INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-physc-em_q1', 'ap-topic-physc-em', 1, false, 'B', 'Gauss Law', 'hard', 'What is the total electric flux through a closed spherical surface containing a point charge $q$?', '["0","$q/\\varepsilon_0$","$q \\varepsilon_0$","\\$4\\pi q$"]'::jsonb, 'Gauss Law states total flux $\Phi_E = Q_{enclosed} / \varepsilon_0$.'),
  ('ap-topic-physc-em_q2', 'ap-topic-physc-em', 2, false, 'A', 'Electricity & Magnetism', 'hard', 'A solid insulating sphere of radius $R$ has a non-uniform volume charge density $\rho(r) = \alpha r$ for $r \le R$, where $\alpha$ is a constant. Using Gauss''s Law, what is the electric field magnitude $E(r)$ inside the sphere ($r < R$)?', '["$E(r) = \\frac{\\alpha r^2}{4\\varepsilon_0}$","$E(r) = \\frac{\\alpha r}{3\\varepsilon_0}$","$E(r) = \\frac{\\alpha r^2}{3\\varepsilon_0}$","$E(r) = \\frac{\\alpha r^3}{4\\varepsilon_0}$"]'::jsonb, 'Construct a concentric spherical Gaussian surface of radius $r < R$. Enclosed charge: $q_{\text{enc}} = \int_0^r \rho(r'') 4\pi r''^2\,dr'' = 4\pi\alpha \int_0^r r''^3\,dr'' = 4\pi\alpha \frac{r^4}{4} = \pi\alpha r^4$. Gauss''s Law: $\oint \vec{E} \cdot d\vec{A} = E(4\pi r^2) = \frac{q_{\text{enc}}}{\varepsilon_0} = \frac{\pi\alpha r^4}{\varepsilon_0}$. Solving for $E$: $E(r) = \frac{\pi\alpha r^4}{4\pi\varepsilon_0 r^2} = \frac{\alpha r^2}{4\varepsilon_0}$.'),
  ('ap-topic-physc-em_q3', 'ap-topic-physc-em', 3, false, 'A', 'Electricity & Magnetism', 'hard', 'A long straight wire of radius $R$ carries a total steady current $I$ distributed with a non-uniform volume current density $J(r) = cr$ for $r \le R$. What is the magnetic field $B(r)$ inside the wire ($r < R$)?', '["$B(r) = \\frac{\\mu_0 I r^2}{2\\pi R^3}$","$B(r) = \\frac{\\mu_0 I r}{2\\pi R^2}$","$B(r) = \\frac{\\mu_0 I r^2}{3\\pi R^3}$","$B(r) = \\frac{\\mu_0 I}{2\\pi r}$"]'::jsonb, 'Total current: $I = \int_0^R J(r'') 2\pi r''\,dr'' = 2\pi c \int_0^R r''^2\,dr'' = \frac{2\pi c R^3}{3} \implies c = \frac{3I}{2\pi R^3}$. For an Amperean loop of radius $r < R$: $I_{\text{enc}} = \int_0^r c r'' (2\pi r'')\,dr'' = \frac{2\pi c r^3}{3} = I \left(\frac{r}{R}\right)^3$. Ampere''s Law: $\oint \vec{B} \cdot d\vec{\ell} = B(2\pi r) = \mu_0 I_{\text{enc}} = \mu_0 I \frac{r^3}{R^3} \implies B(r) = \frac{\mu_0 I r^2}{2\pi R^3}$.'),
  ('ap-topic-physc-em_q4', 'ap-topic-physc-em', 4, false, 'A', 'Electricity & Magnetism', 'hard', 'A thin rod of length $L$ lies along the $x$-axis from $x = 0$ to $x = L$ with uniform charge $Q$. What is the electric potential $V$ at the point $(-d, 0)$ on the $x$-axis, relative to $V(\infty) = 0$?', '["$\\frac{1}{4\\pi\\varepsilon_0}\\frac{Q}{L}\\ln\\left(1 + \\frac{L}{d}\\right)$","$\\frac{1}{4\\pi\\varepsilon_0}\\frac{Q}{d}$","$\\frac{1}{4\\pi\\varepsilon_0}\\frac{Q}{L+d}$","$\\frac{1}{4\\pi\\varepsilon_0}\\frac{Q}{L}\\ln\\left(\\frac{d}{L}\\right)$"]'::jsonb, 'Charge density $\lambda = \frac{Q}{L}$. Consider element $dq = \lambda\,dx$ at coordinate $x$. The distance from element to $(-d, 0)$ is $r = x - (-d) = x + d$. The potential is $V = \frac{1}{4\pi\varepsilon_0}\int_0^L \frac{\lambda\,dx}{x + d} = \frac{\lambda}{4\pi\varepsilon_0}\left[\ln(x + d)\right]_0^L = \frac{Q}{4\pi\varepsilon_0 L}\left[\ln(L + d) - \ln d\right] = \frac{1}{4\pi\varepsilon_0}\frac{Q}{L}\ln\left(\frac{L + d}{d}\right) = \frac{1}{4\pi\varepsilon_0}\frac{Q}{L}\ln\left(1 + \frac{L}{d}\right)$.'),
  ('ap-topic-physc-em_q5', 'ap-topic-physc-em', 5, false, 'A', 'Electricity & Magnetism', 'hard', 'A cylindrical capacitor consists of two concentric conducting cylinders of radii $a$ and $b$ ($a < b$) and length $L \gg b$. What is its capacitance $C$?', '["$C = \\frac{2\\pi\\varepsilon_0 L}{\\ln(b/a)}$","$C = \\frac{2\\pi\\varepsilon_0 L}{b - a}$","$C = \\frac{4\\pi\\varepsilon_0 L}{\\ln(b/a)}$","$C = \\frac{\\pi\\varepsilon_0 L}{\\ln(b/a)}$"]'::jsonb, 'Using Gauss''s Law: $E(r) = \frac{\lambda}{2\pi\varepsilon_0 r}$. The potential difference between cylinders is $\Delta V = \int_a^b E\,dr = \frac{\lambda}{2\pi\varepsilon_0} \ln(b/a)$. Total charge is $Q = \lambda L$. Capacitance is $C = \frac{Q}{\Delta V} = \frac{\lambda L}{\frac{\lambda}{2\pi\varepsilon_0}\ln(b/a)} = \frac{2\pi\varepsilon_0 L}{\ln(b/a)}$.'),
  ('ap-topic-physc-em_q6', 'ap-topic-physc-em', 6, false, 'A', 'Electricity & Magnetism', 'medium', 'In an $RC$ circuit with resistance $R$ and capacitance $C$ connected to an ideal battery of EMF $\mathcal{E}$, what is the charge on the capacitor as a function of time after the switch is closed at $t = 0$?', '["$q(t) = C\\mathcal{E}\\left(1 - e^{-t/RC}\\right)$","$q(t) = C\\mathcal{E} e^{-t/RC}$","$q(t) = \\frac{\\mathcal{E}}{R}\\left(1 - e^{-t/RC}\\right)$","$q(t) = C\\mathcal{E}\\left(1 - e^{-RC/t}\\right)$"]'::jsonb, 'Kirchhoff''s Loop Rule: $\mathcal{E} - iR - \frac{q}{C} = 0$. Substituting $i = \frac{dq}{dt}$: $R\frac{dq}{dt} + \frac{q}{C} = \mathcal{E}$. Solving the first-order linear differential equation with $q(0) = 0$ yields $q(t) = C\mathcal{E}\left(1 - e^{-t/RC}\right)$.'),
  ('ap-topic-physc-em_q7', 'ap-topic-physc-em', 7, false, 'A', 'Electricity & Magnetism', 'hard', 'A conducting rod of length $L$, mass $m$, and resistance $R$ slides frictionlessly along two parallel horizontal conducting rails connected by a zero-resistance wire. A uniform magnetic field $\vec{B}$ points perpendicularly into the page. If the rod is given an initial velocity $v_0$ at $t = 0$, what is its velocity $v(t)$?', '["$v(t) = v_0 e^{-\\frac{B^2 L^2}{m R} t}$","$v(t) = v_0\\left(1 - e^{-\\frac{B^2 L^2}{m R} t}\\right)$","$v(t) = v_0 - \\frac{B^2 L^2}{m R} t$","$v(t) = v_0 e^{-\\frac{BL}{m R} t}$"]'::jsonb, 'Motional EMF $\mathcal{E} = BLv$, producing induced current $I = \frac{\mathcal{E}}{R} = \frac{BLv}{R}$. By Lenz''s Law, the magnetic braking force opposes motion: $F_B = -I L B = -\frac{B^2 L^2}{R} v$. By Newton''s 2nd Law: $m\frac{dv}{dt} = -\frac{B^2 L^2}{R} v \implies \frac{dv}{v} = -\frac{B^2 L^2}{mR} dt$. Integrating: $v(t) = v_0 e^{-\frac{B^2 L^2}{mR} t}$.'),
  ('ap-topic-physc-em_q8', 'ap-topic-physc-em', 8, false, 'A', 'Electricity & Magnetism', 'medium', 'What is the resonant angular frequency $\omega$ of an ideal $LC$ circuit consisting of an inductor $L$ and capacitor $C$?', '["$\\omega = \\frac{1}{\\sqrt{LC}}$","$\\omega = \\sqrt{\\frac{L}{C}}$","$\\omega = \\frac{1}{LC}$","$\\omega = 2\\pi\\sqrt{LC}$"]'::jsonb, 'Kirchhoff''s Loop Rule for an LC loop gives $-L\frac{di}{dt} - \frac{q}{C} = 0$. Since $i = \frac{dq}{dt}$, $L\frac{d^2q}{dt^2} + \frac{1}{C}q = 0 \implies \frac{d^2q}{dt^2} + \frac{1}{LC}q = 0$. Comparing to $\frac{d^2q}{dt^2} + \omega^2 q = 0$ gives $\omega = \frac{1}{\sqrt{LC}}$.'),
  ('ap-topic-physc-em_q9', 'ap-topic-physc-em', 9, false, 'A', 'Electricity & Magnetism', 'hard', 'A circular loop of radius $R$ carries a steady current $I$. Using the Biot-Savart Law, what is the magnetic field magnitude $B$ at the center of the loop?', '["$B = \\frac{\\mu_0 I}{2R}$","$B = \\frac{\\mu_0 I}{2\\pi R}$","$B = \\frac{\\mu_0 I}{4R}$","$B = \\frac{\\mu_0 I}{\\pi R}$"]'::jsonb, 'Biot-Savart Law: $d\vec{B} = \frac{\mu_0 I}{4\pi} \frac{d\vec{\ell} \times \hat{r}}{R^2}$. At the center, $d\vec{\ell} \perp \hat{r}$, so $|d\vec{\ell} \times \hat{r}| = d\ell$. Integrating around the circumference $\oint d\ell = 2\pi R$: $B = \frac{\mu_0 I}{4\pi R^2}(2\pi R) = \frac{\mu_0 I}{2R}$.'),
  ('ap-topic-physc-em_q10', 'ap-topic-physc-em', 10, false, 'A', 'Electricity & Magnetism', 'medium', 'How much energy is stored in the magnetic field of a $4.0\text{ H}$ inductor carrying a steady current of $3.0\text{ A}$?', '["18 J","36 J","12 J","6.0 J"]'::jsonb, 'Energy stored in an inductor is $U_B = \frac{1}{2}L I^2 = \frac{1}{2}(4.0\text{ H})(3.0\text{ A})^2 = 2.0(9.0) = 18\text{ J}$.'),
  ('ap-topic-physc-em_q11', 'ap-topic-physc-em', 11, false, 'A', 'Electricity & Magnetism', 'hard', 'The electric potential in a region of space is given by $V(x, y, z) = 2x^2 y - 3yz^2$. What is the electric field vector $\vec{E}$ at the point $(1, 2, -1)$?', '["$-8\\hat{i} + 1\\hat{j} - 12\\hat{k}$","$8\\hat{i} - 1\\hat{j} + 12\\hat{k}$","$-8\\hat{i} - 7\\hat{j} + 12\\hat{k}$","$-4\\hat{i} + 1\\hat{j} - 6\\hat{k}$"]'::jsonb, 'Electric field is the negative gradient: $\vec{E} = -\nabla V = -\left(\frac{\partial V}{\partial x}\hat{i} + \frac{\partial V}{\partial y}\hat{j} + \frac{\partial V}{\partial z}\hat{k}\right)$. Partial derivatives: $\frac{\partial V}{\partial x} = 4xy$; $\frac{\partial V}{\partial y} = 2x^2 - 3z^2$; $\frac{\partial V}{\partial z} = -6yz$. Evaluating at $(1, 2, -1)$: $\frac{\partial V}{\partial x} = 4(1)(2) = 8$; $\frac{\partial V}{\partial y} = 2(1)^2 - 3(-1)^2 = 2 - 3 = -1$; $\frac{\partial V}{\partial z} = -6(2)(-1) = 12$. Thus $\vec{E} = -[8\hat{i} - 1\hat{j} + 12\hat{k}] = -8\hat{i} + 1\hat{j} - 12\hat{k}$.'),
  ('ap-topic-physc-em_q12', 'ap-topic-physc-em', 12, false, 'A', 'Electricity & Magnetism', 'medium', 'A parallel-plate capacitor with plate area $A$ and separation $d$ is charged to voltage $V$ and then disconnected from the battery. A dielectric slab of dielectric constant $\kappa = 3.0$ is inserted between the plates. What happens to the potential difference between the plates?', '["It decreases to $\\frac{V}{3}$","It increases to $3V$","It remains $V$","It drops to zero"]'::jsonb, 'Since the capacitor is disconnected, the charge $Q$ on the plates is conserved. Inserting the dielectric increases capacitance by factor $\kappa$: $C'' = \kappa C = 3C$. From $V'' = \frac{Q}{C''} = \frac{Q}{3C} = \frac{V}{3}$, the voltage is reduced by a factor of 3.'),
  ('ap-topic-physc-em_q13', 'ap-topic-physc-em', 13, false, 'A', 'Electricity & Magnetism', 'hard', 'A long solenoid of radius $R$ and $n$ turns per unit length carries a time-varying current $I(t) = I_0\cos(\omega t)$. What is the induced electric field magnitude $E(r)$ at a distance $r < R$ from the central axis?', '["$E(r) = \\frac{1}{2}\\mu_0 n I_0 \\omega r \\sin(\\omega t)$","$E(r) = \\mu_0 n I_0 \\omega r \\sin(\\omega t)$","$E(r) = \\frac{1}{2}\\mu_0 n I_0 \\omega \\frac{R^2}{r} \\sin(\\omega t)$","$E(r) = 0$"]'::jsonb, 'Inside the solenoid, $B(t) = \mu_0 n I(t) = \mu_0 n I_0 \cos(\omega t)$. Magnetic flux through a circle of radius $r < R$ is $\Phi_B = B \pi r^2 = \pi r^2 \mu_0 n I_0 \cos(\omega t)$. Faraday''s Law: $\oint \vec{E} \cdot d\vec{\ell} = E(2\pi r) = -\frac{d\Phi_B}{dt} = \pi r^2 \mu_0 n I_0 \omega \sin(\omega t) \implies E(r) = \frac{1}{2}\mu_0 n I_0 \omega r \sin(\omega t)$.'),
  ('ap-topic-physc-em_q14', 'ap-topic-physc-em', 14, false, 'A', 'Electricity & Magnetism', 'medium', 'In an $RL$ circuit connected to battery $\mathcal{E}$ through a switch, what is the inductive time constant $\tau_L$?', '["$\\tau_L = \\frac{L}{R}$","$\\tau_L = R L$","$\\tau_L = \\frac{R}{L}$","$\\tau_L = \\frac{1}{\\sqrt{LR}}$"]'::jsonb, 'Kirchhoff''s loop equation $L\frac{di}{dt} + Ri = \mathcal{E}$ has characteristic time scale $\tau_L = \frac{L}{R}$ (in seconds).'),
  ('ap-topic-physc-em_q15', 'ap-topic-physc-em', 15, false, 'A', 'Electricity & Magnetism', 'hard', 'What is the electrostatic potential energy $U$ required to assemble three identical point charges $+q$ at the vertices of an equilateral triangle of side length $a$ in empty space?', '["$U = \\frac{3 q^2}{4\\pi\\varepsilon_0 a}$","$U = \\frac{q^2}{4\\pi\\varepsilon_0 a}$","$U = \\frac{3 q^2}{8\\pi\\varepsilon_0 a}$","$U = \\frac{6 q^2}{4\\pi\\varepsilon_0 a}$"]'::jsonb, 'Total assembly work is the sum over all unique pairwise interactions: $U = U_{12} + U_{13} + U_{23} = \frac{1}{4\pi\varepsilon_0}\left(\frac{q^2}{a} + \frac{q^2}{a} + \frac{q^2}{a}\right) = \frac{3q^2}{4\pi\varepsilon_0 a}$.'),
  ('ap-topic-physc-em_q16', 'ap-topic-physc-em', 16, false, 'A', 'Electricity & Magnetism', 'hard', 'A proton (charge $+e$, mass $m$) enters a region with uniform electric field $\vec{E} = E_0\hat{j}$ and uniform magnetic field $\vec{B} = B_0\hat{k}$ moving along the $+x$-direction. What speed $v$ allows the proton to pass undeflected?', '["$v = \\frac{E_0}{B_0}$","$v = \\frac{B_0}{E_0}$","$v = \\sqrt{\\frac{E_0}{B_0}}$","$v = E_0 B_0$"]'::jsonb, 'For zero net deflection, electric and magnetic forces must balance: $\vec{F} = q(\vec{E} + \vec{v} \times \vec{B}) = 0$. Here $\vec{F}_E = qE_0\hat{j}$, and $\vec{F}_B = q(v\hat{i} \times B_0\hat{k}) = -qvB_0\hat{j}$. Setting magnitudes equal: $qE_0 = qvB_0 \implies v = \frac{E_0}{B_0}$ (the velocity selector condition).'),
  ('ap-topic-physc-em_q17', 'ap-topic-physc-em', 17, false, 'A', 'Electricity & Magnetism', 'medium', 'What is the equivalent capacitance of two capacitors $C_1 = 3\,\mu\text{F}$ and $C_2 = 6\,\mu\text{F}$ connected in series?', '["$2.0\\,\\mu\\text{F}$","$9.0\\,\\mu\\text{F}$","$4.5\\,\\mu\\text{F}$","$1.5\\,\\mu\\text{F}$"]'::jsonb, 'For capacitors in series: $\frac{1}{C_{\text{eq}}} = \frac{1}{C_1} + \frac{1}{C_2} = \frac{1}{3} + \frac{1}{6} = \frac{3}{6} = \frac{1}{2.0} \implies C_{\text{eq}} = 2.0\,\mu\text{F}$.'),
  ('ap-topic-physc-em_q18', 'ap-topic-physc-em', 18, false, 'A', 'Electricity & Magnetism', 'hard', 'A flat square coil of side length $a = 0.20\text{ m}$ with $N = 50$ turns is placed in a uniform magnetic field perpendicular to the coil plane. The magnetic field increases linearly from $0.10\text{ T}$ to $0.70\text{ T}$ in $0.30\text{ s}$. What is the magnitude of the induced EMF in the coil?', '["4.0 V","2.0 V","8.0 V","0.40 V"]'::jsonb, 'Area $A = a^2 = (0.20)^2 = 0.040\text{ m}^2$. Rate of change of magnetic field is $\frac{\Delta B}{\Delta t} = \frac{0.70 - 0.10}{0.30} = \frac{0.60}{0.30} = 2.0\text{ T/s}$. By Faraday''s Law: $|\mathcal{E}| = N A \left|\frac{\Delta B}{\Delta t}\right| = 50(0.040)(2.0) = 4.0\text{ V}$.'),
  ('ap-topic-physc-em_q19', 'ap-topic-physc-em', 19, false, 'A', 'Electricity & Magnetism', 'medium', 'How does the electric field magnitude $E$ scale with distance $r$ from an infinitely long line of uniform linear charge density $\lambda$?', '["$E \\propto \\frac{1}{r}$","$E \\propto \\frac{1}{r^2}$","$E \\propto \\frac{1}{r^3}$","$E$ is constant independent of $r$"]'::jsonb, 'Applying Gauss''s Law to a cylindrical Gaussian surface gives $E(2\pi r L) = \frac{\lambda L}{\varepsilon_0} \implies E(r) = \frac{\lambda}{2\pi\varepsilon_0 r} \propto \frac{1}{r}$.'),
  ('ap-topic-physc-em_q20', 'ap-topic-physc-em', 20, false, 'A', 'Electricity & Magnetism', 'hard', 'What correction did James Clerk Maxwell introduce to Ampere''s Law to account for time-varying electric fields?', '["Displacement current: $\\mu_0 \\varepsilon_0 \\frac{d\\Phi_E}{dt}$","Motional EMF: $-\\frac{d\\Phi_B}{dt}$","Poynting vector flux: $\\frac{1}{\\mu_0}(\\vec{E} \\times \\vec{B})$","Dielectric polarization current: $\\kappa \\frac{dI}{dt}$"]'::jsonb, 'Maxwell added the displacement current term $I_d = \varepsilon_0 \frac{d\Phi_E}{dt}$ to Ampere''s Law, completing the Maxwell-Ampere Law: $\oint \vec{B} \cdot d\vec{\ell} = \mu_0 I_{\text{enc}} + \mu_0 \varepsilon_0 \frac{d\Phi_E}{dt}$, which resolved charge conservation in capacitors and predicted electromagnetic waves.'),
  ('ap-diag-physc-em_q1', 'ap-diag-physc-em', 1, false, 'C', 'Diagnostic Test – E&M', 'medium', 'Two isolated metal spheres with radii r1 and r2 (with r1 != r2) carrying positive charges Q1 and Q2, respectively, are separated by a very large distance. A thin conducting wire is then connected between the two spheres. Under what condition will positive charge flow from sphere 1 to sphere 2?', '["Q1 > Q2","r1 > r2","Q1 / r1 > Q2 / r2","Q1 r1 > Q2 r2","Q1 / r1^2 > Q2 / r2^2"]'::jsonb, 'Positive charge flows spontaneously from a region of higher electric potential to one of lower electric potential. The electric potential at the surface of an isolated conducting sphere of radius r carrying charge Q is V = (1 / (4 pi epsilon_0)) * (Q / r). Thus, positive charge flows from sphere 1 to sphere 2 if and only if V1 > V2, which requires Q1 / r1 > Q2 / r2.'),
  ('ap-diag-physc-em_q2', 'ap-diag-physc-em', 2, false, 'C', 'Diagnostic Test – E&M', 'medium', 'A charged particle is launched into a region of uniform magnetic field. Given that the particle’s initial velocity has components parallel and perpendicular to the magnetic field, describe the particle’s path qualitatively.', '["a straight line","a circle","a helical (corkscrew) path","a parabolic path","none of the above"]'::jsonb, '(C) See the discussion of the motion of particles within magnetic fields in Chapter 14.'),
  ('ap-diag-physc-em_q3', 'ap-diag-physc-em', 3, false, 'B', 'Diagnostic Test – E&M', 'medium', 'A point charge +Q is located at a fixed distance from a sphere. Compare the magnitude of the attractive force on the sphere if the sphere is (1) metal with net charge −Q, (2) metal with no net charge, (3) an insulator with net charge −Q, or (4) an insulator with no net charge.', '["charged metal = charged insulator > uncharged metal = uncharged insulator","charged metal > charged insulator > uncharged metal > uncharged insulator","charged insulator > charged metal > uncharged insulator > uncharged metal","charged insulator > charged metal > uncharged metal = uncharged insulator","charged insulator = charged metal > uncharged metal > uncharged insulator"]'::jsonb, '(B) This is a question about electrostatic induction. When a positive point charge is placed near a metal sphere (charged or uncharged), it attracts mobile electrons in the metal, causing the metal to become polarized such that more negative charge is on the side closer to the positive point charge and more positive charge is on the side farther away from the positive point charge. Because this charge redistribution results in moving negative charge closer to the positive point charge and moving positive charge farther away from the positive point charge, it increases the attractive force between the metal sphere and the positive point charge. Therefore, compared to an insulating sphere with the same net charge, a metal sphere always experiences a greater attractive force (such that charged metal > charged insulator and uncharged metal > uncharged insulator). Because this inductive effect is small compared to the effect of actually putting net charge −Q on the sphere, charged insulator > uncharged metal.'),
  ('ap-diag-physc-em_q4', 'ap-diag-physc-em', 4, false, 'C', 'Diagnostic Test – E&M', 'medium', 'A bar moves to the right through a magnetic field as shown (the magnetic field points into the page). What is the potential difference between points A and B after equilibrium is established in the bar?', '["The difference is v2Bd, with A at higher potential.","The difference is v2Bd, with B at higher potential.","The difference is vBd, with A at higher potential.","The difference is vBd, with B at higher potential.","Because there is no loop, there is no flux, so there is no potential difference."]'::jsonb, '(C) The charges within the bar are moving in a magnetic field, so they feel a magnetic force. Using the conventional-current description, positive charges feel an upward force, causing positive charge to accumulate at the top end of the bar (leaving negative charge on the bottom end of the bar). This charge continues to accumulate until the electric force created by the charge imbalance cancels the magnetic force, mathematically qE = qvB. The magnitude of the potential difference between points A and B is then |V | = |−\int E \cdot  dr| = |vBd|. The electric field points down (producing a force that opposes the magnetic force), and recalling that electric fields point from high to low potential, we see that point A is at the higher potential. Further information about motional EMF can be found in Example 15.6.'),
  ('ap-diag-physc-em_q5', 'ap-diag-physc-em', 5, false, 'B', 'Diagnostic Test – E&M', 'medium', 'Suppose that the electric potential in a region of space is a constant. What can you conclude about the magnitude of the electric field in this region?', '["It is a nonzero constant.","It is zero.","It is proportional to the distance from the origin.","It is given by","Not enough information is given. Questions 6–8 refer to a circular region of radius a with a uniform magnetic field pointing into the page that is increasing at a constant rate as shown. A circular loop of wire of radius r is centered on the middle of the region."]'::jsonb, '(B) The electric field is the negative derivative (with respect to the spatial coordinate) of the potential. Thus, with a constant potential the electric field must be zero.'),
  ('ap-diag-physc-em_q6', 'ap-diag-physc-em', 6, false, 'C', 'Diagnostic Test – E&M', 'medium', 'Which of the graphs plots the induced EMF in the circular loop of wire shown as a function of its radius r?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(C) The induced EMF depends on the change in the enclosed flux. Because the magnetic field is uniform, and changing at a constant rate, Therefore, the induced EMF depends only on the area of the loop through which magnetic field lines pass. For r < a, the area within the loop exposed to the magnetic field is simply the entire area of the loop, which is a quadratic function, A(r) = \pir2. For r > a, increasing r does not increase the area exposed to the magnetic field (because the magnetic field through the additional area is zero). Therefore, for r > a the induced EMF is constant. The only graph that is quadratic for small r and then constant is choice (C). Calculating the induced EMF due to a magnetic field via Faraday’s law is discussed in Chapter 15.'),
  ('ap-diag-physc-em_q7', 'ap-diag-physc-em', 7, false, 'A', 'Diagnostic Test – E&M', 'medium', 'Given that the resistance of the loop is proportional to the loop’s circumference, which of the graphs seen in question 6 shows the induced current as a function of the radius of the loop?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(A) The current is given by I = V/R. The resistance is proportional to the circumference of the loop, 2\pir. Therefore, for r < a, V is proportional to r2 (as discussed in question 6), and 1/R is proportional to 1/r, so the product I = V/R is proportional to r (and thus its graph is a line passing through the origin). For r > a, V is constant and 1/R is proportional to 1/r, so the product I = V/R is inversely proportional to r. The only graph that satisfies these conditions is choice (A).'),
  ('ap-diag-physc-em_q8', 'ap-diag-physc-em', 8, false, 'A', 'Diagnostic Test – E&M', 'medium', 'A long straight cylindrical wire of radius a carries a constant total current I uniformly distributed over its circular cross section. What is the magnetic field magnitude B(r) as a function of radial distance r from the central axis of the wire for both r <= a and r >= a?', '["B(r) is proportional to r for r <= a, and proportional to 1/r for r >= a","B(r) is zero for r <= a, and proportional to 1/r for r >= a","B(r) is proportional to 1/r for r <= a, and constant for r >= a","B(r) is proportional to r^2 for r <= a, and proportional to 1/r^2 for r >= a","B(r) is constant everywhere inside and outside the wire"]'::jsonb, 'Apply Ampere''s Law oint B * dl = mu_0 I_enc. Inside the wire (r <= a), the enclosed current is I_enc = I * (pi r^2) / (pi a^2) = I (r/a)^2, giving B(2 pi r) = mu_0 I (r/a)^2 ==> B(r) = (mu_0 I / (2 pi a^2)) * r (linear in r). Outside the wire (r >= a), the entire current I is enclosed, so B(2 pi r) = mu_0 I ==> B(r) = mu_0 I / (2 pi r) (inversely proportional to r).'),
  ('ap-diag-physc-em_q9', 'ap-diag-physc-em', 9, false, 'E', 'Diagnostic Test – E&M', 'medium', 'The magnitude of the electric field inside a uniformly charged spherical shell', '["depends on the charge of the shell","depends on the radius of the shell","depends on the distance from the center of the sphere, r","depends on the permittivity of free space, \\epsilon0","is equal to the integral , where is a unit vector pointing from the differential charge dQ to the point in space (within the sphere) where the electric field is being measured"]'::jsonb, '(E) According to Gauss’s law (Chapter 11), the electric field inside a hollow sphere is zero because there is no enclosed charge. Therefore, the electric field is independent of the charge of the shell, the radius of the shell, the radial coordinate, and the permittivity of free space; it is zero inside the sphere independent of any of these factors. Note that the electric field is always given by the equation in choice (E).'),
  ('ap-diag-physc-em_q10', 'ap-diag-physc-em', 10, false, 'C', 'Diagnostic Test – E&M', 'medium', 'If a battery requires an amount of time t to charge a capacitor to 60% of its final charge, what is the time constant of the circuit?', '["\\tau = −t/ln(0.6)","\\tau = −ln(0.6)/t","\\tau = −t/ln(0.4)","\\tau = −ln(0.4)/t","cannot be determined from the information given"]'::jsonb, '(C) Setting the equation for Q(t) equal to 60% of its final value yields Solving for \tau then yields choice (C). Further information about RC circuits can be found in Chapter 13.'),
  ('ap-diag-physc-em_q11', 'ap-diag-physc-em', 11, false, 'C', 'Diagnostic Test – E&M', 'medium', 'Which of the following statements is true of the integral', '["It is equal to the potential at point B minus the potential at point A.","It is always independent of the path taken from point A to point B.","It is the work per unit charge that the electric field performs as a charge moves from point A to point B.","It is the work per unit charge that an external force performs to move a charge from point A to point B.","It is the induced EMF."]'::jsonb, '(C) Choice (A) is false: The potential at point B minus the potential at point A is given by . Choice (B) is false: The integral is path independent only if there is no time-dependent magnetic field present. A time-dependent magnetic field produces a nonconservative electric force with no associated potential function. Choice (C) is true: The work per charge is the opposite of the change in potential energy per charge, which is equal to because of conservation of energy. Choice (D) is false: The work done by an arbitrary external force does not necessarily have any relationship with the electric field. Although choice (E) is true in the special case that the integral is a closed loop, that is, point A = point B, it is not true in general.'),
  ('ap-diag-physc-em_q12', 'ap-diag-physc-em', 12, false, 'A', 'Diagnostic Test – E&M', 'medium', 'A wire loop lies partially in a region where the magnetic field points out of the page, as shown. If the magnetic field is increasing in magnitude, what is the direction of the force on the loop?', '["to the right","to the left","out of the page","toward the top of the page","The force is zero."]'::jsonb, '(A) The current induced in the loop moves in a clockwise direction to oppose the increasing outward flux through the loop according to Lenz’s law. The movement of this current through the top and bottom of the loop creates opposing forces that cancel each other, while the current flowing through the left side of the loop produces a force to the right, which equals the net force on the loop.'),
  ('ap-diag-physc-em_q13', 'ap-diag-physc-em', 13, false, 'E', 'Diagnostic Test – E&M', 'medium', 'Suppose that, rather than an electron orbiting a proton as in atoms, an electron and a positron (a particle with the same mass as an electron and of opposite charge) orbit each other as shown. In terms of the magnitude of the charge on an electron e and the radius of the orbit r, what is the total kinetic energy of the system?', '["KE = e/4\\pi\\epsilon0r","KE = e 2/4\\pi\\epsilon0r 2","KE = −e 2/8\\pi\\epsilon0r 2","KE = −e 2/8\\pi\\epsilon0r","KE = e 2/16\\pi\\epsilon0r"]'::jsonb, '(E) Without doing a lot of work, we can eliminate most of the choices. First, kinetic energy is always positive, so choices (C) and (D) are incorrect. Second, recall the formula for the potential energy of two point charges separated by a distance r (ignoring signs for now): Comparing the form of this expression with our choices allows us to eliminate choices (A), (B), and (C) simply on the basis of dimensional analysis. This leaves us only choice (E), which a detailed calculation shows is the correct answer.'),
  ('ap-diag-physc-em_q14', 'ap-diag-physc-em', 14, false, 'C', 'Diagnostic Test – E&M', 'medium', 'Which one of Maxwell’s equations states the experimental result that physicists have been unable to discover a magnetic monopole?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(C) See Chapter 15 for a further explanation of Gauss’s law for magnetism.'),
  ('ap-diag-physc-em_q15', 'ap-diag-physc-em', 15, false, 'C', 'Diagnostic Test – E&M', 'medium', 'Two resistors with different resistances are connected in parallel. Which of the following statements is correct about this resistor network?', '["The equivalent resistance is greater than the resistance of either of the resistors alone.","The equivalent resistance is in between the resistance of either of the resistors alone.","The equivalent resistance is smaller than the resistance of either of the resistors alone.","The same amount of current passes through both resistors.","The equivalent resistance depends on the potential difference across the resistor array."]'::jsonb, '(C) The equivalent resistance is given by Because the denominator is greater than 1/R1 or 1/R2 alone, the entire fraction must be smaller than R1 or R2 alone. Choice (D) is incorrect: The voltage across the resistors must be the same because they are arranged in parallel. Therefore, the current through either resistor is given by the equation I = V/R. Because the resistors have different resistances, different amounts of current flow through them. The equivalent resistance of a resistor array is a physical property of the array itself (just as the resistance of a resistor is a physical property of the resistor). So it is independent of the voltage across the array (assuming, of course, that the resistors obey Ohm’s law), eliminating choice (E).'),
  ('ap-diag-physc-em_q16', 'ap-diag-physc-em', 16, false, 'D', 'Diagnostic Test – E&M', 'medium', 'The uniform electric field established between the parallel plates of a capacitor has magnitude E. A particle with a charge of magnitude q is released (initially at rest) somewhere between the plates and allowed to move a distance d under the influence of the capacitor’s electric field. What is the change in the particle’s electrostatic potential energy?', '["\\Delta U = q 2Ed","\\Delta U = −q 2Ed","\\Delta U = qEd","\\Delta U = −qEd","none of the above"]'::jsonb, '(D) First, what is the sign of the change in energy? This is a tricky question because the actual sign of the charge and the direction of the electric field are not given. Recall that Fx = −dU/dx. Thus, a particle always feels a force pushing it in a direction that decreases the particle’s potential energy. Therefore, whether the particle’s charge is positive or negative, it always moves in such a way as to decrease its potential energy, so \Delta U < 0. This eliminates choices (A) and (C). What, then, is the magnitude of the decrease in potential energy? The key equation here is \Delta U = q\Delta V (based on the definition of potential). Because the particle moves parallel or antiparallel to the electric field (depending on the sign of its charge), |\Delta V| = |−\int E ⋅ dr| = Ed. Therefore, the magnitude of the change in potential energy is |\Delta U| = |q\Delta V| = qEd, so choice (D) is correct.'),
  ('ap-diag-physc-em_q17', 'ap-diag-physc-em', 17, false, 'B', 'Diagnostic Test – E&M', 'medium', 'An isolated solid metal sphere contains a net charge of +Q. The magnitude of the electric field outside the sphere a distance d from the center of the sphere', '["cannot be calculated because there isn’t appropriate symmetry to apply Gauss’s law","is equal to Q/4\\pi\\epsilon0d 2","is equal to Q/2\\pi\\epsilon0d 2","is equal to","none of the above"]'::jsonb, '(B) Based on Gauss’s law, the enclosed charge term, qenclosed, depends only on the magnitude of the charge and the symmetry properties of its distribution. Therefore, the field produced outside a charged sphere is the same as the field that would be produced if all the charge of the sphere were concentrated at a point at the sphere’s center (which is easily calculated using Coulomb’s law). Note that a charge placed on an isolated conducting sphere distributes itself uniformly across the surface of the sphere. Further information about Gauss’s law and the distribution of a stationary charge along conductors is given in Chapter 11.'),
  ('ap-diag-physc-em_q18', 'ap-diag-physc-em', 18, false, 'C', 'Diagnostic Test – E&M', 'medium', 'Point P is located within a cylindrical wire that carries current into the page with uniform current density as shown. What is the direction of the magnetic field at point P?', '["The magnetic field is zero because of symmetry.","toward the top of the page","toward the bottom of the page","into the page","out of the page"]'::jsonb, '(C) According to Ampere’s law and the symmetry of the situation, the only current that determines the magnetic field at point P is the current enclosed within the amperian path shown. (Thus, the current in region B has no effect on the magnetic field at point P.) The magnetic field produced at P due to the enclosed current is the same as the field produced by a thin wire along the axis of the cylinder, carrying the same current (since the magnetic field depends on only the enclosed current as long as it has cylindrical symmetry). The right-hand rule indicates that this imaginary current-carrying wire would produce a downward magnetic field at point P, so the same downward magnetic field must be produced by the entire cylinder of current featured in this problem. For further information about calculating magnetic fields using Ampere’s law, see Chapter 14.'),
  ('ap-diag-physc-em_q19', 'ap-diag-physc-em', 19, false, 'E', 'Diagnostic Test – E&M', 'medium', 'A point charge +q lies at the origin. Which of the following charge distributions could yield a zero net electric field (due to the +q charge and the charge distribution) at the point (0, 1)? I. a single charge −Q with a smaller magnitude than +q, lying at some point along the x-axis II. a single charge −q with a magnitude equal to +q, lying at some point along the x-axis III. a single charge −Q with a larger magnitude than +q, lying at some point along the x-axis IV. two charges both with charge −Q and with larger magnitudes than +q, lying at points along the x-axis', '["II","III","IV","I and III","II and IV"]'::jsonb, '(E) Distribution I will not be able to cancel the electric field due to +q because it will never be able to achieve a high enough magnitude. Distribution II will work: Simply locate the charge −q at the origin, and it will exactly cancel out the field due to +q over all space. Distribution III will never be able to have an equal magnitude and opposite direction compared to the field due to +q; in order to have an opposite direction the negative charge must be located at the origin, but at this point it will produce a stronger magnitude field than the field due to +q. Distribution IV will definitely work. The charges must be located equal distances from the origin in order for the field due to both of the negative charges to be in the direction opposite the field due to +q. By moving the charges as far away from the origin as is necessary, the magnitude of the field can be adjusted so as to exactly equal the magnitude of the field due to +q.'),
  ('ap-diag-physc-em_q20', 'ap-diag-physc-em', 20, false, 'D', 'Diagnostic Test – E&M', 'medium', 'After closing the switch in the figure, the current I passing through the inductor increases from zero. What is the Kirchhoff’s loop equation describing this situation?', '["V + IR + L(dI/dt) = 0","V + IR − L(dI/dt) = 0","V − IR + L(dI/dt) = 0","V − IR − L(dI/dt) = 0","none of the above"]'::jsonb, '(D) Tracing the loop in the counterclockwise direction: (1) The sign of the potential jump of the battery is positive because we are going from the negative terminal to the positive terminal. (2) The sign of the potential jump across the resistor is negative because we are going in the same direction as the current. (3) The sign of the potential jump across the inductor is negative. Why? The inductor opposes the increase in the current, so its potential jump must be of the opposite sign compared to that of the battery (which has a positive potential jump). Because current is increasing, dI/dt > 0, we must add a negative sign to the term −L(dI/dt) in order for it to have an overall negative value as required.'),
  ('ap-diag-physc-em_q21', 'ap-diag-physc-em', 21, false, 'A', 'Diagnostic Test – E&M', 'medium', 'A battery has an EMF of 9 V and an internal resistance of 20 Ω. For what value of current will the terminal voltage across the battery be 7 V?', '["0.1 A","0.2 A","5 A","10 A","40 A"]'::jsonb, '(A) When the terminal voltage is 7 V, that means that there is a 2 V potential drop across the internal resistance. Applying Ohm’s law to the internal resistance yields I = V/R = 2 V/20 Ω = 0.1 A.'),
  ('ap-diag-physc-em_q22', 'ap-diag-physc-em', 22, false, 'B', 'Diagnostic Test – E&M', 'medium', 'Consider a parallel plate vacuum capacitor. If the plate area and the separation distance are doubled and a dielectric with dielectric constant kD = 2 is inserted between the plates, completely filling the space, the capacitance will', '["increase by a factor of 4","increase by a factor of 2","remain the same","decrease by a factor of 2","decrease by a factor of 4"]'::jsonb, '(B) This problem relies on manipulation of the equation for the capacitance of a parallel plate capacitor with a dielectric, C = \epsilon0AkD /d. Increasing A, d, and kD by factors of 2 results in a net increase of capacitance by a factor of 2.'),
  ('ap-diag-physc-em_q23', 'ap-diag-physc-em', 23, false, 'C', 'Diagnostic Test – E&M', 'medium', 'How much work is done by the electric field on a point charge of magnitude q moved from infinity into the center of a hollow spherical shell of radius R that has a uniform charge density and a net charge of +Q? (Assume there is a very small hole in the shell that allows the point charge to enter but does not disturb the spherical symmetry of the charge distribution.)', '["W = qQ/4\\pi\\epsilon0R","W = qQ/4\\pi\\epsilon0R2","W = −qQ/4\\pi\\epsilon0R","The work is undefined.","The work is zero because of symmetry considerations."]'::jsonb, '(C) The potential at the surface of the sphere is the same as if all of the charge were concentrated at the center of the sphere, that is, V = (1/4\pi\epsilon0)(Q/R) as discussed in question 1. The electric field inside the sphere is zero, so the potential at the center is the same as its value at the surface. The work done by the electric field to move the charge from infinity to this point is the negative of the change in the charge’s potential energy: W = −\Delta U = −q\Delta V = −q(Q/4\pi\epsilon0R).'),
  ('ap-diag-physc-em_q24', 'ap-diag-physc-em', 24, false, 'D', 'Diagnostic Test – E&M', 'medium', 'Which unit is equal to one ohm divided by one henry?', '["coulomb","joule","second","second−1","farad"]'::jsonb, '(D) The time constant of an RL circuit is \tau = L/R. Because the time constant has units of time, R/L has the units of inverse time. Alternative solution: Recall that the voltage drop across an inductor is V = L(dI/dt) and the voltage drop across a resistor is V = IR. Equating the units of voltage in these two formulas, V = IR = L(dI/dt). Manipulating this formula in terms of units yields L/R = I(dt/dI) = t. (Note that dt has the units of time and dI has the units of current.)'),
  ('ap-diag-physc-em_q25', 'ap-diag-physc-em', 25, false, 'D', 'Diagnostic Test – E&M', 'medium', 'Suppose that when a charge is moved through a region of space with an electric field (which is produced by stationary charges), the field does no net work on the charge. Which of the following statements must be true?', '["The electric force is nonconservative.","The charge’s path begins and ends along the same electric field line.","The charge is moved along an equipotential line.","The charge’s path begins and ends on an equipotential line of the same value.","Electric fields never do work on charges."]'::jsonb, '(D) Choice (C) would indeed result in no net work being done (no work is required to move a charge along an equipotential line). However, this is not required for zero net work to be done: It is possible that the field might perform negative work along part of the charge’s path and positive work along the remainder of the path such that the net work is zero. The only condition that is required for zero net work to be done is for the charge to begin and end at the same voltage (so that the change in potential energy is zero, based on the definition of voltage), so choice (D) is correct. Choice (E) is true of magnetic fields, not electric fields, since the magnetic force is always perpendicular to the velocity. Choice (B) won’t generally satisfy the requirement that no net work be done, except in the special case that the path begins and ends at the same point on the field line. In fact, any path that begins and ends at different points along an electric field line must have involved the electric field performing net work because electric field lines are parallel to the electric field and such movement causes a change in voltage. Choice (A) is false: Stationary charges always produce conservative electric forces.'),
  ('ap-diag-physc-em_q26', 'ap-diag-physc-em', 26, false, 'E', 'Diagnostic Test – E&M', 'medium', 'Consider a long solenoid with length l, radius r, and n turns per length. What effect will doubling the radius (while holding l and n constant) have on the inductance of the solenoid?', '["Inductance will decrease by a factor of 4.","Inductance will decrease by a factor of 2.","Inductance will not change.","Inductance will increase by a factor of 2.","Inductance will increase by a factor of 4."]'::jsonb, '(E) Based on the formula for the magnetic field within a solenoid (which can be quickly derived using Ampere’s law), B = \mu0nI. Because the radius of the solenoid does not enter this equation, changing the radius will not affect the strength of the magnetic field within the solenoid. However, because increasing the radius will increase the area of each loop of the solenoid by a factor of 4 (because A = \pir2), it will increase the magnetic flux through each loop by a factor of 4 and thus increase the inductance by a factor of 4.'),
  ('ap-diag-physc-em_q27', 'ap-diag-physc-em', 27, false, 'C', 'Diagnostic Test – E&M', 'medium', 'In the circuit shown, if the potential at point A is chosen to be zero, what is the potential at point B?', '["4 V","2.5 V","−2.5 V","−4 V","none of the above"]'::jsonb, '(C) First, constructing and solving a Kirchhoff’s loop equation indicates that the current is 0.5 A flowing in a clockwise direction. More specifically, one valid loop equation is (choosing to designate positive current in the clockwise direction and traversing the loop in the clockwise direction): (Alternatively, you could realize that the circuit has an equivalent resistance of 4 Ω and an equivalent voltage of 2 V, so applying Ohm’s law indicates that the current is 0.5 A.) Then, to calculate the potential at point B, begin at point A and sum potential jumps as you move to point B. (Use either of the possible two pathways. If the current is solved correctly, you should obtain the same answer either way.) For example, moving along the bottom of the circuit yields'),
  ('ap-diag-physc-em_q28', 'ap-diag-physc-em', 28, false, 'A', 'Diagnostic Test – E&M', 'medium', 'What is the power dissipated in the resistors in the circuit introduced in question 27?', '["Directly proportional to the parameter (linear scaling)","2 W","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","16 W Questions 29–31 refer to the circuits shown in the figure, in which all the batteries are identical."]'::jsonb, '(A) The power dissipated by a resistor is P = I2R, and because the resistors are in series, they share a common current. Therefore, the power dissipated by all the resistors is . (Note that this is equivalent to realizing that the equivalent resistance of the circuit is 4 Ω and plugging this value into the formula P = I2R.)'),
  ('ap-diag-physc-em_q29', 'ap-diag-physc-em', 29, false, 'B', 'Diagnostic Test – E&M', 'medium', 'In which circuit is the equivalent resistance the greatest?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(B) Application of the equivalent resistance formulas reveals that the equivalent resistance of circuits (A) through (E) are 3 Ω, 6 Ω, 4 Ω, 2 Ω, and 5 Ω.'),
  ('ap-diag-physc-em_q30', 'ap-diag-physc-em', 30, false, 'D', 'Diagnostic Test – E&M', 'medium', 'In which of the five circuits is the total power dissipated by all the resistors the greatest?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(D) The most useful formula to use here for power is P = V2/R. The circuit with the lowest equivalent resistance dissipates the greatest total power. (Remember, the voltage is the same for all circuits.)')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-diag-physc-em_q31', 'ap-diag-physc-em', 31, false, 'B', 'Diagnostic Test – E&M', 'medium', 'A real battery of EMF V0 and non-zero internal resistance r is connected across an external load resistor R. Under which of the following conditions is the potential difference across the load resistor R minimized?', '["When R is much greater than r (R >> r)","When R is much smaller than r (R << r)","When R equals r (R = r)","When R is disconnected (open circuit)","The potential difference is always equal to V0 regardless of R"]'::jsonb, 'The current in the single loop circuit is I = V0 / (R + r). The potential difference across the load resistor R is V_R = I R = V0 * R / (R + r) = V0 / (1 + r/R). As R approaches 0 (R << r), V_R approaches 0. When R >> r, V_R approaches V0. Therefore, V_R is minimized when R << r.'),
  ('ap-diag-physc-em_q32', 'ap-diag-physc-em', 32, false, 'D', 'Diagnostic Test – E&M', 'medium', 'Which of the following statements is a necessary condition for the electric flux through a gaussian surface to be zero?', '["The electric field is zero along the entire gaussian surface.","The component of the field perpendicular to the gaussian surface is zero along the entire gaussian surface.","There is no charge enclosed within the gaussian surface.","There is no net charge enclosed within the gaussian surface.","Although the above conditions would cause the flux to be zero, they are not required for the flux to be zero."]'::jsonb, '(D) According to Gauss’s law, the electric flux is proportional to the net enclosed charge, so if the flux is zero, the net enclosed charge must be zero. The conditions in choices (A) and (B) would cause the local flux at any point on the gaussian surface to be zero, which would indeed cause the net flux to be zero. However, these are not required for the net flux to be zero: It is possible that positive flux through part of the gaussian surface cancels negative flux through another part of the gaussian surface such that the net flux is zero. Like choices (A) and (B), choice (C) would indeed result in the flux through the gaussian surface being zero. However, again this is not required for the net flux to be zero. It would be possible for a surface to enclose equal amounts of positive and negative charge such that the net enclosed charge and flux are zero. Further discussion of Gauss’s law can be found in Chapter 11.'),
  ('ap-diag-physc-em_q33', 'ap-diag-physc-em', 33, false, 'D', 'Diagnostic Test – E&M', 'medium', 'Two moving particles of equal mass enter a region of uniform magnetic field pointing out of the page, causing them to move as shown. Which of the following is true about the charges on these particles?', '["|QA| > |QB|, QA > 0","|QA| > |QB|, QA < 0","|QA| < |QB|, QA > 0","|QA| < |QB|, QA < 0","none of the above"]'::jsonb, '(D) The magnetic field provides the centripetal force for the circular motion shown, according to the equation qvB = mv2/r. Because v, m, and B are fixed and shared by both particles, q is inversely proportional to r. Therefore, particle B, which follows a path of smaller radius, must have a greater magnitude of charge. The sign of the charge on particle A can be determined by the right-hand rule to be negative. (Remember that the centripetal force must always point toward the center of the arc.)'),
  ('ap-diag-physc-em_q34', 'ap-diag-physc-em', 34, false, 'D', 'Diagnostic Test – E&M', 'medium', 'Given the electric field vector at a point in space, which of the following can be determined? I. the direction of the electric force on any charged particle (of unspecified charge) at that point II. the magnitude of the electric force on a particle with a charge of magnitude Q at that point III. the rate of change of the potential with respect to position in the direction parallel to the field IV. the rate of change of the potential with respect to position in the direction perpendicular to the field', '["I and II","III and IV","I, III, and IV","II, III, and IV","I, II, III, and IV"]'::jsonb, '(D) I is false: The direction of the force depends on the sign of the charge on the particle, so it cannot be known for any charged particle. II is true: The magnitude of the electric force is simply |F| = QE. III is true: The rate of change in voltage with respect to position in the direction parallel to the field is simply E, with potential decreasing in the direction of the field. IV is true: The rate of change in potential with respect to position in the direction perpendicular to the field is always equal to zero.'),
  ('ap-diag-physc-em_q35', 'ap-diag-physc-em', 35, false, 'C', 'Diagnostic Test – E&M', 'medium', 'A parallel-plate capacitor with plate area A and separation d is charged to a potential difference V0 by a battery. The battery is then disconnected. A slab of dielectric material with dielectric constant kappa > 1 is now inserted, completely filling the space between the plates. What are the new capacitance C and stored energy U compared to their initial values C0 and U0?', '["C = kappa C0, and U = kappa U0","C = C0 / kappa, and U = U0 / kappa","C = kappa C0, and U = U0 / kappa","C = C0, and U = U0","C = kappa C0, and U = U0"]'::jsonb, 'When a dielectric of constant kappa is inserted, the capacitance increases by a factor of kappa: C = kappa C0. Because the capacitor is disconnected from the battery, the charge Q remains constant (Q = Q0). The stored energy is U = Q^2 / (2C) = Q0^2 / (2 kappa C0) = U0 / kappa. Thus, capacitance increases by kappa and stored energy decreases by a factor of kappa (the electrostatic field does work pulling the dielectric slab into the plates).'),
  ('ap-topic-physc-circuits_q1', 'ap-topic-physc-circuits', 1, false, 'C', 'Ch13: Circuits', 'medium', 'The equivalent resistance of the circuit in Figure 13.14 is Figure 13.14', '["4R","2R","R","R/2","R/4"]'::jsonb, '(C) The parallel combination of the two resistors with resistances R and 2R has an equivalent resistance of Adding the resistor R, which is in series with this parallel combination, yields an equivalent resistance of R.'),
  ('ap-topic-physc-circuits_q2', 'ap-topic-physc-circuits', 2, false, 'B', 'Ch13: Circuits', 'medium', 'In an RC series circuit connected to a constant DC voltage source V0, an initially uncharged capacitor C is charged through a resistor R. At time t = 0 the switch is closed. What is the current I(t) through the circuit as a function of time t?', '["I(t) = (V0 / R) * (1 - e^{-t / (RC)})","I(t) = (V0 / R) * e^{-t / (RC)}","I(t) = (V0 / R) * e^{-t / (2RC)}","I(t) = V0 C * e^{-t / (RC)}","I(t) is constant and equal to V0 / R"]'::jsonb, 'By Kirchhoff''s loop rule: V0 - I R - q/C = 0. Differentiating with respect to t (since dq/dt = I): -R (dI/dt) - I/C = 0 ==> dI/dt = -I / (RC). Integrating from t = 0 where the uncharged capacitor has q(0) = 0 and initial current I(0) = V0/R: I(t) = (V0 / R) e^{-t / (RC)}.'),
  ('ap-topic-physc-circuits_q3', 'ap-topic-physc-circuits', 3, false, 'C', 'Ch13: Circuits', 'medium', 'A battery with EMF V0 and internal resistance r is connected across an external variable load resistor R. For what value of R is the power delivered to the external load maximized?', '["R = 0","R = r / 2","R = r","R = 2r","R approaches infinity"]'::jsonb, 'The current is I = V0 / (R + r). The power dissipated in the load is P(R) = I^2 R = V0^2 R / (R + r)^2. To find the maximum, set dP/dR = 0: dP/dR = V0^2 [ (R+r)^2 - 2R(R+r) ] / (R+r)^4 = V0^2 (r - R) / (R+r)^3 = 0 ==> R = r. This is the Maximum Power Transfer Theorem.'),
  ('ap-topic-physc-circuits_q4', 'ap-topic-physc-circuits', 4, false, 'B', 'Ch13: Circuits', 'medium', 'Twelve identical resistors, each of resistance R, are connected along the twelve edges of a cube. What is the equivalent resistance R_eq between two diametrically opposite corners of the cube?', '["R / 2","5/6 R","3/4 R","7/12 R","R"]'::jsonb, 'By symmetry, when a current I enters one corner and exits the diametrically opposite corner: At the entry corner, current splits equally into 3 edges, each carrying I/3. At each of the next vertices, current splits into 2 edges, each carrying (I/3)/2 = I/6 (6 edges total). At the exit corner, 3 edges recombine, each carrying I/3. The total voltage drop across opposite corners is Delta V = (I/3)R + (I/6)R + (I/3)R = (2/6 + 1/6 + 2/6) I R = (5/6) I R. Therefore, R_eq = Delta V / I = 5/6 R.'),
  ('ap-topic-physc-circuits_q5', 'ap-topic-physc-circuits', 5, false, 'B', 'Ch13: Circuits', 'medium', 'For the circuit in Figure 13.15, which of the following is true? Figure 13.15', '["VB − VA = +5 V","VB − VA = +3 V","VB − VA = −2 V","VB − VA = −3 V","VB − VA = −5 V"]'::jsonb, '(B) This problem involves Kirchhoff’s loop rule. First, Kirchhoff’s node equation indicates that the current flowing down the 1 Ω resistor is 2 A. Then, writing a Kirchhoff’s loop equation containing points A and B in either possible loop yields the correct answer. For example, we will use the outer loop and move clockwise. Starting at point A and summing potential jumps as we move from point A to point B yields Therefore,'),
  ('ap-topic-physc-circuits_q6', 'ap-topic-physc-circuits', 6, false, 'B', 'Ch13: Circuits', 'medium', 'In a series RC circuit, an uncharged capacitor of capacitance C is charged through a resistor R by a battery of voltage V. After a very long time (t >> RC), what is the total energy supplied by the battery, and how much of that energy is stored in the capacitor?', '["Battery supplies 1/2 C V^2, and capacitor stores 1/2 C V^2","Battery supplies C V^2, and capacitor stores 1/2 C V^2 (with 1/2 C V^2 dissipated as heat in R)","Battery supplies C V^2, and capacitor stores C V^2","Battery supplies 2 C V^2, and capacitor stores C V^2","Battery supplies C V^2, and capacitor stores 1/4 C V^2"]'::jsonb, 'When fully charged, the capacitor carries charge Q = C V. The total work done by the battery is W = Q V = (C V) V = C V^2. The energy stored in the electric field of the capacitor is U_C = 1/2 C V^2. By conservation of energy, the remaining energy W - U_C = 1/2 C V^2 is dissipated as thermal energy in the resistor regardless of the value of R.'),
  ('ap-topic-physc-circuits_q7', 'ap-topic-physc-circuits', 7, false, 'B', 'Ch13: Circuits', 'medium', 'What is the equivalent voltage of the two batteries arranged in series in Figure 13.16? Figure 13.16', '["2 V, with point A at higher potential","2 V, with point B at higher potential","4 V, with point A at higher potential","4 V, with point B at higher potential","It is not valid to treat the two batteries as a single equivalent battery."]'::jsonb, '(B) Summing the potential jumps indicates that point B always has a potential 2 V higher than point A. Therefore, the two batteries together have the same effect as one 2 V battery with its positive terminal at point B and its negative terminal at point A.'),
  ('ap-topic-physc-circuits_q8', 'ap-topic-physc-circuits', 8, false, 'B', 'Ch13: Circuits', 'medium', 'How much power is dissipated in the circuit discussed in question 4?', '["P = 20/3R","P = 12/5R","P = 6/5R","P = 3/5R","none of the above Figure 13.17"]'::jsonb, '(B) . This problem illustrates how simplifying a circuit and calculating equivalent voltages and resistances simplifies calculating quantities such as power.'),
  ('ap-topic-physc-circuits_q9', 'ap-topic-physc-circuits', 9, false, 'A', 'Ch13: Circuits', 'medium', 'In the circuit shown in Figure 13.17, capacitor C1 is initially charged and capacitor C2 is initially uncharged when the switch is closed at t =', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(A) Initially the current is equal to I = V/R = Q/C1R (because C2 acts as a short circuit and C1 initially has voltage V = Q/C1). The current at equilibrium is zero. Therefore, the current exponentially decays from a finite value to zero, as described by graph (A).'),
  ('ap-topic-physc-circuits_q10', 'ap-topic-physc-circuits', 10, false, 'D', 'Ch13: Circuits', 'medium', 'Which of the following is Kirchhoff’s loop equation for the circuit shown in Figure 13.17? (I is designated as the counterclockwise current.)', '["−Q1/C1 − IR + Q2/C2 = 0","Q1/C1 − IR + Q2/C2 = 0","−Q1/C1 + IR − Q2/C2 = 0","Q1/C1 − IR − Q2/C2 = 0","Q1/C1 + IR + Q2/C2 = 0 Figure 13.18"]'::jsonb, '(D) Beginning at the top right corner of the circuit and moving counterclockwise: 1. The potential jump across C1 is positive because we are going from the negative plate to the positive plate (which is at a higher potential). 2. The potential jump across the resistor is negative because we are going in the same direction as the current (which flows counterclockwise). 3. The potential jump across C2 is negative because we are going from the positive plate to the negative plate. Note: Of course, if you choose to go in the opposite direction, all the signs will be reversed and an equivalent equation will be obtained (which can be converted to the equation in choice (D) by multiplying both sides by −1).'),
  ('ap-topic-physc-circuits_q11', 'ap-topic-physc-circuits', 11, false, 'B', 'Ch13: Circuits', 'medium', 'A capacitor is discharged through a resistor. If the energy stored in the capacitor decreases to 1/4 of its initial value in 10 seconds, what is the time constant tau = RC of the circuit?', '["10 s","10 / ln(2) s","10 / ln(4) s","5 s","20 s"]'::jsonb, 'The charge on the discharging capacitor is q(t) = Q0 e^{-t / tau}. The stored energy is U(t) = q(t)^2 / (2C) = U0 e^{-2t / tau}. Given U(10) / U0 = 1/4: e^{-20 / tau} = 1/4 ==> e^{20 / tau} = 4 ==> 20 / tau = ln(4) = 2 ln(2) ==> tau = 20 / (2 ln(2)) = 10 / ln(2) s.'),
  ('ap-topic-physc-circuits_q12', 'ap-topic-physc-circuits', 12, false, 'E', 'Ch13: Circuits', 'medium', 'The capacitor in the circuit in Figure 13.20 is uncharged when the switch is closed at t = 0. Figure 13.20 How much energy is dissipated in the circuit from t = 0 to t = \infty?', '["the energy stored in the capacitor, CV2","the energy stored in the capacitor and the energy dissipated in the resistor, equal to CV2","the energy stored in the capacitor, \\frac{1}{2}CV^2","the energy stored in the capacitor and the energy dissipated in the resistor, equal to 2CV2","none of the above"]'::jsonb, '(E) Although the rate at which energy is dissipated by the RC loop of the circuit is finite, energy continues to be dissipated by the 2R resistor forever, so the energy dissipated from t = 0 to t = \infty is undefined (infinite).'),
  ('ap-topic-physc-circuits_q13', 'ap-topic-physc-circuits', 13, false, 'B', 'Ch13: Circuits', 'medium', 'An inductor of inductance L and a resistor of resistance R are connected in series with a switch and a battery of EMF V0. The switch is closed at t = 0. What is the rate of change of current dI/dt at the instant t = 0?', '["Zero","V0 / L","V0 / R","V0 / (R L)","Infinity"]'::jsonb, 'Kirchhoff''s loop rule for the RL circuit is V0 - I R - L (dI/dt) = 0. At t = 0, the current through the inductor cannot change instantaneously from zero, so I(0) = 0. The equation becomes V0 - 0 - L (dI/dt) = 0 ==> dI/dt = V0 / L.'),
  ('ap-topic-physc-circuits_q14', 'ap-topic-physc-circuits', 14, false, 'A', 'Diagnostic Test – E&M', 'medium', 'In an LC circuit consisting of an ideal inductor L and an ideal capacitor C with no resistance, the charge on the capacitor oscillates with time. What is the period T of the electromagnetic oscillations?', '["2 pi sqrt(L C)","1 / (2 pi sqrt(L C))","2 pi L / C","2 pi sqrt(L / C)","pi sqrt(L C)"]'::jsonb, 'The differential equation governing the LC circuit is L (d^2 q / dt^2) + q/C = 0 ==> d^2 q / dt^2 + (1 / (L C)) q = 0. This is simple harmonic motion with angular frequency omega = 1 / sqrt(L C). The oscillation period is T = 2 pi / omega = 2 pi sqrt(L C).'),
  ('ap-topic-physc-circuits_q15', 'ap-topic-physc-circuits', 15, false, 'C', 'Diagnostic Test – E&M', 'medium', 'A charged particle is launched into a region of uniform magnetic field. Given that the particle’s initial velocity has components parallel and perpendicular to the magnetic field, describe the particle’s path qualitatively.', '["a straight line","a circle","a helical (corkscrew) path","a parabolic path","none of the above"]'::jsonb, '(C) See the discussion of the motion of particles within magnetic fields in Chapter 14.'),
  ('ap-topic-physc-circuits_q16', 'ap-topic-physc-circuits', 16, false, 'B', 'Diagnostic Test – E&M', 'medium', 'A point charge +Q is located at a fixed distance from a sphere. Compare the magnitude of the attractive force on the sphere if the sphere is (1) metal with net charge −Q, (2) metal with no net charge, (3) an insulator with net charge −Q, or (4) an insulator with no net charge.', '["charged metal = charged insulator > uncharged metal = uncharged insulator","charged metal > charged insulator > uncharged metal > uncharged insulator","charged insulator > charged metal > uncharged insulator > uncharged metal","charged insulator > charged metal > uncharged metal = uncharged insulator","charged insulator = charged metal > uncharged metal > uncharged insulator"]'::jsonb, '(B) This is a question about electrostatic induction. When a positive point charge is placed near a metal sphere (charged or uncharged), it attracts mobile electrons in the metal, causing the metal to become polarized such that more negative charge is on the side closer to the positive point charge and more positive charge is on the side farther away from the positive point charge. Because this charge redistribution results in moving negative charge closer to the positive point charge and moving positive charge farther away from the positive point charge, it increases the attractive force between the metal sphere and the positive point charge. Therefore, compared to an insulating sphere with the same net charge, a metal sphere always experiences a greater attractive force (such that charged metal > charged insulator and uncharged metal > uncharged insulator). Because this inductive effect is small compared to the effect of actually putting net charge −Q on the sphere, charged insulator > uncharged metal.'),
  ('ap-topic-physc-circuits_q17', 'ap-topic-physc-circuits', 17, false, 'C', 'Diagnostic Test – E&M', 'medium', 'A bar moves to the right through a magnetic field as shown (the magnetic field points into the page). What is the potential difference between points A and B after equilibrium is established in the bar?', '["The difference is v2Bd, with A at higher potential.","The difference is v2Bd, with B at higher potential.","The difference is vBd, with A at higher potential.","The difference is vBd, with B at higher potential.","Because there is no loop, there is no flux, so there is no potential difference."]'::jsonb, '(C) The charges within the bar are moving in a magnetic field, so they feel a magnetic force. Using the conventional-current description, positive charges feel an upward force, causing positive charge to accumulate at the top end of the bar (leaving negative charge on the bottom end of the bar). This charge continues to accumulate until the electric force created by the charge imbalance cancels the magnetic force, mathematically qE = qvB. The magnitude of the potential difference between points A and B is then |V | = |−\int E \cdot  dr| = |vBd|. The electric field points down (producing a force that opposes the magnetic force), and recalling that electric fields point from high to low potential, we see that point A is at the higher potential. Further information about motional EMF can be found in Example 15.6.'),
  ('ap-topic-physc-circuits_q18', 'ap-topic-physc-circuits', 18, false, 'B', 'Diagnostic Test – E&M', 'medium', 'Suppose that the electric potential in a region of space is a constant. What can you conclude about the magnitude of the electric field in this region?', '["It is a nonzero constant.","It is zero.","It is proportional to the distance from the origin.","It is given by","Not enough information is given. Questions 6–8 refer to a circular region of radius a with a uniform magnetic field pointing into the page that is increasing at a constant rate as shown. A circular loop of wire of radius r is centered on the middle of the region."]'::jsonb, '(B) The electric field is the negative derivative (with respect to the spatial coordinate) of the potential. Thus, with a constant potential the electric field must be zero.'),
  ('ap-topic-physc-circuits_q19', 'ap-topic-physc-circuits', 19, false, 'C', 'Diagnostic Test – E&M', 'medium', 'Which of the graphs plots the induced EMF in the circular loop of wire shown as a function of its radius r?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(C) The induced EMF depends on the change in the enclosed flux. Because the magnetic field is uniform, and changing at a constant rate, Therefore, the induced EMF depends only on the area of the loop through which magnetic field lines pass. For r < a, the area within the loop exposed to the magnetic field is simply the entire area of the loop, which is a quadratic function, A(r) = \pir2. For r > a, increasing r does not increase the area exposed to the magnetic field (because the magnetic field through the additional area is zero). Therefore, for r > a the induced EMF is constant. The only graph that is quadratic for small r and then constant is choice (C). Calculating the induced EMF due to a magnetic field via Faraday’s law is discussed in Chapter 15.'),
  ('ap-topic-physc-circuits_q20', 'ap-topic-physc-circuits', 20, false, 'A', 'Diagnostic Test – E&M', 'medium', 'Given that the resistance of the loop is proportional to the loop’s circumference, which of the graphs seen in question 6 shows the induced current as a function of the radius of the loop?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(A) The current is given by I = V/R. The resistance is proportional to the circumference of the loop, 2\pir. Therefore, for r < a, V is proportional to r2 (as discussed in question 6), and 1/R is proportional to 1/r, so the product I = V/R is proportional to r (and thus its graph is a line passing through the origin). For r > a, V is constant and 1/R is proportional to 1/r, so the product I = V/R is inversely proportional to r. The only graph that satisfies these conditions is choice (A).'),
  ('ap-topic-physc-magnetism_q1', 'ap-topic-physc-magnetism', 1, false, 'C', 'Ch14: Magnetic Fields', 'medium', 'Two circular loops of wire of equal radius R carry equal currents I. One loop lies in the xy-plane carrying current counterclockwise as seen from the positive z-axis, producing a magnetic field B_z k at the origin. The second loop lies in the xz-plane carrying current that produces a magnetic field -B_y j at the origin. What is the direction of the net magnetic field at the origin?', '["Along the positive x-axis","In the xy-plane at 45 degrees to the axes","In the yz-plane along the direction -j + k","Along the negative z-axis","Zero net magnetic field"]'::jsonb, 'By the principle of superposition, the net magnetic field at the origin is B_net = B1 + B2 = -B_y j + B_z k. Because the loops have equal radii and carry equal currents, |B_y| = |B_z| = mu_0 I / (2R). The net field lies in the yz-plane and is parallel to the vector -j + k.'),
  ('ap-topic-physc-magnetism_q2', 'ap-topic-physc-magnetism', 2, false, 'C', 'Ch14: Magnetic Fields', 'medium', 'A long coaxial cable consists of an inner solid cylindrical conductor of radius a and an outer thin cylindrical shell of radius b (with a < b). Equal currents I flow in opposite directions through the inner and outer conductors. What is the magnetic field magnitude B(r) in the space between the conductors (a < r < b)?', '["Zero","mu_0 I r / (2 pi a^2)","mu_0 I / (2 pi r)","mu_0 I / (2 pi b)","mu_0 I / (4 pi r^2)"]'::jsonb, 'Apply Ampere''s law oint B * dl = mu_0 I_enc around a circular path of radius r (with a < r < b). The path encloses only the inner conductor carrying total current I. Thus, B(2 pi r) = mu_0 I ==> B(r) = mu_0 I / (2 pi r).'),
  ('ap-topic-physc-magnetism_q3', 'ap-topic-physc-magnetism', 3, false, 'D', 'Ch14: Magnetic Fields', 'medium', 'A uniform magnetic field of magnitude B points out of the page in the region x > 0, and a uniform magnetic field of equal magnitude points into the page in the region x < 0, as shown in Figure 14.15. A particle with charge +q and mass m initially at the origin moves to the right with speed v. At which of the following points does the particle cross the y- axis? Figure 14.15', '["6 mv/qB","3 mv/qB","−3 mv/qB","−6 mv/qB","The particle will never cross the y-axis."]'::jsonb, '(D) The particle’s velocity is perpendicular to the magnetic field, so it moves in a circular path. The radius of the path can be calculated by equating the magnetic force to the centripetal force, qvB = mv2/r, to obtain r = mv/qB. Careful examination of the particle’s path reveals that it moves in the path shown in Figure 14.25. Therefore, it passes through the y-axis at multiples of −2r = −2 mv/qB. Figure 14.25'),
  ('ap-topic-physc-magnetism_q4', 'ap-topic-physc-magnetism', 4, false, 'D', 'Ch14: Magnetic Fields', 'medium', 'Two infinitely long wires carry equal currents of I into the page, as shown in Figure 14.24.', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(D) The particle’s velocity is perpendicular to the magnetic field, so it moves in a circular path. The radius of the path can be calculated by equating the magnetic force to the centripetal force, qvB = mv2/r, to obtain r = mv/qB. Careful examination of the particle’s path reveals that it moves in the path shown in Figure 14.25. Therefore, it passes through the y-axis at multiples of −2r = −2 mv/qB. Figure 14.25'),
  ('ap-topic-physc-magnetism_q5', 'ap-topic-physc-magnetism', 5, false, 'E', 'Ch14: Magnetic Fields', 'medium', 'An electron moves in a magnetic field along a certain path at a constant speed. The magnetic field does no work on the electron if', '["the path is parallel to the magnetic field so that the magnetic force is zero","the path is perpendicular to the field so that the electron moves in uniform circular motion","the magnetic field is constant in space so that there is no induced electric field","the electron must move along a magnetic field line","None of the above conditions are necessary."]'::jsonb, '(E) The magnetic force is always perpendicular to velocity, so it can never do work (recall that dW = F \cdot  d r).'),
  ('ap-topic-physc-magnetism_q6', 'ap-topic-physc-magnetism', 6, false, 'C', 'Ch14: Magnetic Fields', 'medium', 'Figure 14.16 shows a cross section of a coaxial cable. A current of 1.0 A passes through the center of the cable, while a uniform current density of 1.0 A/m2 comes out of the page through the outer sheath of the cable. At what distance from the center of the cable is the magnetic field equal to zero? Figure 14.16', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","(D) The magnetic field is zero but not at the radii listed above.","Independent of the mass and charge distribution","The magnetic field is never zero except at infinity."]'::jsonb, '(C) According to Ampere’s law, the magnetic field is zero when the enclosed current is zero. For the inward current to balance the outward current, the outward current enclosed must equal 1.0 A. The enclosed outward current is 1.0 A when the Amperian path encloses an area of 1.0 m2 of the sheath (because the current density is 1.0 A/m2). Geometrically, 1 = \pir2 − \pi(1.0)2. Solving this equation for r yields choice (C).'),
  ('ap-topic-physc-magnetism_q7', 'ap-topic-physc-magnetism', 7, false, 'A', 'Ch14: Magnetic Fields', 'medium', 'A charged particle moves in uniform circular motion due to a magnetic field perpendicular to the plane of its motion. Which of the graphs in Figure 14.17 illustrates the relationship between the charge’s velocity and the radius of its motion? (Assume that other variables, such as the magnetic field strength and the mass of the particle, are held constant.) Figure 14.17', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(A) The magnetic force provides the centripetal force: Thus, v is a linear function of r that passes through the origin.'),
  ('ap-topic-physc-magnetism_q8', 'ap-topic-physc-magnetism', 8, false, 'B', 'Ch14: Magnetic Fields', 'medium', 'A particle with a charge −q and mass m is moving with speed v through a mass spectrometer that contains a uniform outward magnetic field as shown in Figure 14.18. What is the magnitude and direction of the electric field required so that the net force on this particle is zero? Figure 14.18', '["E = vB, with a direction upward","E = vB, with a direction downward","E = B/v, with a direction upward","E = B/v, with a direction downward","E = B/v, with a direction into the page"]'::jsonb, '(B) For the magnetic force to cancel the electric force, |qv \times  B| = qvB = qE, which simplifies to E = vB. The direction of the magnetic force on the charge is downward (opposite the direction indicated by the right- hand rule because the charge is negative). The electric force must point in the opposite direction, upward. However, since the charge is negative, in order to produce an upward electric force the field must point downward.'),
  ('ap-topic-physc-magnetism_q9', 'ap-topic-physc-magnetism', 9, false, 'A', 'Ch14: Magnetic Fields', 'medium', 'Consider current passing through a short segment of a circular loop of wire as shown in Figure 14.19. The current passing through the rest of the circular wire produces a magnetic field at the location of the short segment, resulting in a magnetic force on the current-carrying segment of wire. Which of the following statements about this force is true? Figure 14.19', '["The force is to the right.","The force is to the left.","The magnetic field is zero because of symmetry, so there is no force.","The force is pointing out of the page.","The force is pointing into the page."]'::jsonb, '(A) First, imagine dividing the loop into little segments and considering the magnetic field due to each segment (using the right- hand rule for the direction of a magnetic field produced by a current- carrying wire or using the right-hand rule embedded in Biot-Savart’s law). Because each segment produces a magnetic field pointing out of the page at the segment of wire, the net magnetic field points out of the page. Using the right-hand rule again, the force this field exerts on the segment of wire is to the right. In general, each segment of the loop feels a force directed radially outward due to the rest of the loop.'),
  ('ap-topic-physc-magnetism_q10', 'ap-topic-physc-magnetism', 10, false, 'D', 'Ch14: Magnetic Fields', 'medium', 'Two wires located along the x-axis carry equal currents into the page as shown in Figure 14.20. Which of the graphs shows the y-component of the magnetic field along the x-axis? Figure 14.20', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(D) At the origin, the fields due to the two wires cancel and the net field is zero, eliminating choices (A) and (B). As each wire is approached from the right, the field decreases to negative infinity, and as each wire is approached from the left, the field increases to positive infinity. This is consistent only with choice (D).'),
  ('ap-topic-physc-magnetism_q11', 'ap-topic-physc-magnetism', 11, false, 'C', 'Ch14: Magnetic Fields', 'medium', 'A particle moves through an electric field as shown in Figure 14.21. What is the direction of the magnetic field needed to ensure that the particle experiences zero net force? Figure 14.21', '["into the page if the particle is positively charged, out of the page if the particle is negatively charged","into the page if the particle is negatively charged, out of the page if the particle is positively charged","into the page, irrespective of the particle’s charge","out of the page, irrespective of the particle’s charge","to the left, irrespective of the particle’s charge"]'::jsonb, '(C) Changing the sign of the charge of the particle changes the direction of both the electric and the magnetic forces, two changes that cancel each other out, so that in either case the magnetic field must point into the page in order to cancel out the electric field. (If the magnetic field is into the page, a positive charge will feel an electric force to the right and a magnetic force to the left. Alternatively, a negative charge will feel forces in the opposite directions.)'),
  ('ap-topic-physc-magnetism_q12', 'ap-topic-physc-magnetism', 12, false, 'B', 'Ch14: Magnetic Fields', 'medium', 'Three loops of equal radii carrying equal currents lie on planes parallel to the yz-plane as shown in Figure 14.22. Two of the loops are located equal distances d from the yz-plane as shown, while the third loop lies on the yz-plane. In what direction is the net magnetic field at the origin? Figure 14.22', '["The magnetic field is zero because of symmetry.","The magnetic field is in the +x-direction.","The magnetic field is in the −x-direction.","The magnetic field lies in the xz-plane.","The magnetic field lies in the xy-plane. Free-Response Questions"]'::jsonb, '(B) The two loops lying off the yz-plane produce equal and opposite fields which cancel each other. (The loop at x = −d produces a magnetic field in the −x-direction, while the loop at x = d produces a magnetic field in the +x-direction.) The net field is therefore equal to the field produced by the middle loop, which produces a field in the +x- direction. Free-Response 1. Given the cylindrical symmetry of this problem, Ampere’s Law is the way to go. As in Examples 14.4 and 14.5, the field lines will be concentric circles centered on the center of the inner conductor. The Amperian path will be a circle of radius r. The left-hand side of Ampere’s law for this path will be ∮B \cdot  dl = B(2\pir). All we need to do is to figure out the direction and magnitude of the enclosed current to solve each part of the problem. (a) The current density in the inner conductor is , positive because the current is flowing out of the page. Thus, the enclosed current is , and Ampere’s law says: The field is counterclockwise because the current is positive, pointing out of the page. (b) Now the enclosed current is the full value I, pointing out of the page, i.e., positive. Ampere’s law yields , just like a thin current- carrying wire. The field is counterclockwise. (c) This is the trickiest part of this problem as we are enclosing the entire inner conductor but only a portion of the outer conductor. First, we need to find the current density in the outer conductor. The cross- sectional area of the outer conductor is and the current density is , negative because the current flows into the page. The enclosed current is then given by I enclosed . Applying Ampere’s law we find: The field is positive, i.e., counterclockwise because the enclosed current is positive. (d) The enclosed current is now zero so the field is zero. 2. (a) The magnetic field due to an infinitely long wire is equal in magnitude to B = \mu0I/2\pir and has a direction indicated by the right-hand rule. The magnetic field along the x-axis is a superposition of the magnetic fields due to both of the wires, as shown in Figure 14.26. Figure 14.26 Adding the two vectors yields (b) This expression is given in Figure 14.27. In sketching the curve, first we note that the function has odd symmetry; mathematically, B(−x) = −B(x). Because x is raised to a greater power in the denominator than in the numerator, the function asymptotically approaches zero as x approaches positive or negative infinity. Finally, we note that the function is zero at the origin and that it passes through the origin with a negative slope. Figure 14.27 Note: A graphing calculator can also be used to sketch this curve: Simply graphing the function f(x) = −x/(1 + x2) is sufficient to get an idea of how this curve looks. (c) The magnetic force is always perpendicular to the velocity, so it never does any work. (Thus, the magnetic force can change only an object’s direction, not its speed.) Therefore, no work need be done by an external force to move the charge from infinity to the origin.'),
  ('ap-topic-physc-magnetism_q13', 'ap-topic-physc-magnetism', 13, false, 'A', 'Diagnostic Test – E&M', 'medium', 'A charged particle with charge q and mass m enters a region of uniform magnetic field B with velocity v perpendicular to the field. The particle travels in a circle of radius R. What is the kinetic energy of the particle in terms of q, m, B, and R?', '["q^2 B^2 R^2 / (2 m)","q B R / (2 m)","q^2 B R^2 / m","1/2 q B v R","q B^2 R / (2 m)"]'::jsonb, 'The magnetic force provides the centripetal acceleration: q v B = m v^2 / R ==> m v = q B R. Linear momentum is p = q B R. The kinetic energy is K = p^2 / (2 m) = (q B R)^2 / (2 m) = q^2 B^2 R^2 / (2 m).'),
  ('ap-topic-physc-magnetism_q14', 'ap-topic-physc-magnetism', 14, false, 'C', 'Diagnostic Test – E&M', 'medium', 'A charged particle is launched into a region of uniform magnetic field. Given that the particle’s initial velocity has components parallel and perpendicular to the magnetic field, describe the particle’s path qualitatively.', '["a straight line","a circle","a helical (corkscrew) path","a parabolic path","none of the above"]'::jsonb, '(C) See the discussion of the motion of particles within magnetic fields in Chapter 14.'),
  ('ap-topic-physc-magnetism_q15', 'ap-topic-physc-magnetism', 15, false, 'B', 'Diagnostic Test – E&M', 'medium', 'A point charge +Q is located at a fixed distance from a sphere. Compare the magnitude of the attractive force on the sphere if the sphere is (1) metal with net charge −Q, (2) metal with no net charge, (3) an insulator with net charge −Q, or (4) an insulator with no net charge.', '["charged metal = charged insulator > uncharged metal = uncharged insulator","charged metal > charged insulator > uncharged metal > uncharged insulator","charged insulator > charged metal > uncharged insulator > uncharged metal","charged insulator > charged metal > uncharged metal = uncharged insulator","charged insulator = charged metal > uncharged metal > uncharged insulator"]'::jsonb, '(B) This is a question about electrostatic induction. When a positive point charge is placed near a metal sphere (charged or uncharged), it attracts mobile electrons in the metal, causing the metal to become polarized such that more negative charge is on the side closer to the positive point charge and more positive charge is on the side farther away from the positive point charge. Because this charge redistribution results in moving negative charge closer to the positive point charge and moving positive charge farther away from the positive point charge, it increases the attractive force between the metal sphere and the positive point charge. Therefore, compared to an insulating sphere with the same net charge, a metal sphere always experiences a greater attractive force (such that charged metal > charged insulator and uncharged metal > uncharged insulator). Because this inductive effect is small compared to the effect of actually putting net charge −Q on the sphere, charged insulator > uncharged metal.'),
  ('ap-topic-physc-magnetism_q16', 'ap-topic-physc-magnetism', 16, false, 'C', 'Diagnostic Test – E&M', 'medium', 'A bar moves to the right through a magnetic field as shown (the magnetic field points into the page). What is the potential difference between points A and B after equilibrium is established in the bar?', '["The difference is v2Bd, with A at higher potential.","The difference is v2Bd, with B at higher potential.","The difference is vBd, with A at higher potential.","The difference is vBd, with B at higher potential.","Because there is no loop, there is no flux, so there is no potential difference."]'::jsonb, '(C) The charges within the bar are moving in a magnetic field, so they feel a magnetic force. Using the conventional-current description, positive charges feel an upward force, causing positive charge to accumulate at the top end of the bar (leaving negative charge on the bottom end of the bar). This charge continues to accumulate until the electric force created by the charge imbalance cancels the magnetic force, mathematically qE = qvB. The magnitude of the potential difference between points A and B is then |V | = |−\int E \cdot  dr| = |vBd|. The electric field points down (producing a force that opposes the magnetic force), and recalling that electric fields point from high to low potential, we see that point A is at the higher potential. Further information about motional EMF can be found in Example 15.6.'),
  ('ap-topic-physc-magnetism_q17', 'ap-topic-physc-magnetism', 17, false, 'B', 'Diagnostic Test – E&M', 'medium', 'Suppose that the electric potential in a region of space is a constant. What can you conclude about the magnitude of the electric field in this region?', '["It is a nonzero constant.","It is zero.","It is proportional to the distance from the origin.","It is given by","Not enough information is given. Questions 6–8 refer to a circular region of radius a with a uniform magnetic field pointing into the page that is increasing at a constant rate as shown. A circular loop of wire of radius r is centered on the middle of the region."]'::jsonb, '(B) The electric field is the negative derivative (with respect to the spatial coordinate) of the potential. Thus, with a constant potential the electric field must be zero.'),
  ('ap-topic-physc-magnetism_q18', 'ap-topic-physc-magnetism', 18, false, 'C', 'Diagnostic Test – E&M', 'medium', 'Which of the graphs plots the induced EMF in the circular loop of wire shown as a function of its radius r?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(C) The induced EMF depends on the change in the enclosed flux. Because the magnetic field is uniform, and changing at a constant rate, Therefore, the induced EMF depends only on the area of the loop through which magnetic field lines pass. For r < a, the area within the loop exposed to the magnetic field is simply the entire area of the loop, which is a quadratic function, A(r) = \pir2. For r > a, increasing r does not increase the area exposed to the magnetic field (because the magnetic field through the additional area is zero). Therefore, for r > a the induced EMF is constant. The only graph that is quadratic for small r and then constant is choice (C). Calculating the induced EMF due to a magnetic field via Faraday’s law is discussed in Chapter 15.'),
  ('ap-topic-physc-magnetism_q19', 'ap-topic-physc-magnetism', 19, false, 'A', 'Diagnostic Test – E&M', 'medium', 'Given that the resistance of the loop is proportional to the loop’s circumference, which of the graphs seen in question 6 shows the induced current as a function of the radius of the loop?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(A) The current is given by I = V/R. The resistance is proportional to the circumference of the loop, 2\pir. Therefore, for r < a, V is proportional to r2 (as discussed in question 6), and 1/R is proportional to 1/r, so the product I = V/R is proportional to r (and thus its graph is a line passing through the origin). For r > a, V is constant and 1/R is proportional to 1/r, so the product I = V/R is inversely proportional to r. The only graph that satisfies these conditions is choice (A).'),
  ('ap-topic-physc-magnetism_q20', 'ap-topic-physc-magnetism', 20, false, 'B', 'Diagnostic Test – E&M', 'medium', 'Two long, straight, parallel wires separated by distance d carry currents I1 and I2 in opposite directions (antiparallel). What is the nature and magnitude per unit length of the magnetic force between the two wires?', '["Attractive with magnitude mu_0 I1 I2 / (2 pi d)","Repulsive with magnitude mu_0 I1 I2 / (2 pi d)","Repulsive with magnitude mu_0 I1 I2 / (4 pi d^2)","Attractive with magnitude mu_0 I1 I2 / (2 pi d^2)","Zero because the currents are in opposite directions"]'::jsonb, 'Using the right-hand rule, antiparallel currents produce a repulsive force between the wires. The magnetic field produced by wire 1 at the location of wire 2 is B1 = mu_0 I1 / (2 pi d). The magnetic force on a segment of length L of wire 2 is F = I2 L B1 = mu_0 I1 I2 L / (2 pi d). Therefore, the force per unit length is F/L = mu_0 I1 I2 / (2 pi d), and it is repulsive.'),
  ('ap-topic-physc-em-drills_q1', 'ap-topic-physc-em-drills', 1, false, 'A', 'Coulomb''s Law Scaling Factor', 'easy', 'What will happen to the magnitude of electric force between two particles if the distance between them is doubled and each charge is tripled?', '["Multiplied by a factor of $9/4$","Multiplied by a factor of $3/2$","Multiplied by a factor of $3/4$","Multiplied by a factor of $9/2$","Multiplied by a factor of $6/4$"]'::jsonb, '(A) From Coulomb''s Law, $F = \frac{1}{4\pi\varepsilon_0}\frac{q_1 q_2}{r^2}$. Tripling both charges scales the numerator by $3 \times 3 = 9$. Doubling the separation distance scales the denominator by $2^2 = 4$. The resulting electrostatic force is multiplied by a factor of $9/4$.'),
  ('ap-topic-physc-em-drills_q2', 'ap-topic-physc-em-drills', 2, false, 'C', 'Negative Charge Kinematics in Electric Field', 'medium', 'A particle ($m = 10^{-10}\text{ kg}, q = -5 \times 10^{-13}\text{ C}$) starts at rest inside a uniform electric field $E = 50\text{ N/C}$ directed toward the left in a $1\text{-m}$ square region, positioned $70\text{ cm}$ from the left edge and $30\text{ cm}$ from the right edge. How long will it take to escape the field?', '["$1.10\\text{ s}$","$1.23\\text{ s}$","$1.55\\text{ s}$","$2.31\\text{ s}$","$2.59\\text{ s}$"]'::jsonb, '(C) Because the charge is negative, the electric force acts to the right, opposite to $\vec{E}$. The distance to escape out the right side is $d = 30\text{ cm} = 0.30\text{ m}$.
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-physc-em-drills_q6', 'ap-topic-physc-em-drills', 6, false, 'B', 'Gauss''s Law Flux vs. Point Field Superposition', 'medium', 'Charges $Q_2, Q_3$ are inside a Gaussian surface while $Q_1, Q_4$ are outside. Point P is on the surface. Which is true?', '["Flux depends on all four; $\\vec{E}$ at P depends on $Q_2, Q_3$.","Flux depends only on $Q_2, Q_3$; $\\vec{E}$ at P depends on all four.","Flux depends on $Q_2, Q_3$; $\\vec{E}$ at P depends on $Q_1, Q_2, Q_3$.","Flux depends on $Q_1, Q_4$; $\\vec{E}$ at P depends on $Q_2, Q_3$.","Both flux and $\\vec{E}$ depend on all four."]'::jsonb, '(B) By Gauss''s Law, total enclosed flux $\Phi_E = \frac{Q_{\text{enc}}}{\varepsilon_0} = \frac{Q_2 + Q_3}{\varepsilon_0}$ depends only on internal charges. By the principle of linear superposition, the local electric field vector $\vec{E}$ at any spatial point P is the vector sum of fields produced by all charges present ($Q_1, Q_2, Q_3, Q_4$).'),
  ('ap-topic-physc-em-drills_q7', 'ap-topic-physc-em-drills', 7, false, 'A', 'Uniformly Charged Sphere Interior Field', 'hard', 'A nonconducting solid sphere of radius $R$ carries uniform charge $-Q$. What is the electric field magnitude at distance $r < R$ from the center?', '["$\\frac{Q r}{4\\pi\\varepsilon_0 R^3}$","$\\frac{Q}{4\\pi\\varepsilon_0 R^2}$","$\\frac{Q}{4\\pi\\varepsilon_0 R^3}$","$\\frac{Q}{4\\pi\\varepsilon_0 R^3 r}$","$\\frac{Q}{4\\pi\\varepsilon_0 r^2}$"]'::jsonb, '(A) Enclosed charge at radius $r < R$: $Q_{\text{enc}} = -Q\left(\frac{r^3}{R^3}\right)$. Applying Gauss''s Law:
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-mock-physc-em-1_q31', 'ap-mock-physc-em-1', 31, false, 'D', 'Composite Dielectric Parallel-Plate Capacitor', 'hard', 'A dielectric of thickness $d/3$ and constant $K$ is inserted between the plates (separation $d$) of a parallel-plate capacitor. What is the total capacitance?', '["$\\frac{\\varepsilon_0 A(2+3K)}{d}$","$\\frac{3\\varepsilon_0 A}{d(2K+1)}$","$\\frac{K\\varepsilon_0 A}{d(2K+1)}$","$\\frac{3K\\varepsilon_0 A}{d(2K+1)}$","$\\frac{3K\\varepsilon_0 A}{d(K+2)}$"]'::jsonb, '(D) The system consists of three series capacitors: two vacuum gaps of thickness $d/3$ and one dielectric slab of thickness $d/3$.
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-mock-physc-em-3_q15', 'ap-mock-physc-em-3', 15, false, 'B', 'AP Physics C: Electricity & Magnetism', 'medium', '<p class="image"><img alt="Images" class="q-img" src="images/f0322-07.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="ques"><strong><a href="ch19v.xhtml#rch19r_15" id="ch19r_15">15.</a></strong> The diagram above shows a cross section of a three-dimensional closed surface. While no electric charges are inside the surface, several point charges outside the surface produce the nonuniform electric field $E$ shown above. Consider the vector <em>dA</em> to have a magnitude equal to a small element of surface area, and direction pointed normal to the surface as shown. Which of the following is true about <img alt="Images" class="q-img" src="images/f0322-08.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/> evaluated for the entire surface?</p>', '["<p>It is positive, because the net charge of the objects producing this electric field must have been positive.</p>","<p>It is zero, because no charge is enclosed within the surface</p>","<p>It is negative, because the smaller electric field intersects more surface area than the larger electric field.</p>","<p>It is undefined, because the $E$ is not always parallel to <em>dA</em>.</p>","<p>It is positive, because the larger electric field intersects more surface area than the smaller electric field.</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_15" id="rch19r_15">15.</a></strong> <strong>B—</strong>Gauss’s law says that for a closed surface, <img alt="Images" class="q-img" src="images/f0339-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/> is proportional to the charge enclosed by the surface. While the mathematics of Gauss’s law becomes difficult when the charge distribution and the surface are asymmetric, the law still holds. Since zero charge is enclosed, the integral becomes zero as well.</p>'),
  ('ap-mock-physc-em-3_q16', 'ap-mock-physc-em-3', 16, false, 'B', 'AP Physics C: Electricity & Magnetism', 'medium', '<p class="image"><img alt="Images" class="q-img" src="images/f0323-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="ques"><strong><a href="ch19v.xhtml#rch19r_16" id="ch19r_16">16.</a></strong> A uniform electric field of magnitude 400 N/C points to the right. Positions 1 and 2 are located in the electric field as shown. An object of charge +1.0 mC moves from position 1 to position 2. How much work is done on the object by the field?</p>', '["<p>−0.84 J</p>","<p>+0.84 J</p>","<p>+1.2 J</p>","<p>−1.2 J</p>","<p>0 J</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_16" id="rch19r_16">16.</a></strong> <strong>B—</strong>The force on the object is uniform and equal to <em>qE</em> = (0.001 C)(400 N/C) = 0.40 N. The work done by a uniform force is equal to force times distance, where that distance must be parallel (or antiparallel) to the direction of the force. The electric force is to the right; the force on a positive charge is likewise to the right. So the necessary distance is horizontal only . . . that’s (3 m) (cos 45<sup>o</sup>) = 2.1 m. The work done is (0.40 N) × (2.1 m) = 0.84 J. That work is positive because the electric force is parallel, not antiparallel, to the component of displacement along the direction of force.</p>'),
  ('ap-mock-physc-em-3_q17', 'ap-mock-physc-em-3', 17, false, 'E', 'AP Physics C: Electricity & Magnetism', 'medium', '<p class="image"><img alt="Images" class="q-img" src="images/f0323-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="ques"><strong><a href="ch19v.xhtml#rch19r_17" id="ch19r_17">17.</a></strong> Two objects carry opposite charges of the same magnitude. Both objects move up the page with speed $v$, as shown above. Which of the following indicates the direction of the instantaneous electric and magnetic fields, if any, at point P directly between the objects?</p><p class="image"><img alt="Images" class="q-img" src="images/f0323-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="image"><img alt="Images" class="q-img" src="images/f0323-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Electric Field: To the left; Magnetic Field: Out of the page","Electric Field: To the left; Magnetic Field: Into the page","Electric Field: Zero; Magnetic Field: Zero","Electric Field: To the right; Magnetic Field: Out of the page","Electric Field: To the right; Magnetic Field: Into the page"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_17" id="rch19r_17">17.</a></strong> <strong>E—</strong>For the magnetic field, think of the moving charges as current-carrying wires. Use the second right-hand rule. The left charge carries a current—a flow of positive charge—up the page. Point the thumb with the current and curl the fingers. The fingers point into the page at point P. Similarly, the right charge can be thought of as a flow of negative charge up the page, and so is equivalent to a flow of positive charge down the page. The magnetic field at point P due to the right charge is also into the page. So the net magnetic field is into the page. Then the electric field due to a charge points away from a positive, toward a negative charge. At point P that’s to the right due to the left-hand charge, and also to the right due to the right-hand charge, making the net electric field to the right.</p>'),
  ('ap-mock-physc-em-3_q18', 'ap-mock-physc-em-3', 18, false, 'E', 'AP Physics C: Electricity & Magnetism', 'medium', '<p class="ques"><strong><a href="ch19v.xhtml#rch19r_18" id="ch19r_18">18.</a></strong> Four isolated charge arrangements are shown above. Which of the following correctly ranks the magnitude of the electric force $F$ exerted by each charge on the other in its arrangement?</p>', '["<p>$F_{1}$ &gt; $F_{3}$ &gt; $F_{2}$ &gt; $F_{4}$</p>","<p>$F_{1}$ &gt; $F_{2}$ &gt; $F_{3}$ &gt; $F_{4}$</p>","<p>$F_{1} = F_{3}$ &gt; $F_{2} = F_{4}$</p>","<p>$F_{3}$ &gt; $F_{4}$ &gt; $F_{1} = F_{2}$</p>","<p>$F_{1} = F_{2}$ &gt; $F_{3} = F_{4}$</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_18" id="rch19r_18">18.</a></strong> <strong>E—</strong>The magnitude of the electric force is given by $F$ = <em>kqq/d</em><sup>2</sup>. The magnitude of a force is just an amount—the + or − sign is not plugged into the equation. (The signs of the charges indicate directions of force—like charge signs repel, opposite charge signs repel.) So with the same amount of charge in each arrangement, the force will depend on the distance between charges—larger distance, smaller force.</p>'),
  ('ap-mock-physc-em-3_q19', 'ap-mock-physc-em-3', 19, false, 'B', 'AP Physics C: Electricity & Magnetism', 'medium', '<p class="ques"><strong><a href="ch19v.xhtml#rch19r_19" id="ch19r_19">19.</a></strong> A parallel plate capacitor is connected to a battery and charged fully. While still connected to the battery, a dielectric slab is inserted between the plates of the capacitor. Which of the following quantities will change when the slab is inserted?</p><p class="roman1t">I. The magnitude of the electric field between the plates</p><p class="roman2">II. The charge stored on the capacitor</p><p class="roman3">III. The potential difference between the plates</p>', '["<p>I only</p>","<p>II only</p>","<p>III only</p>","<p>I and III only</p>","<p>I, II, and III</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_19" id="rch19r_19">19.</a></strong> <strong>B—</strong>Voltage—that is, potential difference—is provided by a battery. Since the battery remains connected, the potential difference across the plates does not change. Electric field between two parallel plates is equal to <em>V/d</em>, the potential difference between the plates divided by the distance between the plates. Neither $V$ nor $d$ changes, so electric field doesn’t change. A dielectric material changes the capacitance of the capacitor (the formula for the capacitance of a parallel-plate capacitor is $C$ = <em>kɛ</em><sub>0</sub><em>A/d</em>—the effect of the dielectric slab is to increase the $k$ term). By $Q$ = <em>CV</em>, a bigger $C$ with an unchanged $V$ gives larger charge $Q$.</p>'),
  ('ap-mock-physc-em-3_q20', 'ap-mock-physc-em-3', 20, false, 'D', 'AP Physics C: Electricity & Magnetism', 'medium', '<p class="image"><img alt="Images" class="q-img" src="images/f0324-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="ques"><strong><a href="ch19v.xhtml#rch19r_20" id="ch19r_20">20.</a></strong> A metal sphere is attached to an insulating stand. Conducting wire 1 is connected between the sphere and a very large metal desk in electrical contact with the ground. A negatively charged glass rod is brought very close to the sphere without touching it, as shown. Next, wire 1 is cut. Finally, the glass rod is moved far away from the sphere. Which of the pictures of the sphere models the sign and distribution of charge on the surface of the sphere at the end of this process?</p>', '["<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0324-02.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0324-03.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0324-04.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0324-05.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0324-06.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_20" id="rch19r_20">20.</a></strong> <strong>D—</strong>Initially, the negative rod attracts positive charges in the conducting sphere and repels negative charges from the sphere into the ground. This makes the sphere have a net positive charge when the wire is cut. When the rod is moved far away, nothing is nearby to cause polarization. So the positive charges will distribute uniformly on the surface of the conductor, as in choice D.</p>'),
  ('ap-mock-physc-em-3_q21', 'ap-mock-physc-em-3', 21, false, 'B', 'AP Physics C: Electricity & Magnetism', 'medium', '<p class="ques"><strong><a href="ch19v.xhtml#rch19r_21" id="ch19r_21">21.</a></strong> A circular wire of radius $r$ is completely inside a magnetic field $B$, which increases with time $t$ according to the function $B$ = 3$t^{2}$. Which of the following is a correct expression for the EMF induced in the wire?</p>', '["<p>12<em>πr</em><sup>2</sup>$t$</p>","<p>6<em>πr</em><sup>2</sup>$t$</p>","<p>6<em>πrt</em><sup>2</sup></p>","<p>12<em>πrt</em></p>","<p>3<em>πr</em><sup>2</sup>$t^{2}$</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_21" id="rch19r_21">21.</a></strong> <strong>B—</strong>The EMF is given by the time derivative of the magnetic flux, which is $B$ times the area of the loop. The area of the loop is <em>πr</em><sup>2</sup><sub>,</sub> so the expression for flux is 3<em>πr</em><sup>2</sup>$t^{2}$<sub>.</sub> The time derivative of this expression is 6<em>πr</em><sup>2</sup>$t$.</p>'),
  ('ap-mock-physc-em-3_q22', 'ap-mock-physc-em-3', 22, false, 'A', 'AP Physics C: Electricity & Magnetism', 'medium', '<p class="image"><img alt="Images" class="q-img" src="images/f0324-07.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="ques"><strong><a href="ch19v.xhtml#rch19r_22" id="ch19r_22">22.</a></strong> Two parallel plates—the positive plate on the right—produce a uniform electric field of 80 N/C. The plates are separated by 16 cm. Point A is next to the positive plate, while point P is directly between the plates. How much kinetic energy is gained by a proton that is released from rest at point A when it reaches point P ?</p>', '["<p>1.0 × 10<sup>−18</sup> J</p>","<p>1.4 × 10<sup>−6</sup> J</p>","<p>2.1 × 10<sup>−6</sup> J</p>","<p>0 J</p>","<p>2.0 × 10<sup>−18</sup> J</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_22" id="rch19r_22">22.</a></strong> <strong>A—</strong>The kinetic energy gained by the proton is equal to the potential energy lost from A to B. The potential energy lost by the proton is $q$Δ$V$, where the change in electric potential Δ$V$ is <em>Ed</em> (derived from the equation for a uniform electric field, $E$ = Δ$V$/Δ$x$). The charge $q$ here is the charge of a proton; the distance $d$ is the distance from point A to point P, 0.08 m. Not the distance between plates, but the distance the proton moves! So the change in potential energy is (1.6 × 10<sup>-</sup>19 C)(80 N/C)(0.08 m) = 1.0 × 10<sup>-</sup>18 J.</p>'),
  ('ap-mock-physc-em-3_q23', 'ap-mock-physc-em-3', 23, false, 'D', 'AP Physics C: Electricity & Magnetism', 'medium', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="image"><img alt="Images" class="q-img" src="images/f0324-08.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">Questions 23 and 24: Two metal spheres, labeled 1 and 2, have different radii, as shown above. The spheres initially each carried positive charge +<em>Q,</em> but have been in electrical contact by means of a long metal wire for a long time.</p></div><p class="ques"><strong><a href="ch19v.xhtml#rch19r_23" id="ch19r_23">23.</a></strong> A rectangular wire loop is located above a wire carrying a current $I$, which increases with time $t$ according to the equation $I$ = 3$t$. Which of the following is correct about the current induced in the wire loop?</p>', '["<p>It is counterclockwise and increasing.</p>","<p>It is clockwise and increasing.</p>","<p>It remains zero.</p>","<p>It is counterclockwise and constant.</p>","<p>It is clockwise and constant.</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_23" id="rch19r_23">23.</a></strong> <strong>D—</strong>Induced current in the loop is, by Ohm’s law, the induced voltage (EMF) divided by the constant resistance of the loop. So whether induced current is constant depends on the EMF. Induced EMF is <em>dB/dt</em>. The magnetic field produced by a current-carrying wire depends linearly on $I$. The time derivative of $I$ is a constant value. Thus, the EMF is constant, and so is the induced current. Now, the direction of the magnetic field inside the wire is into the page by the second right-hand rule—point the thumb left with the current producing the field, the fingers curl into the page. This magnetic field is increasing because the current is increasing. So by Lenz’s law, increasing flux is into the page, making decreasing flux out of the page . . . and the induced current is found by pointing the right thumb with decreasing flux and curling the fingers. That’d be counterclockwise.</p>'),
  ('ap-mock-physc-em-3_q24', 'ap-mock-physc-em-3', 24, false, 'C', 'AP Physics C: Electricity & Magnetism', 'medium', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="image"><img alt="Images" class="q-img" src="images/f0324-08.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">Questions 23 and 24: Two metal spheres, labeled 1 and 2, have different radii, as shown above. The spheres initially each carried positive charge +<em>Q,</em> but have been in electrical contact by means of a long metal wire for a long time.</p></div><p class="ques"><strong><a href="ch19v.xhtml#rch19r_24" id="ch19r_24">24.</a></strong> Which of the following statements is true about the electric potential at the center of each sphere?</p>', '["<p>It is greater for sphere 1.</p>","<p>It is zero for both spheres.</p>","<p>It is the same positive value for both spheres.</p>","<p>It is the same negative value for both spheres.</p>","<p>It is greater for sphere 2.</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_24" id="rch19r_24">24.</a></strong> <strong>C—</strong>The electric field inside a conductor is zero everywhere—and these two spheres are a single conductor, so they have electric field zero everywhere. The equation $E$ = <em>−dV/dx</em> indicates that electric field tells how electric potential changes. Since electric field is zero, that means electric potential can’t change within the two spheres. But that potential isn’t zero! The electric potential is considered zero a long way away from any charges. Since these spheres have positive charge, they create positive potential outside of the spheres, and so they must have a uniform but positive potential everywhere inside.</p>'),
  ('ap-mock-physc-em-3_q25', 'ap-mock-physc-em-3', 25, false, 'D', 'AP Physics C: Electricity & Magnetism', 'medium', '<p class="image"><img alt="Images" class="q-img" src="images/f0324-09.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="ques"><strong><a href="ch19v.xhtml#rch19r_25" id="ch19r_25">25.</a></strong> Which of the following is true about the charge on each sphere after a long time?</p>', '["<p>Both spheres are positively charged, but sphere 1 holds a greater magnitude of charge.</p>","<p>Both spheres hold zero charge.</p>","<p>Sphere 2 holds positive charge, while sphere 1 holds negative charge.</p>","<p>Both spheres are positively charged, but sphere 2 holds a greater magnitude of charge.</p>","<p>Both spheres hold equal positive charge.</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_25" id="rch19r_25">25.</a></strong> <strong>D—</strong>The positive charge initially on the conducting spheres must redistribute at the surface (because no charge can remain inside a conductor). We know the electric potential is the same everywhere in and on each sphere. And electric potential at the surface is given by <em>kQ/r</em>. The sphere with the bigger radius must likewise hold the bigger charge.</p>'),
  ('ap-mock-physc-em-3_q26', 'ap-mock-physc-em-3', 26, false, 'A', 'AP Physics C: Electricity & Magnetism', 'hard', '<p class="image"><img alt="Images" class="q-img" src="images/f0325-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="ques"><strong><a href="ch19v.xhtml#rch19r_26" id="ch19r_26">26.</a></strong> Circuit 1 above shows three identical resistors labeled X, Y, and Z. In circuit 2, resistor Z is removed. Which of the following correctly compares the current through and voltage across resistor Y in circuit 2 compared to circuit 1?</p><p class="image"><img alt="Images" class="q-img" src="images/f0325-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="image"><img alt="Images" class="q-img" src="images/f0325-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Current through Y: Greater; Voltage across Y: Greater","Current through Y: Smaller; Voltage across Y: Smaller","Current through Y: Greater; Voltage across Y: Smaller","Current through Y: Smaller; Voltage across Y: Greater","Current through Y: Unchanged; Voltage across Y: Unchanged"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_26" id="rch19r_26">26.</a></strong> <strong>A—</strong>First, consider the whole circuit: the battery is the same, so the total voltage is unchanged. The equivalent resistance increases because we removed a parallel branch. By $V$ = <em>IR</em>, the total current must decrease. Now apply Ohm’s law to resistor X only: The reduced total current all runs through resistor X, but resistor X can’t change its own resistance. So by $V$ = <em>IR</em>, the voltage across bulb X is smaller than before. Kirchoff’s loop rule says that the voltage across X and Y must sum to V. . . so with smaller voltage across X, there must be greater voltage across Y. Now apply Ohm’s law to bulb Y: greater voltage with unchanged resistance means greater current, too.</p>'),
  ('ap-mock-physc-em-3_q27', 'ap-mock-physc-em-3', 27, false, 'C', 'AP Physics C: Electricity & Magnetism', 'hard', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="noindent">Questions 27 and 28: The diagram above shows two concentric spherical conducting shells. The net charge on the inner sphere is −2$Q$. The net charge on the outer sphere is +3$Q$.</p></div><p class="ques"><strong><a href="ch19v.xhtml#rch19r_27" id="ch19r_27">27.</a></strong> What is the charge that resides on the outer surface of the outer shell?</p>', '["<p>+2$Q$</p>","<p>zero</p>","<p>$+Q$</p>","<p>+3$Q$</p>","<p>+5$Q$</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_27" id="rch19r_27">27.</a></strong> <strong>C—</strong>The electric field inside a conductor is zero; charge can only sit on the surface of a conductor. Consider a Gaussian surface drawn inside the outer shell, going through point C. Since the shell is conducting, there must be zero electric field inside. Therefore, this Gaussian surface must enclose zero total charge. The inner shell contains charge −2$Q$, so the inner surface of the outer shell—the part inside this Gaussian surface—contains +2$Q$ to make the total charge inside the Gaussian surface zero. Then the remaining +1$Q$ of charge on the outer shell must be on the outer surface.</p>'),
  ('ap-mock-physc-em-3_q28', 'ap-mock-physc-em-3', 28, false, 'E', 'AP Physics C: Electricity & Magnetism', 'hard', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="noindent">Questions 27 and 28: The diagram above shows two concentric spherical conducting shells. The net charge on the inner sphere is −2$Q$. The net charge on the outer sphere is +3$Q$.</p></div><p class="ques"><strong><a href="ch19v.xhtml#rch19r_28" id="ch19r_28">28.</a></strong> Four positions are labeled in the diagram. Which of the following correctly ranks those positions by the magnitude of the electric field at each position?</p>', '["<p>A &gt; B &gt; D &gt; C</p>","<p>D &gt; C &gt; B &gt; A</p>","<p>A &gt; B &gt; C &gt; D</p>","<p>D = B &gt; A = C</p>","<p>B &gt; D &gt; A = C</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_28" id="rch19r_28">28.</a></strong> <strong>E—</strong>The electric field inside a conductor is zero, so C is the smallest. A Gaussian sphere through A encloses no charge, so the electric field at A is also zero. A Gaussian sphere at position B encloses −2$Q$; a Gaussian sphere at position D encloses $+Q$. So the sphere at D encloses a smaller magnitude of charge AND has a larger distance from the center, meaning D has a smaller electric field than B.</p>'),
  ('ap-mock-physc-em-3_q29', 'ap-mock-physc-em-3', 29, false, 'D', 'AP Physics C: Electricity & Magnetism', 'hard', '<p class="image"><img alt="Images" class="q-img" src="images/f0326-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="ques"><strong><a href="ch19v.xhtml#rch19r_29" id="ch19r_29">29.</a></strong> A uniform magnetic field of magnitude $B$ points at a 60<sup>o</sup> angle above the plane of a rectangular wire loop of dimensions $x$ by $y$ as shown above. What is the magnetic flux through the loop?</p>', '["<p><em>Bxy</em></p>","<p><em>Bx</em></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0326-02.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0326-03.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><em>By</em></p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_29" id="rch19r_29">29.</a></strong> <strong>D—</strong>Magnetic flux is <em>BA</em>, where $A$ is the area of the loop that is directly penetrated by the magnetic field. Here the magnetic field is penetrating the loop at an angle, so we need to look at the component of the magnetic field that penetrates directly, that is, at a 90<sup>o</sup> angle to the plane of the loop. That’s $B$ sin 60<sup>o</sup>, or <img alt="Images" class="q-img" src="images/f0341-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>. (Not cosine of 60 degrees . . . if you’re not sure, note that the magnetic field is closer to straight-through the loop than to along the loop, so we want the bigger component, and sin 60<sup>o</sup> is bigger than cos 60<sup>o</sup>.) And the area of the loop is <em>xy</em>.</p>'),
  ('ap-mock-physc-em-3_q30', 'ap-mock-physc-em-3', 30, false, 'E', 'AP Physics C: Electricity & Magnetism', 'hard', '<p class="image"><img alt="Images" class="q-img" src="images/f0326-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="ques"><strong><a href="ch19v.xhtml#rch19r_30" id="ch19r_30">30.</a></strong> A 50 V battery is connected to a 70 W resistor and a 0.50 mF capacitor in the circuit shown above. The capacitor is uncharged when the switch is closed. Sometime later when the current through the resistor is 0.43 A, how much charge is stored on the capacitor?</p>', '["<p>0 μC</p>","<p>35 μC</p>","<p>25 μC</p>","<p>15 μC</p>","<p>10 μC</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_30" id="rch19r_30">30.</a></strong> <strong>E—</strong>When the current is 0.43 A, the voltage across the resistor is (70 Ω)(0.43 A) = 30 V. That means the voltage across the capacitor is 20 V by Kirchoff’s loop rule, to add to the total 50 V in the battery. For a capacitor, the charge stored is given by $Q$ = <em>CV</em>. Here that’s (0.50 μF)(20 V) = 10 μC.</p>'),
  ('ap-mock-physc-em-3_q31', 'ap-mock-physc-em-3', 31, false, 'C', 'AP Physics C: Electricity & Magnetism', 'hard', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="image"><img alt="Images" class="q-img" src="images/f0326-05.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">Questions 31 and 32: In the circuit above, the switch S has initially been closed for a very long time. Then the switch is opened.</p></div><p class="ques"><strong><a href="ch19v.xhtml#rch19r_31" id="ch19r_31">31.</a></strong> Immediately before the switch is opened, what is the current through $R_{1}$?</p>', '["<p>1.5 A</p>","<p>0.33 A</p>","<p>1.0 A</p>","<p>0.5 A</p>","<p>0 A</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_31" id="rch19r_31">31.</a></strong> <strong>C—</strong>Inductors resist changes in current. Since the current has been flowing for a long time and thus is steady, the inductor has no effect on the circuit. It just acts as a bare wire. So the two resistors are both in parallel with the battery, taking the voltage of the battery. The current through $R_{1}$ is 12 V / 12 Ω = 1.0 A.</p>'),
  ('ap-mock-physc-em-3_q32', 'ap-mock-physc-em-3', 32, false, 'D', 'AP Physics C: Electricity & Magnetism', 'hard', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="image"><img alt="Images" class="q-img" src="images/f0326-05.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">Questions 31 and 32: In the circuit above, the switch S has initially been closed for a very long time. Then the switch is opened.</p></div><p class="ques"><strong><a href="ch19v.xhtml#rch19r_32" id="ch19r_32">32.</a></strong> Immediately after the switch is opened, what is the current through $R_{1}$?</p>', '["<p>1.5 A</p>","<p>0.33 A</p>","<p>1.0 A</p>","<p>0.5 A</p>","<p>0 A</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_32" id="rch19r_32">32.</a></strong> <strong>D—</strong>Inductors resist changes in current. So the current through the inductor now is the same as the current through the inductor before the switch was closed. The inductor was in series with the 24 Ω resistor, which carried 12 V/24 Ω = 0.5 A of current. With the battery removed, the resistor $R_{1}$ is in series with $R_{2}$, so it must carry the 0.5 A of current.</p>'),
  ('ap-mock-physc-em-3_q33', 'ap-mock-physc-em-3', 33, false, 'E', 'AP Physics C: Electricity & Magnetism', 'hard', '<p class="image"><img alt="Images" class="q-img" src="images/f0326-06.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="ques"><strong><a href="ch19v.xhtml#rch19r_33" id="ch19r_33">33.</a></strong> An electron is initially moving to the left with speed $v$ parallel to a wire carrying a constant rightward current $I$ as shown above. Which of the following indicates the direction of the magnetic force on the electron at the instant shown, and whether the long-term path of the electron is circular or not circular?</p><p class="image"><img alt="Images" class="q-img" src="images/f0326-07.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Direction of Force: Upward (away from wire); Path: Circular","Direction of Force: Upward (away from wire); Path: Not circular","Direction of Force: Zero; Path: Straight line","Direction of Force: Downward (toward wire); Path: Circular","Direction of Force: Downward (toward wire); Path: Not circular"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_33" id="rch19r_33">33.</a></strong> <strong>E—</strong>The magnetic field produced by a current-carrying wire is given by the second right-hand rule: Point the thumb to the right and curl. The fingers point out of the page above the wire, so that’s the direction of the magnetic field. Now the force on the electron is given by the first right-hand rule: Point with the velocity, curl the fingers out of the page with the magnetic field, and the thumb gives the upward force on a positive charge. An electron has a negative charge, though, so the force is downward. Because the magnetic force is perpendicular to the velocity, the path is initially circular. But because the magnetic field isn’t uniform (it drops off the farther you get from the current-carrying wire), the magnetic force isn’t always of the same magnitude, and so the path becomes not circular.</p>'),
  ('ap-mock-physc-em-3_q34', 'ap-mock-physc-em-3', 34, false, 'E', 'AP Physics C: Electricity & Magnetism', 'hard', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="noindent">Questions 34 and 35: Two small objects, each carrying negative electric charge of magnitude 2.0 μC, are placed on the $x$-axis at positions $x_{a}$ = +4.0 cm and $x_{b}$ = -4.0 cm.</p></div><p class="ques"><strong><a href="ch19v.xhtml#rch19r_34" id="ch19r_34">34.</a></strong> What is the electric potential at position $x$ = 0?</p>', '["<p>+900,000 V</p>","<p>+450,000 V</p>","<p>0 V</p>","<p>-450,000 V</p>","<p>-900,000 V</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_34" id="rch19r_34">34.</a></strong> <strong>E—</strong>Each charge contributes a potential of <em>kQ/d</em> to the total potential at the origin. That’s (9 × 10<sup>9</sup> N/$m^{2}$/$C^{2}$)(−2 × 10<sup>−6</sup> C)/(0.04 m) = −450,000 V per charge. Both charges are negative and so produce negative electric potentials, and electric potentials add as scalars, making the total potential −900,000 V.</p>'),
  ('ap-mock-physc-em-3_q35', 'ap-mock-physc-em-3', 35, false, 'D', 'AP Physics C: Electricity & Magnetism', 'hard', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="noindent">Questions 34 and 35: Two small objects, each carrying negative electric charge of magnitude 2.0 μC, are placed on the $x$-axis at positions $x_{a}$ = +4.0 cm and $x_{b}$ = -4.0 cm.</p></div><p class="ques"><strong><a href="ch19v.xhtml#rch19r_35" id="ch19r_35">35.</a></strong> What is the magnitude of the electric field at position $x$ = 0?</p>', '["<p>44 N/C</p>","<p>2.2 million N/C</p>","<p>1.1 million N/C</p>","<p>0 N/C</p>","<p>22 N/C</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19r.xhtml#ch19r_35" id="rch19r_35">35.</a></strong> <strong>D—</strong>By $E$ = <em>kQ/$d^{2}$</em>, each charge creates an electric field of the same magnitude (because both are of the same amount of charge, located the same distance from the origin). A negative charge produces an electric field toward that charge. So the fields produced by each charge are pointed in opposite directions. Electric fields add as vectors; equal magnitude vectors pointing in opposite directions subtract to zero.</p>'),
  ('ap-mock-physc-em-3_q36', 'ap-mock-physc-em-3', 36, true, 'FRQ_MANUAL_EVALUATION', 'AP Physics C: Electricity & Magnetism Free Response', 'hard', '<div class=''frq-prompt''><h3>E&M 1</h3><p class="ques"><strong><a href="ch19w.xhtml#rch19s_1" id="ch19s_1">1.</a></strong> A rod of length $L$ carrying positive charge has uniform linear charge density <em>ℓ</em>. Points A and B are located distances $d$ and 2$d$, respectively, from the center of the line.</p><p class="alphabrt">(a) Consider the situation when $L$ is much, much greater than $d$.</p><p class="roman4r">i. Derive an expression for the magnitude of the electric field at point A. Express your answer in terms of given variables and fundamental constants.</p><p class="roman4r">ii. On the dot below, draw the direction of the electric field at point A.</p><p class="image"><img alt="Images" class="q-img" src="images/f0328-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="roman4r">iii. Let the magnitude of the electric field at point A be $E_{A1}$. Is the magnitude of the electric field at point B greater than, less than, or equal to ½$E_{A1}$? Justify your answer.</p><p class="roman4r">iv. Derive an expression for the electric potential difference between points A and B. Express your answer in terms of given variables and fundamental constants.</p><p class="alphabr">(B) Now consider the situation when $L$ is NOT much greater than $d$.</p><p class="roman4r">i. In terms of given variables and fundamental constants, derive an integral with limits that could be evaluated to determine the magnitude of the electric field at point A.</p><p class="roman4r">ii. On the dot below, draw the direction of the electric field at point A.</p><p class="image"><img alt="Images" class="q-img" src="images/f0328-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="roman4r">iii. Let the magnitude of the electric field in this case at point A be $E_{A2}$. Is $E_{A2}$ greater than, less than, or equal to $E_{A1}$? Justify your answer.</p><p class="image"><img alt="Images" class="q-img" src="images/f0328-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p></div>', '["Submit analytical derivation in workspace."]'::jsonb, '<p class="ques"><strong><a href="ch19s.xhtml#ch19s_1" id="rch19s_1">1.</a></strong> (15 points)</p><p class="alphabrt">(a)</p><p class="roman4r"> i. Use Gauss’s law with a cylindrical Gaussian surface. Because the length of the rod is big now compared to $d$, the electric field will always point straight away from the rod—so straight through the surface. Then Gauss’s law says <em>EA</em> = $Q$/<em>ɛ</em><sub>0</sub>. Here the area A of the cylindrical Gaussian surface $A$ is 2<em>πrL</em>; we’re looking for the electric field a distance $d$ from the rod, so replace $r$ with $d$. The charge $Q$ enclosed by the surface is <em>λL</em>. Solve for $E$ to get $E$ = <em>λ/</em>(2<em>πdɛ</em><sub>0</sub>).</p><p class="hangp"><strong>1 pt</strong> for attempting to use Gauss’s law reasonably</p><p class="hangp"><strong>1 pt</strong> for the correct area term</p><p class="hangp"><strong>1 pt</strong> for the correct expression for the charge enclosed</p><p class="hangp"><strong>1 pt</strong> for the correct answer</p><p class="roman4rtb"> ii.</p><p class="hangp"><strong>1 pt</strong> for an arrow straight up the page</p><p class="image"><img alt="Images" class="q-img" src="images/f0342-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="roman4r">iii. The electric field expression is inversely related to the first power of $r$, the distance from the rod. That means doubling $r$ cuts the electric field in half. (If you stated an incorrect expression in part (i) that has a clear $r$ dependence, then award credit here for an answer and justification consistent with that incorrect equation.)</p><p class="hangp"><strong>1 pt</strong> for the answer</p><p class="hangp"><strong>1 pt</strong> for a correct justification</p><p class="roman4rtb">iv.</p><p class="hangp"><strong>1 pt</strong> for substituting an electric field expression from part (i) into <img alt="Images" class="q-img" src="images/f0342-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>.</p><p class="hangp"><strong>1 pt</strong> for correct limits and an attempt to evaluate the integral with respect to $r$</p><p class="hangp"><strong>1 pt</strong> for the correct answer in any form that has correctly evaluated the correct integral</p><p class="image"><img alt="Images" class="q-img" src="images/f0342-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="alphabrt">(b)</p><p class="roman4r"> i.</p><p class="hangp"><strong>1 pt</strong> for using (not just writing) the expression <img alt="Images" class="q-img" src="images/f0343-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="hangp"><strong>1 pt</strong> for substituting <em>dq</em> = <em>λdx</em></p><p class="hangp"><strong>1 pt</strong> for using geometry to write $r$, the distance from a position on the rod to point A, in terms of $x$ and $d$ as shown in the diagram below</p><p class="hangp"><strong>1 pt</strong> for correct limits</p><p class="image"><img alt="Images" class="q-img" src="images/f0343-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="roman4rtb"> ii.</p><p class="hangp"><strong>1 pt</strong> for an upward pointing arrow</p><p class="image"><img alt="Images" class="q-img" src="images/f0343-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-mock-physc-em-3_q37', 'ap-mock-physc-em-3', 37, true, 'FRQ_MANUAL_EVALUATION', 'AP Physics C: Electricity & Magnetism Free Response', 'hard', '<div class=''frq-prompt''><h3>E&M 2</h3><p class="ques"><strong><a href="ch19w.xhtml#rch19s_2" id="ch19s_2">2.</a></strong> A single rectangular copper coil of dimensions $s$ by <em>ℓ</em> is moving to the right with speed $v$. Let position $x$ = 0 be where the right-hand edge of the coil enters a uniform magnetic field of magnitude $B$ pointing into the page. Let position $x = D$ be where the left-hand edge of the coil exits the field.</p><p class="alphar1">(a) i. On the axes below, sketch the shape of a graph of the current induced in the coil as a function of position, from $x$ = 0 to $x = D$ + <em>ℓ</em>. Represent clockwise current as positive.</p><p class="image"><img alt="Images" class="q-img" src="images/f0329-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="roman4r">ii. Justify the shape of your graph for the region $x$ = 0 to $x$ = <em>ℓ</em>.</p><p class="roman4r">iii. In terms of given variables and fundamental constants, write an expression for the maximum induced EMF in the coil.</p><p class="alphabr">(b) Describe any changes to your graph if instead a copper coil of the same rectangular dimensions but consisting of two loops of wire moved with speed $v$ through the magnetic field. Justify your response.</p><p class="alphabr">(c) Now the original single coil enters the field as before, but the coil speeds up with acceleration $a$ starting from rest at position $x$ = 0.</p><p class="roman4r">i. Consider only the time during which the coil is entering the magnetic field. Derive an expression for the induced EMF in the coil as a function of position $x$. Express your answer in terms of given variables and fundamental constants.</p><p class="roman4r">ii. Sketch the shape of a graph of the current induced in this coil as a function of position, from $x$ = 0 to $x = D$ + <em>ℓ</em>.</p><p class="image"><img alt="Images" class="q-img" src="images/f0329-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p></div>', '["Submit analytical derivation in workspace."]'::jsonb, '<p class="ques"><strong><a href="ch19s.xhtml#ch19s_2" id="rch19s_2">2.</a></strong> (15 points)</p><p class="alphabrt">(a)</p><p class="roman4r"> i.</p><p class="hangp"><strong>1 pt</strong> for zero current between <em>ℓ</em> and $D$</p><p class="hangp"><strong>1 pt</strong> for a horizontal line between 0 and <em>ℓ</em></p><p class="hangp"><strong>1 pt</strong> for a horizontal line on the opposite side of the axis between $D$ and $D$ + <em>ℓ</em></p><p class="hangp"><strong>1 pt</strong> for a graph entirely below the horizontal axis between 0 and <em>ℓ</em></p><p class="roman4rtb"> ii.</p><p class="hangp"><strong>1 pt</strong> For explaining that in general equation <em>ɛ</em> = <em>Bℓv</em>, here each term is unchanging, so the EMF and hence the current isn’t changing either</p><p class="image"><img alt="Images" class="q-img" src="images/f0343-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="roman4rtb"> ii.</p><p class="hangp"><strong>1 pt</strong> for the correct answer, <em>Bsv.</em> (Not <em>Bℓv</em>, because $s$ is the side of the rectangle that is not changing how much is inside the field.)</p><p class="alphabrc">(b)</p><p class="hangp"><strong>1 pt</strong> for recognizing that the magnetic flux or the induced EMF is doubled</p><p class="hangp"><strong>1 pt</strong> for recognizing that the coil’s resistance is also doubled</p><p class="hangp"><strong>1 pt</strong> for using Ohm’s law ($I$ = EMF/resistance) to determine that the induced current is unchanged</p><p class="alphabrt">(c)</p><p class="roman4r"> i. Answer is <img alt="Images" class="q-img" src="images/f0344-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>.</p><p class="hangp"><strong>1 pt</strong> for using the definition of induced EMF, <em>ɛ</em> = $d$Φ<em>/dt</em> or <em>ɛ</em> = <em>Bsv</em> (full credit whether or not negative sign is included)</p><p class="hangp"><strong>1 pt</strong> for substituting <img alt="Images" class="q-img" src="images/f0344-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="roman4rtb"> ii.</p><p class="hangp"><strong>1 pt</strong> for the first segment starting at zero and concave toward the horizontal axis (This point is awarded if the shape is correct, even if drawn above the axis.)</p><p class="hangp"><strong>1 pt</strong> for a curved segment between $D$ and $D$ + <em>ℓ</em></p><p class="hangp"><strong>1 pt</strong> for this last segment starting at a greater vertical value than the first segment ended</p><p class="hangp"><strong>1 pt</strong> for this last segment being concave toward the horizontal axis (Based on the answer to part (i), the square root function indicates the concave-down shape of the graph. The faster the coil moves, the more induced EMF/current by <em>ɛ</em> = <em>Bsv</em>. And the coil moves faster farther along the track because of the acceleration.)</p><p class="image"><img alt="Images" class="q-img" src="images/f0344-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-mock-physc-em-3_q38', 'ap-mock-physc-em-3', 38, true, 'FRQ_MANUAL_EVALUATION', 'AP Physics C: Electricity & Magnetism Free Response', 'hard', '<div class=''frq-prompt''><h3>E&M 3</h3><p class="ques"><strong><a href="ch19w.xhtml#rch19s_3" id="ch19s_3">3.</a></strong> In the laboratory, you are given a wire coil of unknown inductance. You have available digital ammeters, digital voltmeters, and a variety of known resistors and capacitors.</p><p class="alphabrt">(a) Using the available equipment, describe an experimental procedure that could determine the inductance of the wire coil. Give enough detail that another student could reproduce your method.</p><p class="alphabr">(b) Draw a labeled diagram showing how the inductor is connected to the other equipment in your procedure.</p><p class="alphabr">(c) Explain how the inductance of the coil will be determined from the measurements made.</p><p class="image"><img alt="Images" class="q-img" src="images/f0329-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="alphabr">(d) The coil is determined to have an inductance of 25 mH. It is connected to a 15 V battery, a 100 W resistor, and a 50 W resistor in the circuit shown. The circuit has been connected for a long time with the switch in position A. Next, the switch is thrown to position B.</p><p class="roman4r">i. Determine the current through the inductor immediately before the switch is thrown. Briefly justify your answer.</p><p class="roman4r">ii. Determine the current through the inductor immediately after the switch is thrown. Briefly justify your answer.</p><p class="roman4r">iii. Determine the current through the inductor after the switch has been in position B for a long time. Briefly justify your answer.</p><p class="center1"><strong>STOP. End of Physics C—Electricity and Magnetism Practice Exam 3—Free-Response Questions</strong></p></div>', '["Submit analytical derivation in workspace."]'::jsonb, '<p class="ques"><strong><a href="ch19s.xhtml#ch19s_3" id="rch19s_3">3.</a></strong> (15 points)</p><p class="quesna">Parts (a), (b), and (c) are graded all together. As long as the elements that earn points are there somewhere, award credit.</p><p class="alphabrt">(a) Connect the inductor to a charged capacitor. Use a digital voltmeter to measure the voltage across the inductor as a function of time. Determine the period of the oscillating voltage from the voltmeter’s output.</p><p class="quesna">This example uses a circuit with a capacitor and inductor; something similar can be done with a resistor-inductor circuit and its time constant, or with other circuits.</p><p class="hangp"><strong>1 pt</strong> for a conceptually plausible plan to collect data that could lead to a calculation of $L$</p><p class="hangp"><strong>1 pt</strong> for a well-specified procedure that indicates correct use of appropriate equipment to measure the required quantities</p><p class="hangp"><strong>1 pt</strong> for using more than a single measurement, that is, a graph or multiple trials to reduce error</p><p class="alphabrt">(b) An example consistent with the method above:</p><p class="image"><img alt="Images" class="q-img" src="images/f0345-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="hangp"><strong>1 pt</strong> for drawing a diagram of a circuit that would function, that is, a complete circuit</p><p class="hangp"><strong>1 pt</strong> for correctly placing an ammeter or voltmeter (an ammeter must be connected in series, a voltmeter in parallel)</p><p class="hangp"><strong>1 pt</strong> for correct placement of all other equipment specified in part (a)</p><p class="quesna">(c) An example continued from above:</p><p class="quesna">The reading on the voltmeter will oscillate with a period given by <img alt="Images" class="q-img" src="images/f0345-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>. On the voltmeter output, look at the time from one maximum voltage to the next—that’s the period. Plug in that period and the capacitance $C$, and you can solve for the inductance $L$.</p><p class="hangp"><strong>1 pt</strong> for recognizing the existence of a period for an <em>LC</em> circuit, or a time constant for an <em>LR</em> circuit</p><p class="hangp"><strong>1 pt</strong> for correctly relating the period/time constant to other circuit properties</p><p class="hangp"><strong>1 pt</strong> for explaining how to find the period or time constant from the collected data</p><p class="roman4rtb"> i. The battery has been connected for a long time, so the inductor acts as a bare wire. The resistance of the active branch is 100 Ω, the battery is 15 V, so the current is $I$ = <em>V/R</em> = 15 V/100 Ω = 0.15 A.</p><p class="hangp"><strong>1 pt</strong> for the correct answer</p><p class="hangp"><strong>1 pt</strong> for a correct verbal justification</p><p class="roman4rtb"> ii. The inductor resists changes in current. Since the current was 0.15 A right before the switch was closed, the initial current after the switch is closed is also 0.15 A.</p><p class="hangp"><strong>1 pt</strong> for the correct answer</p><p class="hangp"><strong>1 pt</strong> for a correct verbal justification</p><p class="roman4rtb">iii. After a long time, the current again reaches a steady state with the inductor acting as a bare wire. The total resistance this time is 150 Ω, so the current is 15 V/150 Ω = 0.10 A.</p><p class="hangp"><strong>1 pt</strong> for the correct answer</p><p class="hangp"><strong>1 pt</strong> for a correct verbal justification</p><h4 class="h4c">AP Physics C—Electricity and Magnetism</h4><p class="centera"><strong>Full Exam Scoring</strong></p><p class="noindentt1">Multiple-Choice: Number Correct______(35 max)</p><p class="noindentt1">Free-Response: Question 1______(15 max)</p><p class="noindentq">Question 2______(15 max)</p><p class="noindentq">Question 3______(15 max)</p><p class="noindentt1">Total Free-Response______(45 max)</p><p class="noindentt1">1.286 × Multiple-Choice + Free-Response = Raw Score______(90 max)</p><p class="image"><img alt="Images" class="q-img" src="images/f0346-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-mock-physc-em-3_q39', 'ap-mock-physc-em-3', 39, false, 'E', 'Practice Test 1 – E&M', 'medium', 'Consider the circuit shown, which contains two identical lightbulbs connected to a battery. The top bulb’s intensity will', '["decrease slightly if either of the two switches is closed.","decrease slightly if S1 is closed but not if S2 is closed.","decrease slightly if S2 is closed but not if S1 is closed.","remain unchanged if S2 is closed but go out completely if S1 is closed.","remain unchanged if S1 is closed but go out completely if S2 is closed."]'::jsonb, '(E) If S1 is closed, a parallel circuit with an equivalent resistance of R/2 will be created. Thus the current drawn from the battery will double and half that current will go through the top bulb, yielding the same current that flowed before the switch S1 was closed. If S2 is closed, creating a path of zero resistance, no current will pass through either bulb.'),
  ('ap-mock-physc-em-3_q40', 'ap-mock-physc-em-3', 40, false, 'D', 'Practice Test 1 – E&M', 'medium', 'What is the voltage V in the circuit shown in the figure?', '["1 V","2 V","4 V","6 V","8 V"]'::jsonb, '(D) A Kirchhoff’s loop equation for the right loop [clockwise: 8 V − (1 A)(4 Ω) − (I)(2 Ω) = 0] reveals that the current i moving from point A to point B must be 2.0 A (upward). A node equation at point A then shows the current through the left 2 Ω resistor must be 1.0 A flowing to the right. Finally, a Kirchhoff’s loop equation for the left loop [clockwise: V − (1 A)(2 Ω) − (2 A)(2 Ω) = 0] allows us to calculate the voltage of the battery as 6 V.'),
  ('ap-mock-physc-em-3_q41', 'ap-mock-physc-em-3', 41, false, 'D', 'Practice Test 1 – E&M', 'medium', 'A battery of voltage V0 is connected in series with a resistor of resistance R and an uncharged capacitor C at t = 0. What is the current in the circuit at the instant t = R C?', '["(V0 / R) * (1 - 1/e)","Zero","(V0 / R) * (1 - 1/e^2)","(V0 / R) * (1/e)","V0 / R"]'::jsonb, 'The current in an RC series charging circuit is I(t) = (V0 / R) e^{-t / (RC)}. At t = RC, the current is I(RC) = (V0 / R) e^{-1} = (V0 / R) * (1/e).'),
  ('ap-mock-physc-em-3_q42', 'ap-mock-physc-em-3', 42, false, 'A', 'Practice Test 1 – E&M', 'medium', 'A sphere of radius R contains a negative charge with a charge density given by the function \rho = −cr4, where r equals the distance from the center of the sphere. Where does the electric field have the smallest magnitude?', '["at the center of the sphere","at some point between the center of the sphere and the surface of the sphere","at the surface of the sphere","outside the sphere","The electric field is constant in space."]'::jsonb, '(A) At the center of the sphere, as a result of symmetry, the electric field is zero. At every other point in space, the electric field is nonzero.'),
  ('ap-mock-physc-em-3_q43', 'ap-mock-physc-em-3', 43, false, 'E', 'Practice Test 1 – E&M', 'medium', 'Referring to the charge distribution described in question 4, where is the potential smallest in magnitude?', '["at the center of the sphere","at some point between the center of the sphere and the surface of the sphere","at the surface of the sphere","outside the sphere","at infinity"]'::jsonb, '(E) The electric field at all points in space is directed toward the center of the sphere because the sphere is negatively charged. Electric fields always point in the direction of decreasing potential. With the conventional choice of zero potential at infinity, the potential will be negative everywhere else and thus smallest in magnitude at infinity.'),
  ('ap-mock-physc-em-3_q44', 'ap-mock-physc-em-3', 44, false, 'A', 'Practice Test 1 – E&M', 'medium', 'A loop is moved out of a magnetic field at constant velocity as shown. Which of the following statements about the induced current in the loop and the applied force on the loop is correct? (The magnetic field points into the page.)', '["The current is clockwise, and the applied force is to the right.","The current is clockwise, and the applied force is to the left.","The current is counterclockwise, and the applied force is to the right.","The current is counterclockwise, and the applied force is to the left.","The current is counterclockwise, and the applied force is into the page."]'::jsonb, '(A) To oppose the decrease in flux going into the page, the current flows clockwise. What magnetic force does this produce on the loop? The magnetic forces on the top and bottom of the loop, which point up and down, respectively, cancel each other out. The force on the left side of the loop points to the left, and there is zero force on the right side of the loop (because the magnetic field is zero in this region), so the net magnetic force points to the left. Because the applied force must cancel out this magnetic force in order for the loop to move at constant velocity, it then points to the right.'),
  ('ap-mock-physc-em-3_q45', 'ap-mock-physc-em-3', 45, false, 'C', 'Practice Test 1 – E&M', 'medium', 'Which of the following statements about electric field lines and equipotential curves is false?', '["Equipotential lines are always perpendicular to electric field lines.","The electric field magnitude is greater in regions where the density of electric field lines is greater.","Electric field lines begin and end only at the locations of negative and positive charges, respectively.","The work required to move a charge along an equipotential line is zero.","Electric field lines never penetrate metals."]'::jsonb, '(C) Electric field lines begin and end at locations of positive and negative charges, respectively (not the other way around).'),
  ('ap-topic-physc-fields-drills_q1', 'ap-topic-physc-fields-drills', 1, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fields', 'medium', '<p><strong>Electric and Magnetic Fields Drill #1:</strong> Determine the magnitude and direction of the electric and magnetic forces acting on the particle:</p><p class="ques"><strong>1.</strong> an e- at rest</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>1.</strong> No force or acceleration, $v$ = 0.</p>'),
  ('ap-topic-physc-fields-drills_q2', 'ap-topic-physc-fields-drills', 2, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fields', 'medium', '<p><strong>Electric and Magnetic Fields Drill #2:</strong> Determine the magnitude and direction of the electric and magnetic forces acting on the particle:</p><p class="quesa"><strong>2.</strong> an e- moving ↑ at 2 m/s</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>2.</strong> <img alt="Images" class="q-img" src="images/e0067-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-fields-drills_q3', 'ap-topic-physc-fields-drills', 3, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fields', 'medium', '<p><strong>Electric and Magnetic Fields Drill #3:</strong> Determine the magnitude and direction of the electric and magnetic forces acting on the particle:</p><p class="quesa"><strong>3.</strong> an e- moving ← at 2 m/s</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>3.</strong> No force or acceleration, sin $\theta$ = 0.</p>'),
  ('ap-topic-physc-fields-drills_q4', 'ap-topic-physc-fields-drills', 4, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fields', 'medium', '<p><strong>Electric and Magnetic Fields Drill #4:</strong> Determine the magnitude and direction of the electric and magnetic forces acting on the particle:</p><p class="quesa"><strong>4.</strong> a proton moving ⊙ at 2 m/s</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>4.</strong> <img alt="Images" class="q-img" src="images/e0067-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-fields-drills_q5', 'ap-topic-physc-fields-drills', 5, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fields', 'medium', '<p><strong>Electric and Magnetic Fields Drill #5:</strong> Determine the magnitude and direction of the electric and magnetic forces acting on the particle:</p><p class="quesa"><strong>5.</strong> an e- moving up and to the right, at an angle of 30° to the horizontal, at 2 m/s</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>5.</strong> <img alt="Images" class="q-img" src="images/e0068-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-fields-drills_q6', 'ap-topic-physc-fields-drills', 6, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fields', 'medium', '<p><strong>Electric and Magnetic Fields Drill #6:</strong> Determine the magnitude and direction of the electric and magnetic forces acting on the particle:</p><p class="quesa"><strong>6.</strong> an e- moving up and to the left, at an angle of 30° to the horizontal, at 2 m/s</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>6.</strong> <img alt="Images" class="q-img" src="images/e0068-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-fields-drills_q7', 'ap-topic-physc-fields-drills', 7, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fields', 'medium', '<p><strong>Electric and Magnetic Fields Drill #7:</strong> Determine the magnitude and direction of the electric and magnetic forces acting on the particle:</p><p class="quesa"><strong>7.</strong> a positron moving up and to the right, at an angle of 30° to the horizontal, at 2 m/s</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>7.</strong> <img alt="Images" class="q-img" src="images/e0068-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-fields-drills_q8', 'ap-topic-physc-fields-drills', 8, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fields', 'medium', '<p><strong>Electric and Magnetic Fields Drill #8:</strong> Determine the magnitude and direction of the electric and magnetic forces acting on the particle:</p><p class="quesa"><strong>8.</strong> an e- moving → at 2 m/s</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>8.</strong> No force or acceleration, sin $\theta$ = 0.</p>'),
  ('ap-topic-physc-fields-drills_q9', 'ap-topic-physc-fields-drills', 9, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fields', 'medium', '<p><strong>Electric and Magnetic Fields Drill #9:</strong> Determine the magnitude and direction of the electric and magnetic forces acting on the particle:</p><p class="quesa"><strong>9.</strong> a proton moving ⊗ at 2 m/s</p><p class="image"><img alt="Images" class="q-img" src="images/f0067-07.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">The electric field above has magnitude 3.0 N/C. For each of the following particles placed in the field, find (a) the force exerted by the electric field on the particle, and (b) the acceleration of the particle. Be sure to give magnitude <em>and direction</em> in each case.</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>9.</strong> <img alt="Images" class="q-img" src="images/e0068-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-fields-drills_q10', 'ap-topic-physc-fields-drills', 10, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fields', 'medium', '<p><strong>Electric and Magnetic Fields Drill #10:</strong> Determine the magnitude and direction of the electric and magnetic forces acting on the particle:</p><p class="ques"><strong>10.</strong> an e- at rest</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>10.</strong> <img alt="Images" class="q-img" src="images/e0068-05.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-fields-drills_q11', 'ap-topic-physc-fields-drills', 11, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fields', 'medium', '<p><strong>Electric and Magnetic Fields Drill #11:</strong> Determine the magnitude and direction of the electric and magnetic forces acting on the particle:</p><p class="quesa"><strong>11.</strong> a proton at rest</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>11.</strong> <img alt="Images" class="q-img" src="images/e0068-06.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-fields-drills_q12', 'ap-topic-physc-fields-drills', 12, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fields', 'medium', '<p><strong>Electric and Magnetic Fields Drill #12:</strong> Determine the magnitude and direction of the electric and magnetic forces acting on the particle:</p><p class="quesa"><strong>12.</strong> a positron at rest</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>12.</strong> <img alt="Images" class="q-img" src="images/e0068-07.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-fields-drills_q13', 'ap-topic-physc-fields-drills', 13, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fields', 'medium', '<p><strong>Electric and Magnetic Fields Drill #13:</strong> Determine the magnitude and direction of the electric and magnetic forces acting on the particle:</p><p class="quesa"><strong>13.</strong> an e- moving ↑ at 2 m/s</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>13.</strong> <img alt="Images" class="q-img" src="images/e0068-08.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-fields-drills_q14', 'ap-topic-physc-fields-drills', 14, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fields', 'medium', '<p><strong>Electric and Magnetic Fields Drill #14:</strong> Determine the magnitude and direction of the electric and magnetic forces acting on the particle:</p><p class="quesa"><strong>14.</strong> an e- moving → at 2 m/s</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>14.</strong> <img alt="Images" class="q-img" src="images/e0068-09.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-fields-drills_q15', 'ap-topic-physc-fields-drills', 15, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fields', 'medium', '<p><strong>Electric and Magnetic Fields Drill #15:</strong> Determine the magnitude and direction of the electric and magnetic forces acting on the particle:</p><p class="quesa"><strong>15.</strong> a proton moving ⊙ at 2 m/s</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>15.</strong> <img alt="Images" class="q-img" src="images/e0068-10.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-fields-drills_q16', 'ap-topic-physc-fields-drills', 16, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fields', 'medium', '<p><strong>Electric and Magnetic Fields Drill #16:</strong> Determine the magnitude and direction of the electric and magnetic forces acting on the particle:</p><p class="quesa"><strong>16.</strong> an e- moving ← at 2 m/s</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>16.</strong> <img alt="Images" class="q-img" src="images/e0068-11.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-fields-drills_q17', 'ap-topic-physc-fields-drills', 17, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fields', 'medium', '<p><strong>Electric and Magnetic Fields Drill #17:</strong> Determine the magnitude and direction of the electric and magnetic forces acting on the particle:</p><p class="quesa"><strong>17.</strong> a positron moving up and to the right, at an angle of 30° to the horizontal, at 2 m/s</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>17.</strong> <img alt="Images" class="q-img" src="images/e0068-12.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><h4 class="h4">Step-by-Step Solution to #2:</h4><p class="noindent">(a) The magnetic force on a charge is given by $F$ = <em>qvB</em> sin $\theta$. Since the velocity is perpendicular to the magnetic field, $\theta$ = 90°, and sin $\theta$ = 1. The charge $q$ is the amount of charge on an electron, 1.6 × 10<sup>−19</sup> C. $v$ is the electron’s speed, 2 m/s. $B$ is the magnetic field, 3 T.</p><p class="image"><img alt="Images" class="q-img" src="images/e0068-13.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">The direction is given by the right-hand rule. Point your fingers in the direction of the electron’s velocity, toward the top of the page; curl your fingers in the direction of the magnetic field, to the right; your thumb points into the page. Since the electron has a negative charge, the force points opposite your thumb, or out of the page.</p><p class="noindentt">(b) Even though we’re dealing with a magnetic force, we can still use Newton’s second law. Since the magnetic force is the only force acting, just set this force equal to <em>ma</em> and solve. The direction of the acceleration must be in the same direction as the net force.</p><p class="image"><img alt="Images" class="q-img" src="images/e0068-14.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><h4 class="h4">Step-by-Step Solution to #10:</h4><p class="noindent">(a) The electric force on a charge is given by $F$ = <em>qE</em>. The charge $q$ is the amount of charge on an electron, 1.6 × 10<sup>–19</sup> C. $E$ is the electric field, 3 N/C.</p><p class="image"><img alt="Images" class="q-img" src="images/e0069-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">Because the electron has a negative charge, the force is opposite the electric field, or right.</p><p class="noindentt">(b) Even though we’re dealing with an electric force, we can still use Newton’s second law. Since the electric force is the only force acting, just set this force equal to <em>ma</em> and solve. The direction of the acceleration must be in the same direction as the net force.</p><p class="image"><img alt="Images" class="q-img" src="images/e0069-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-fields-drills_q18', 'ap-topic-physc-fields-drills', 18, false, 'A', 'ap-topic-physc-fields', 'medium', 'Using Gauss''s Law, what is the electric field at distance $r$ from an infinitely long straight wire with uniform linear charge density $\lambda$?', '["$E = \\dfrac{\\lambda}{2\\pi\\epsilon_0 r}$","$E = \\dfrac{\\lambda}{4\\pi\\epsilon_0 r^2}$","$E = \\dfrac{\\lambda}{\\epsilon_0 r}$","$E = \\dfrac{\\lambda r}{2\\epsilon_0}$"]'::jsonb, 'Using a cylindrical Gaussian surface of length $L$ and radius $r$: $\Phi_E = E(2\pi r L) = \frac{q_{enc}}{\epsilon_0} = \frac{\lambda L}{\epsilon_0} \implies E = \frac{\lambda}{2\pi\epsilon_0 r}$.'),
  ('ap-topic-physc-fields-drills_q19', 'ap-topic-physc-fields-drills', 19, false, 'B', 'ap-topic-physc-fields', 'easy', 'What is the electric field inside a solid conducting sphere of radius $R$ carrying net charge $Q$ in electrostatic equilibrium?', '["$\\dfrac{kQ}{r^2}$","Zero everywhere inside ($r < R$)","$\\dfrac{kQr}{R^3}$","$\\dfrac{kQ}{R^2}$"]'::jsonb, 'In electrostatic equilibrium, charges reside entirely on the outer surface of a conductor; the electric field inside is identically zero.')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-physc-fields-drills_q20', 'ap-topic-physc-fields-drills', 20, false, 'C', 'ap-topic-physc-fields', 'medium', 'How is electric potential $V(\vec{r})$ mathematically related to electric field $\vec{E}(\vec{r})$?', '["$\\vec{E} = \\nabla V$","$V = -\\nabla \\cdot \\vec{E}$","$\\vec{E} = -\\nabla V$ (the electric field is the negative gradient of potential)","$\\vec{E} = \\nabla \\times V$"]'::jsonb, 'Because the electrostatic force is conservative, $\Delta V = -\int \vec{E} \cdot d\vec{r}$, meaning $\vec{E} = -\nabla V$.'),
  ('ap-topic-physc-circuits-drills_q1', 'ap-topic-physc-circuits-drills', 1, true, 'FRQ_MANUAL_EVALUATION', 'Circuit Analysis', 'medium', '<p><strong>Simple Circuits Drill #1:</strong> Analyze the DC circuit diagram to determine the current, voltage drops, and power dissipation:</p><p class="ques"><strong>1.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0075-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>1.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0076-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-circuits-drills_q2', 'ap-topic-physc-circuits-drills', 2, true, 'FRQ_MANUAL_EVALUATION', 'Circuit Analysis', 'medium', '<p><strong>Simple Circuits Drill #2:</strong> Analyze the DC circuit diagram to determine the current, voltage drops, and power dissipation:</p><p class="ques"><strong>2.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0075-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>2.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0076-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="quesna">(Remember, a kΩ is 1000 Ω, and a mA is 10<sup>–3</sup> A.)</p>'),
  ('ap-topic-physc-circuits-drills_q3', 'ap-topic-physc-circuits-drills', 3, true, 'FRQ_MANUAL_EVALUATION', 'Circuit Analysis', 'medium', '<p><strong>Simple Circuits Drill #3:</strong> Analyze the DC circuit diagram to determine the current, voltage drops, and power dissipation:</p><p class="ques"><strong>3.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0075-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>3.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0076-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-circuits-drills_q4', 'ap-topic-physc-circuits-drills', 4, true, 'FRQ_MANUAL_EVALUATION', 'Circuit Analysis', 'medium', '<p><strong>Simple Circuits Drill #4:</strong> Analyze the DC circuit diagram to determine the current, voltage drops, and power dissipation:</p><p class="ques"><strong>4.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0075-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>4.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0076-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-circuits-drills_q5', 'ap-topic-physc-circuits-drills', 5, true, 'FRQ_MANUAL_EVALUATION', 'Circuit Analysis', 'medium', '<p><strong>Simple Circuits Drill #5:</strong> Analyze the DC circuit diagram to determine the current, voltage drops, and power dissipation:</p><p class="ques"><strong>5.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0075-05.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>5.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0076-05.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-circuits-drills_q6', 'ap-topic-physc-circuits-drills', 6, true, 'FRQ_MANUAL_EVALUATION', 'Circuit Analysis', 'medium', '<p><strong>Simple Circuits Drill #6:</strong> Analyze the DC circuit diagram to determine the current, voltage drops, and power dissipation:</p><p class="ques"><strong>6.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0075-06.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>6.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0076-06.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-circuits-drills_q7', 'ap-topic-physc-circuits-drills', 7, true, 'FRQ_MANUAL_EVALUATION', 'Circuit Analysis', 'medium', '<p><strong>Simple Circuits Drill #7:</strong> Analyze the DC circuit diagram to determine the current, voltage drops, and power dissipation:</p><p class="ques"><strong>7.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0075-07.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>7.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0076-07.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><h4 class="h4">Step-by-Step Solution to #2:</h4><p class="noindent">Start by simplifying the combinations of resistors. The 8 kΩ and 10 kΩ resistors are in parallel. Their equivalent resistance is given by</p><p class="image"><img alt="Images" class="q-img" src="images/e0077-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">which gives $R_{eq}$ = 4.4 kΩ.</p><p class="image"><img alt="Images" class="q-img" src="images/f0077-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">Next, simplify these series resistors to their equivalent resistance of 6.4 kΩ.</p><p class="image"><img alt="Images" class="q-img" src="images/f0077-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">The total resistance of the entire circuit is 6.4 kΩ (i.e., 6400 Ω). Because we know the total voltage of the entire circuit to be 10 V, we can use Ohm’s law to get the total current</p><p class="image"><img alt="Images" class="q-img" src="images/e0077-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">(more commonly written as 1.6 mA).</p><p class="indent">Now look at the previous diagram. The same current of 1.6 mA must go out of the battery, into the 2 kΩ resistor, and into the 4.4 kΩ resistor. The voltage across each resistor can thus be determined by $V$ = (1.6 mA)$R$ for each resistor, giving 3.2 V across the 2 kΩ resistor and 6.8 V across the 4.4 kΩ resistor.</p><p class="indent">The 2 kΩ resistor is on the chart. However, the 4.4 kΩ resistor is the equivalent of two parallel resistors. Because voltage is the same for resistors in parallel, there are 6.8 V across <em>each</em> of the two parallel resistors in the original diagram. Fill that in the chart, and use Ohm’s law to find the current through each:</p><p class="image"><img alt="Images" class="q-img" src="images/e0077-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><hr/><p class="footnote"><sup>1</sup>For numerical answers, it’s okay if you’re off by a significant figure or so.</p>'),
  ('ap-topic-physc-circuits-drills_q8', 'ap-topic-physc-circuits-drills', 8, true, 'FRQ_MANUAL_EVALUATION', 'Circuit Analysis', 'medium', '<p><strong>Simple Circuits Drill #8:</strong> A \$12\text{ V}$ battery powers a bridge circuit with three resistors $R_1 = 4\,\Omega$, $R_2 = 6\,\Omega$, and $R_3 = 12\,\Omega$ in parallel. Determine the total equivalent resistance and current drawn.</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$R_{\text{eq}} = 2.0\,\Omega$, $I_{\text{total}} = 6.0\text{ A}$.</p>'),
  ('ap-topic-physc-circuits-drills_q9', 'ap-topic-physc-circuits-drills', 9, true, 'FRQ_MANUAL_EVALUATION', 'Circuit Analysis', 'medium', '<p><strong>Simple Circuits Drill #9:</strong> A \$12\text{ V}$ battery powers a bridge circuit with three resistors $R_1 = 4\,\Omega$, $R_2 = 6\,\Omega$, and $R_3 = 12\,\Omega$ in parallel. Determine the total equivalent resistance and current drawn.</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$R_{\text{eq}} = 2.0\,\Omega$, $I_{\text{total}} = 6.0\text{ A}$.</p>'),
  ('ap-topic-physc-circuits-drills_q10', 'ap-topic-physc-circuits-drills', 10, true, 'FRQ_MANUAL_EVALUATION', 'Circuit Analysis', 'medium', '<p><strong>Simple Circuits Drill #10:</strong> A \$12\text{ V}$ battery powers a bridge circuit with three resistors $R_1 = 4\,\Omega$, $R_2 = 6\,\Omega$, and $R_3 = 12\,\Omega$ in parallel. Determine the total equivalent resistance and current drawn.</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$R_{\text{eq}} = 2.0\,\Omega$, $I_{\text{total}} = 6.0\text{ A}$.</p>'),
  ('ap-topic-physc-circuits-drills_q11', 'ap-topic-physc-circuits-drills', 11, true, 'FRQ_MANUAL_EVALUATION', 'Circuit Analysis', 'medium', '<p><strong>Simple Circuits Drill #11:</strong> A \$12\text{ V}$ battery powers a bridge circuit with three resistors $R_1 = 4\,\Omega$, $R_2 = 6\,\Omega$, and $R_3 = 12\,\Omega$ in parallel. Determine the total equivalent resistance and current drawn.</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$R_{\text{eq}} = 2.0\,\Omega$, $I_{\text{total}} = 6.0\text{ A}$.</p>'),
  ('ap-topic-physc-circuits-drills_q12', 'ap-topic-physc-circuits-drills', 12, true, 'FRQ_MANUAL_EVALUATION', 'Circuit Analysis', 'medium', '<p><strong>Simple Circuits Drill #12:</strong> A \$12\text{ V}$ battery powers a bridge circuit with three resistors $R_1 = 4\,\Omega$, $R_2 = 6\,\Omega$, and $R_3 = 12\,\Omega$ in parallel. Determine the total equivalent resistance and current drawn.</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$R_{\text{eq}} = 2.0\,\Omega$, $I_{\text{total}} = 6.0\text{ A}$.</p>'),
  ('ap-topic-physc-circuits-drills_q13', 'ap-topic-physc-circuits-drills', 13, true, 'FRQ_MANUAL_EVALUATION', 'Circuit Analysis', 'medium', '<p><strong>Simple Circuits Drill #13:</strong> A \$12\text{ V}$ battery powers a bridge circuit with three resistors $R_1 = 4\,\Omega$, $R_2 = 6\,\Omega$, and $R_3 = 12\,\Omega$ in parallel. Determine the total equivalent resistance and current drawn.</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$R_{\text{eq}} = 2.0\,\Omega$, $I_{\text{total}} = 6.0\text{ A}$.</p>'),
  ('ap-topic-physc-circuits-drills_q14', 'ap-topic-physc-circuits-drills', 14, true, 'FRQ_MANUAL_EVALUATION', 'Circuit Analysis', 'medium', '<p><strong>Simple Circuits Drill #14:</strong> A \$12\text{ V}$ battery powers a bridge circuit with three resistors $R_1 = 4\,\Omega$, $R_2 = 6\,\Omega$, and $R_3 = 12\,\Omega$ in parallel. Determine the total equivalent resistance and current drawn.</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$R_{\text{eq}} = 2.0\,\Omega$, $I_{\text{total}} = 6.0\text{ A}$.</p>'),
  ('ap-topic-physc-circuits-drills_q15', 'ap-topic-physc-circuits-drills', 15, true, 'FRQ_MANUAL_EVALUATION', 'Circuit Analysis', 'medium', '<p><strong>Simple Circuits Drill #15:</strong> A \$12\text{ V}$ battery powers a bridge circuit with three resistors $R_1 = 4\,\Omega$, $R_2 = 6\,\Omega$, and $R_3 = 12\,\Omega$ in parallel. Determine the total equivalent resistance and current drawn.</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$R_{\text{eq}} = 2.0\,\Omega$, $I_{\text{total}} = 6.0\text{ A}$.</p>'),
  ('ap-topic-physc-circuits-drills_q16', 'ap-topic-physc-circuits-drills', 16, false, 'A', 'ap-topic-physc-circuits', 'easy', 'In an $RC$ series circuit connected to battery voltage $V_0$, what is the voltage across the charging capacitor as a function of time ($t \ge 0$)?', '["$V_C(t) = V_0\\left(1 - e^{-t/(RC)}\\right)$","$V_C(t) = V_0 e^{-t/(RC)}$","$V_C(t) = V_0\\left(1 - e^{-RC t}\\right)$","$V_C(t) = \\frac{V_0}{RC}t$"]'::jsonb, 'Kirchhoff''s loop rule gives $V_0 - iR - q/C = 0 \implies R dq/dt + q/C = V_0$. The solution is $q(t) = CV_0(1 - e^{-t/(RC)})$, so $V_C(t) = V_0(1 - e^{-t/(RC)})$.'),
  ('ap-topic-physc-circuits-drills_q17', 'ap-topic-physc-circuits-drills', 17, false, 'B', 'ap-topic-physc-circuits', 'easy', 'In an $RL$ series circuit with resistance $R$ and inductance $L$, what is the characteristic inductive time constant $\tau$?', '["$\\tau = \\dfrac{R}{L}$","$\\tau = \\dfrac{L}{R}$","$\\tau = RL$","$\\tau = \\sqrt{LC}$"]'::jsonb, 'From the differential equation $L \frac{di}{dt} + R i = V$, the characteristic relaxation time constant is $\tau = L / R$.'),
  ('ap-topic-physc-circuits-drills_q18', 'ap-topic-physc-circuits-drills', 18, false, 'C', 'ap-topic-physc-circuits', 'easy', 'What is the total energy stored in the magnetic field of an inductor carrying current $I$?', '["$U_B = \\frac{1}{2}L^2 I$","$U_B = LI$","$U_B = \\frac{1}{2}LI^2$","$U_B = \\frac{1}{2}\\frac{I^2}{L}$"]'::jsonb, '$U = \int P dt = \int (L \frac{di}{dt}) i dt = L \int i di = \frac{1}{2}LI^2$.'),
  ('ap-topic-physc-circuits-drills_q19', 'ap-topic-physc-circuits-drills', 19, false, 'D', 'ap-topic-physc-circuits', 'easy', 'An $LC$ circuit consists of ideal inductor $L$ and capacitor $C$. What is the natural angular frequency $\omega_0$ of electrical oscillations?', '["$\\omega_0 = \\sqrt{LC}$","$\\omega_0 = \\dfrac{1}{LC}$","$\\omega_0 = \\dfrac{L}{C}$","$\\omega_0 = \\dfrac{1}{\\sqrt{LC}}$"]'::jsonb, 'Loop equation: $L \frac{d^2q}{dt^2} + \frac{q}{C} = 0 \implies \frac{d^2q}{dt^2} + \frac{1}{LC}q = 0 \implies \omega_0 = \frac{1}{\sqrt{LC}}$.'),
  ('ap-topic-physc-circuits-drills_q20', 'ap-topic-physc-circuits-drills', 20, false, 'A', 'ap-topic-physc-circuits', 'medium', 'Immediately after the switch is closed in an $RL$ circuit with an unenergized inductor, how does the inductor behave?', '["As an open circuit ($i(0^+) = 0$), opposing sudden changes in current","As an ideal short circuit of zero resistance","As a constant voltage source equal to $2V_0$","As a pure resistive load $R$"]'::jsonb, 'Because current through an inductor cannot change discontinuously without infinite induced EMF, $i(0^+) = i(0^-) = 0$, acting instantaneously as an open circuit.'),
  ('ap-topic-physc-em-fundamentals_q1', 'ap-topic-physc-em-fundamentals', 1, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fundamentals', 'medium', '<p><strong>E&M Core Concept #1:</strong></p><p class="numbert"><strong>1.</strong> Given the charge of a particle and the electric field experienced by that particle, give the equation to determine the electric force acting on the particle.</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="numbert"><strong>1.</strong> $F$ = <em>qE.</em></p>'),
  ('ap-topic-physc-em-fundamentals_q2', 'ap-topic-physc-em-fundamentals', 2, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fundamentals', 'medium', '<p><strong>E&M Core Concept #2:</strong></p><p class="number"><strong>2.</strong> Given the charge of a particle and the magnetic field experienced by that particle, give the equation to determine the magnetic force acting on the particle.</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>2.</strong> $F$ = <em>qvB</em> sin $\theta$.</p>'),
  ('ap-topic-physc-em-fundamentals_q3', 'ap-topic-physc-em-fundamentals', 3, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fundamentals', 'medium', '<p><strong>E&M Core Concept #3:</strong></p><p class="number"><strong>3.</strong> What are the units of magnetic flux? What are the units of EMF?</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>3.</strong> Magnetic flux is <em>BA</em>, so the units are tesla·meter$s^{2}$ (or, alternatively, webers). EMF is a voltage, so the units are volts.</p>'),
  ('ap-topic-physc-em-fundamentals_q4', 'ap-topic-physc-em-fundamentals', 4, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fundamentals', 'medium', '<p><strong>E&M Core Concept #4:</strong></p><p class="number"><strong>4.</strong> A wire carries a current to the left, as shown below. What is the direction and magnitude of the magnetic field produced by the wire at point $P$?</p><p class="image"><img alt="Images" class="q-img" src="images/f0027-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>4.</strong> Point your right thumb in the direction of the current, i.e., to the left. Your fingers point in the direction of the magnetic field. This field wraps around the wire, pointing into the page above the wire and out of the page below the wire. Since point $P$ is below the wire, the field points out of the page.</p>'),
  ('ap-topic-physc-em-fundamentals_q5', 'ap-topic-physc-em-fundamentals', 5, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fundamentals', 'medium', '<p><strong>E&M Core Concept #5:</strong></p><p class="number"><strong>5.</strong> When is the equation <em>kQ/r</em><sup>2</sup> valid? What is this an equation for?</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>5.</strong> This equation is only valid when a point charge produces an electric field. (Careful—if you just said “point charge,” you’re not entirely correct. If a point charge experiences an electric field produced by something else, this equation is irrelevant.) It is an equation for the electric field produced by the point charge.</p>'),
  ('ap-topic-physc-em-fundamentals_q6', 'ap-topic-physc-em-fundamentals', 6, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fundamentals', 'medium', '<p><strong>E&M Core Concept #6:</strong></p><p class="number"><strong>6.</strong> The electric field at point $P$ is 100 N/C; the field at point <em>Q,</em> 1 meter away from point <em>P,</em> is 200 N/C. A point charge of +1 C is placed at point <em>P.</em> What is the magnitude of the electric force experienced by this charge?</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>6.</strong> Do <em>not</em> use $E$ = <em>kQ</em>/$r^{2}$ here because the electric field is known. So, the source of the electric field is irrelevant—just use $F$ = <em>qE</em> to find that the force on the charge is (1 C)(100 N/C) = 100 N. (The charge is placed at point <em>P,</em> so anything happening at point $Q$ is irrelevant.)</p>'),
  ('ap-topic-physc-em-fundamentals_q7', 'ap-topic-physc-em-fundamentals', 7, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fundamentals', 'medium', '<p><strong>E&M Core Concept #7:</strong></p><p class="number"><strong>7.</strong> Can a current be induced in a wire if the flux through the wire is zero? Explain.</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>7.</strong> Yes! Induced EMF depends on the <em>change</em> in flux. So, imagine that the flux is changing rapidly from one direction to the other. For a brief moment, flux will be zero; but flux is still changing at that moment. (And, of course, the induced current will be the EMF divided by the resistance of the wire.)</p>'),
  ('ap-topic-physc-em-fundamentals_q8', 'ap-topic-physc-em-fundamentals', 8, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fundamentals', 'medium', '<p><strong>E&M Core Concept #8:</strong></p><p class="number"><strong>8.</strong> True or false: In a uniform electric field pointing to the right, a negatively charged particle will move to the left. If true, justify with an equation; if false, explain the flaw in reasoning.</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>8.</strong> False. The negative particle will be <em>forced</em> to the left. But the particle could have entered the field while moving to the right . . . in that case, the particle would continue moving to the right, but would slow down.</p>'),
  ('ap-topic-physc-em-fundamentals_q9', 'ap-topic-physc-em-fundamentals', 9, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fundamentals', 'medium', '<p><strong>E&M Core Concept #9:</strong></p><p class="number"><strong>9.</strong> Which is a vector and which is a scalar: electric field and electric potential?</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>9.</strong> Electric field is a vector, so fields produced in different directions can cancel. Electric potential is a scalar, so direction is irrelevant.</p>'),
  ('ap-topic-physc-em-fundamentals_q10', 'ap-topic-physc-em-fundamentals', 10, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fundamentals', 'medium', '<p><strong>E&M Core Concept #10:</strong></p><p class="number"><strong>10.</strong> Fill in the blank with either “parallel” or “series”:</p><p class="alphamt">a. Voltage across resistors in ______ must be the same for each.</p><p class="alpham">b. Current through resistors in ______ must be the same for each.</p><p class="alpham">c. Voltage across capacitors in ______ must be the same for each.</p><p class="alpham">d. Charge stored on capacitors in ______ must be the same for each.</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>10.</strong> Voltage across resistors in parallel must be the same for each.</p><p class="numbern">Current through resistors in series must be the same for each.</p><p class="numbern">Voltage across capacitors in parallel must be the same for each.</p><p class="numbern">Charge stored on capacitors in series must be the same for each.</p>'),
  ('ap-topic-physc-em-fundamentals_q11', 'ap-topic-physc-em-fundamentals', 11, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fundamentals', 'medium', '<p><strong>E&M Core Concept #11:</strong></p><p class="number"><strong>11.</strong> A uniform electric field acts to the right. In which direction will each of these particles accelerate?</p><p class="alphamt">a. proton</p><p class="alpham">b. positron (same mass as electron, but opposite charge)</p><p class="alpham">c. neutron</p><p class="alpham">d. anti-proton (same mass as proton, but opposite charge)</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>11.</strong> The positively charged proton will accelerate with the field, to the right.</p><p class="numbern">The positively charged positron will accelerate with the field, to the right.</p><p class="numbern">The uncharged neutron will not accelerate.</p><p class="numbern">The negatively charged anti-proton will accelerate against the field, to the left.</p>'),
  ('ap-topic-physc-em-fundamentals_q12', 'ap-topic-physc-em-fundamentals', 12, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fundamentals', 'medium', '<p><strong>E&M Core Concept #12:</strong></p><p class="number"><strong>12.</strong> A uniform magnetic field acts to the right. In which direction will each of these particles accelerate, assuming they enter the field moving toward the top of the page?</p><p class="alphamt">a. proton</p><p class="alpham">b. positron (same mass as electron, but opposite charge)</p><p class="alpham">c. neutron</p><p class="alpham">d. anti-proton (same mass as proton, but opposite charge)</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>12.</strong> Use the right-hand rule for each:</p><p class="numbern">The positively charged proton will accelerate into the page.</p><p class="numbern">The positively charged positron will accelerate into the page.</p><p class="numbern">The uncharged neutron will not accelerate.</p><p class="numbern">The negatively charged anti-proton will accelerate out of the page.</p>'),
  ('ap-topic-physc-em-fundamentals_q13', 'ap-topic-physc-em-fundamentals', 13, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fundamentals', 'medium', '<p><strong>E&M Core Concept #13:</strong></p><p class="number"><strong>13.</strong> How do you find the potential energy of an electric charge?</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>13.</strong> If you know the electric potential experienced by the charge, PE = <em>qV.</em></p><h3 class="h3" id="lev18">What Do I Know, and What Don’t I Know?</h3><p class="noindent">I’ll bet you didn’t get every question on both of these fundamentals quizzes correct. That’s okay. The whole point of these quizzes is for you to determine where to focus your study.</p><p class="indent">It’s a common mistake to “study” by doing 20 problems on a topic on which you are already comfortable. But that’s not studying . . . that’s a waste of time. You don’t need to drill yourself on topics you already understand! It’s also probably a mistake to attack what for you is the toughest concept in physics right before the exam. Virtually every student has that one chapter they just don’t get, however hard they try. That’s okay.</p><p class="indent">The fundamentals quizzes that you just took can tell you exactly what you should and should not study. Did you give correct answers with full confidence in the correctness of your response? In that case, you’re done with that topic. No more work is necessary. The place to focus your efforts is on the topics where either you gave wrong answers that you thought were right, or right answers that you weren’t really sure about.</p><p class="indent">Now, take the diagnostic test. Once you’ve used the fundamentals quizzes and diagnostic test to identify the specific content areas you want to work on, proceed to the review in Chapters 9–20. Read a chapter, work through the examples in the chapter, and attempt some of the problems at the end of the chapter. Then come back to these fundamentals quizzes. When you respond to every question confidently, you are ready.</p>'),
  ('ap-topic-physc-em-fundamentals_q14', 'ap-topic-physc-em-fundamentals', 14, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fundamentals', 'medium', '<p><strong>E&M Core Concept #14:</strong> State the physical meaning of Gauss''s Law for Magnetism $\oint \vec{B}\cdot d\vec{A} = 0$ and its implication for magnetic monopoles.</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p>Gauss''s law for magnetism confirms magnetic field lines never terminate and magnetic monopoles do not exist.</p>'),
  ('ap-topic-physc-em-fundamentals_q15', 'ap-topic-physc-em-fundamentals', 15, true, 'FRQ_MANUAL_EVALUATION', 'E&M Fundamentals', 'medium', '<p><strong>E&M Core Concept #15:</strong> State the relation between the speed of electromagnetic waves in vacuum $c$ and the fundamental constants $\epsilon_0$ and $\mu_0$.</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p>$c = \frac{1}{\sqrt{\epsilon_0 \mu_0}}$.</p>'),
  ('ap-topic-physc-em-fundamentals_q16', 'ap-topic-physc-em-fundamentals', 16, false, 'A', 'ap-topic-physc-em', 'easy', 'A proton moves with velocity $\vec{v} = v\hat{i}$ through a region with magnetic field $\vec{B} = B\hat{k}$. What is the direction of the magnetic Lorentz force?', '["$-y$ direction ($-\\hat{j}$)","$+y$ direction ($+\\hat{j}$)","$+z$ direction ($+\\hat{k}$)","Zero force"]'::jsonb, '$\vec{F} = q(\vec{v} \times \vec{B}) = q(v\hat{i} \times B\hat{k}) = q v B (\hat{i} \times \hat{k}) = -q v B\hat{j}$.'),
  ('ap-topic-physc-em-fundamentals_q17', 'ap-topic-physc-em-fundamentals', 17, false, 'B', 'ap-topic-physc-em', 'easy', 'According to Faraday''s Law, the induced electromotive force (EMF) in a closed conducting loop is proportional to:', '["The total magnetic field strength alone","The time rate of change of magnetic flux through the loop: $\\mathcal{E} = -\\dfrac{d\\Phi_B}{dt}$","The electrostatic potential difference between the loop terminals","The mechanical torque applied to the loop"]'::jsonb, 'Faraday''s law of induction states $\mathcal{E} = -\frac{d\Phi_B}{dt}$, with Lenz''s law indicated by the negative sign.'),
  ('ap-topic-physc-em-fundamentals_q18', 'ap-topic-physc-em-fundamentals', 18, false, 'C', 'ap-topic-physc-em', 'easy', 'Using Ampere''s Law, what is the magnetic field inside an ideal long solenoid with $n$ turns per unit length carrying current $I$?', '["$B = \\dfrac{\\mu_0 I}{2\\pi r}$","$B = \\dfrac{\\mu_0 n I}{2}$","$B = \\mu_0 n I$","$B = \\mu_0 n^2 I$"]'::jsonb, 'Applying Ampere''s law around a rectangular loop enclosing $N = n L$ turns yields $B L = \mu_0 (n L I) \implies B = \mu_0 n I$.'),
  ('ap-topic-physc-em-fundamentals_q19', 'ap-topic-physc-em-fundamentals', 19, false, 'D', 'ap-topic-physc-em', 'easy', 'Why can a static magnetic field do no work on a moving charged particle?', '["Because magnetic field lines always form closed loops","Because magnetic charges do not exist","Because kinetic energy cannot be converted into potential energy","Because the magnetic force $\\vec{F}_B = q(\\vec{v} \\times \\vec{B})$ is always perpendicular to instantaneous velocity $\\vec{v}$"]'::jsonb, 'Power $P = \vec{F} \cdot \vec{v} = q(\vec{v} \times \vec{B}) \cdot \vec{v} \equiv 0$. The magnetic force does zero work and changes only the direction of motion, never speed.'),
  ('ap-topic-physc-em-fundamentals_q20', 'ap-topic-physc-em-fundamentals', 20, false, 'A', 'ap-topic-physc-em', 'easy', 'A metal bar of length $L$ moves at constant velocity $v$ perpendicular to a uniform magnetic field $B$. What motional EMF is induced across its ends?', '["$\\mathcal{E} = B L v$","$\\mathcal{E} = \\frac{1}{2}B L v$","$\\mathcal{E} = B L^2 v$","$\\mathcal{E} = 0$"]'::jsonb, 'Charge carriers experience Lorentz force $F = q v B$. In equilibrium, electric field $E = v B$. Potential difference across length $L$ is $\mathcal{E} = E L = B L v$.'),
  ('ap-topic-physc-gauss_q1', 'ap-topic-physc-gauss', 1, false, 'C', 'Ch11: Gauss''s Law', 'medium', 'Which of the following statements is correct?', '["If a gaussian surface contains zero net charge, the electric field at every location on the surface must be zero.","If net flux through a gaussian surface is zero, the surface must enclose no charge.","If the electric field at every location on a gaussian surface is zero, the surface must contain no net charge.","The electric field on a gaussian surface is generally not influenced by charge that is not enclosed by the surface.","Charges outside the gaussian surface affect the electric field on the surface and therefore affect the net flux through the surface."]'::jsonb, '(C) Choice (A) is correct if the charge distribution has appropriate symmetry but is not true in general. If the enclosed charge is zero, the net flux must be zero. However, this does not require the field at every point along the surface to be zero: It is possible for the flux to be positive in some locations along the gaussian surface and negative along others such that the net flux is zero (even if the field is not zero throughout the surface). Choice (B) is almost true. If the electric flux is zero, the net charge must be zero. However, it is possible that the surface contains charge as long as it contains equal amounts of positive and negative charge. Choice (C) is true. [The addition of the word net fixes the flaw in choice (B).] Choice (D) is completely false. Charge outside the gaussian surface does not affect the net electric flux through the surface, but it does affect the field along the gaussian surface. Choice (E) is also false. Although charges outside the gaussian surface affect the electric field on the surface, they do not affect the net flux through the surface.'),
  ('ap-topic-physc-gauss_q2', 'ap-topic-physc-gauss', 2, false, 'C', 'Ch11: Gauss''s Law', 'medium', 'A point charge +q is located at the center of an imaginary spherical Gaussian surface of radius R. If the radius of the Gaussian surface is doubled to 2R, what happens to the total electric flux Phi_E passing through the surface?', '["Phi_E is quadrupled","Phi_E is doubled","Phi_E remains unchanged","Phi_E is halved","Phi_E is reduced to one-fourth"]'::jsonb, 'According to Gauss''s Law, the total electric flux through any closed surface is Phi_E = q_enc / epsilon_0. The enclosed charge q_enc is +q regardless of the radius of the Gaussian surface. Therefore, doubling the radius does not change the total electric flux.'),
  ('ap-topic-physc-gauss_q3', 'ap-topic-physc-gauss', 3, false, 'B', 'Ch11: Gauss''s Law', 'medium', 'A spherical metal shell with zero net charge encloses a point charge. The magnitude of the surface charge density', '["is greater on the outside surface of the shell than on the inside surface of the shell","is greater on the inside surface of the shell than on the outside surface of the shell","is zero because the net charge is zero","is zero because the surface charge density of a metal must be zero","Not enough information is given."]'::jsonb, '(B) Because the electric field within a metal must be zero, any surface passing through a metal must enclose zero net charge. Imagine a surface passing through the metal shell. To enclose zero net charge, a charge opposite in magnitude to the enclosed charge must lie on the inner surface of the metal shell. Conservation of charge then requires that an equal and opposite charge lie on the outside surface of the shell. Therefore, both surfaces have nonzero charge density, and both surfaces have the same magnitude of charge. However, because the area of the outside surface is larger than the area of the inside surface, the magnitude of its charge density must be lower.'),
  ('ap-topic-physc-gauss_q4', 'ap-topic-physc-gauss', 4, false, 'B', 'Ch11: Gauss''s Law', 'medium', 'Two thin insulating sheets of charge flank a thick conducting sheet as shown in Figure 11.8. The charge densities on the insulating sheets are given by \sigma1 = 10.0 \times  10−6 C/m2, \sigma2 = − 10.0 \times  10−6 C/m2, while the conductor has zero net charge.', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(B) Because the electric field within a metal must be zero, any surface passing through a metal must enclose zero net charge. Imagine a surface passing through the metal shell. To enclose zero net charge, a charge opposite in magnitude to the enclosed charge must lie on the inner surface of the metal shell. Conservation of charge then requires that an equal and opposite charge lie on the outside surface of the shell. Therefore, both surfaces have nonzero charge density, and both surfaces have the same magnitude of charge. However, because the area of the outside surface is larger than the area of the inside surface, the magnitude of its charge density must be lower.'),
  ('ap-topic-physc-gauss_q5', 'ap-topic-physc-gauss', 5, false, 'B', 'Ch11: Gauss''s Law', 'medium', 'Two metal spherical shells, with radii r1 > r2, each contain a charge +Q distributed on their metal surfaces. The two shells are located far apart from each other compared to their radii. When a wire connects the two shells, what happens?', '["Negative charge flows from sphere 1 to sphere 2.","Negative charge flows from sphere 2 to sphere 1.","No charge flows between the spheres.","An electric field builds with time within the wire.","No magnetic fields are produced."]'::jsonb, '(B) The potentials of spheres 1 and 2 are approximately Q/4\pi\epsilon0r1 and Q/4\pi\epsilon0r2, respectively, because the spheres are far apart and thus essentially isolated. Because r1 > r2, V1 < V2 and charge flows from the higher to the lower potential. The fact that a sphere of charge +Q with radius r has the same potential as a point a distance r from a point charge +Q is discussed in Example 11.7, part (b).'),
  ('ap-topic-physc-gauss_q6', 'ap-topic-physc-gauss', 6, false, 'A', 'Ch11: Gauss''s Law', 'medium', 'Referring to the situation described in question 3 after the two spheres reach equilibrium, what is the ratio of their charges (assuming negligible charge accumulates on the wire)?', '["Q1/Q2 = r1/r2","Q1/Q2 = r2/r1","Q1/Q2 = (r1/r2)2","Q1/Q2 = (r2/r1)2","none of the above"]'::jsonb, '(A) In equilibrium, a conductor is an equipotential. The two spheres connected by a wire form a single conductor. Therefore, This equation can be rearranged into choice (A).'),
  ('ap-topic-physc-gauss_q7', 'ap-topic-physc-gauss', 7, false, 'A', 'Ch11: Gauss''s Law', 'medium', 'A point charge −Q is inserted inside a cubic uncharged metal box. Which of the following statements is true?', '["A net charge of +Q is distributed on the inner surface of the box.","The electric field outside the box is unaffected by the box and is determined solely by the point charge.","The potential within the walls of the metal box is zero.","There is a net charge of +Q on the box.","The electric field inside the region bounded by the metal box is zero."]'::jsonb, '(A) Choice (A): Since the electric field within the metal is zero, a gaussian surface lying within the metal of the box experiences zero flux and thus must enclose zero net charge. Therefore, the charge on the inner surface of the metal must be the opposite of the point charge, +Q. Choice (B): Based on the above discussion, the net electric field outside the box arises from the charge −Q induced on the outer surface of the box. The distribution of this charge is not spherically symmetric (it has the symmetry of the box), and thus the field outside the box is not that of a point charge except at very large distances. Choice (C): The electric field is zero within the metal so that the potential is constant but not equal to zero. The electric field outside the box arises from the induced negative charge on the surface of the box, so the potential is negative. Choice (D): Conservation of charge requires the net charge on the box remain zero. Choice (E): Within the box, electric field lines begin on the inner surface of the box at the positive charge +Q and end on the point charge −Q. The electric field is not zero.'),
  ('ap-topic-physc-gauss_q8', 'ap-topic-physc-gauss', 8, false, 'B', 'Ch11: Gauss''s Law', 'medium', 'Two concentric thin spherical conducting shells have radii R1 and R2 (with R1 < R2). The inner shell carries net charge -Q and the outer shell carries net charge +2Q. What is the electric field magnitude E(r) in the region outside both shells (r > R2)?', '["Zero","k Q / r^2","2 k Q / r^2","3 k Q / r^2","k Q / (R2^2 - R1^2)"]'::jsonb, 'For r > R2, a spherical Gaussian surface of radius r encloses both shells. The net enclosed charge is q_enc = (-Q) + (+2Q) = +Q. By Gauss''s Law, oint E * dA = E * (4 pi r^2) = q_enc / epsilon_0 = Q / epsilon_0 ==> E(r) = k Q / r^2 directed radially outward.'),
  ('ap-topic-physc-gauss_q9', 'ap-topic-physc-gauss', 9, false, 'E', 'Ch11: Gauss''s Law', 'medium', 'Three nonconducting spheres all have the same net charge +Q and radius R. The charge is uniformly distributed throughout the volume of sphere A, uniformly distributed on the surface of sphere B, and distributed with a density proportional to the radial variable \rho = cr throughout the volume of sphere C (c = Q/\piR4). Which is a valid comparison of the electric fields at a distance r from the center of these spheres, assuming that r > R?', '["EA < EB < EC","EA < EC < EB","EC < EA < EB","EC < EB < EA","EB = EC = EA"]'::jsonb, '(E) Because the enclosed charge is the same in every case (for a gaussian sphere passing through the point of interest), the electric fields are the same.')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-physc-gauss_q10', 'ap-topic-physc-gauss', 10, false, 'E', 'Ch11: Gauss''s Law', 'medium', 'Consider the three spheres introduced in question 7. Which of the following is a valid comparison of the potentials at the surface of each of the spheres?', '["VA < VB < VC","VA < VC < VB","VC < VA < VB","VC < VB < VA","VB = VC = VA"]'::jsonb, '(E) Because the electric field is the same outside each of the spheres, the potential at the surface of each of the spheres, which is an integral of this electric field, is also the same.'),
  ('ap-topic-physc-gauss_q11', 'ap-topic-physc-gauss', 11, false, 'A', 'Ch11: Gauss''s Law', 'medium', 'Three charged sheets lie parallel to the yz-plane as shown in Figure 11.5. Which graph shows the electric field as a function of position? Figure 11.5', '["graph (A)","graph (B)","graph (C)","graph (D)","graph (E) Free-Response Questions"]'::jsonb, '(A) Recall that the formula for the magnitude of an electric field due to a sheet of charge is E = \sigma/2\epsilon0. The magnitude of the electric field does not depend on the distance from the charged sheets (only on which side of the sheets the point is), so the field must remain constant within any region not divided by the plates, eliminating all the choices except (A). To find the electric field, compute the vector sum of the fields caused by each of the three sheets. Free-Response 1. (a) Applying Gauss’s law, As for the direction of the field, if the flux is positive, the electric field must be parallel to the directed area vector (pointing away from the surface), whereas if the flux is negative, the electric field will point toward the center of the surface. (b) The enclosed charge is related to the flux: (c) The flux through the two surfaces is equal (because they both contain the same enclosed charge). (d) Making a straightforward application of Gauss’s law: Again, if the flux is positive, the electric field will point away from the surface, whereas if the flux is negative, the electric field will point toward the center of the surface. (e) At r = b, the electric field is zero because the point is located inside a metal. Therefore, the net flux must be zero and the enclosed charge must also be zero. This implies that a charge −\epsilon0\Phi must exist on the inside surface of the metal shell. Charge conservation then requires a charge of Q + \epsilon0\Phi to reside on the outside surface of the metal shell. The flux through surface a and the field at r = a is unchanged because the surrounding charge is spherically symmetric and the enclosed charge is unchanged. 2. (a) The electric field inside a metal is zero in static equilibrium. (b) Each insulating sheet produces a field of magnitude |\sigma|/2\epsilon0, as shown in Example 11.1. In the region between the left sheet and the conductor, the field produced by the left sheet points to the right (away from the positive charge) as does the field produced by the right sheet (toward the negative charge). These two fields superpose to yield a net field of directed to the right. (c) As in part (b), the field between the conductor and the right insulating sheet is a superposition of the fields produced by the two sheets. The directions of these fields is identical to part (b), and thus the answer to this part is Eright = Eleft. (d) To find the charge densities on the surfaces of the conductor, we need to use Gauss’s law. We draw a box as in Example 11.1 that is bisected by the surface of the conductor; see Figure 11.9. We know that the electric field is horizontal, and thus there is no flux through the top and bottom of the box. We also know that the flux through the right side is zero because the field inside the conductor is zero. Thus, the only flux is through the left face and is given by \Phi = Eleft A cos 180° = − Eleft A, where A is the area of the left face. Gauss’s law tells us that It makes sense that the charge density is negative. The field to the left of the conductor is pointing to the right and must terminate on negative charges so that there’s no field inside the conductor. Figure 11.9 (e) We solve this part in a similar fashion to part (d). If we draw a box that straddles the right face of the conductor, the only flux through the box will be through the right face and will be given by \Phi = Eright A = Eright A. Because Eright = Eleft, in magnitude the charge density on the right surface of the conductor will be \sigmaright = − \sigmaleft = 1.0 \times  10−5 C/m2. The charge density is positive because the field on the right side of the conductor points to the right, away from the conductor. Note that these equal and opposite charge densities will produce zero net field to the left and to the right of the conductor when they are superposed. Thus, they make no contribution to the superposition of fields in parts (b) and (c). 1After reading this chapter, you should be able to easily derive Coulomb’s law from Gauss’s law. Alternatively, deriving Gauss’s law from Coulomb’s law requires math beyond BC calculus. 2However, Gauss’s law has a greater range of validity, as it correctly describes the electric fields of moving charges, whereas Coulomb’s law is valid only for static charge distributions.'),
  ('ap-topic-physc-gauss_q12', 'ap-topic-physc-gauss', 12, false, 'C', 'Diagnostic Test – E&M', 'medium', 'Two metal spheres with radii r1 and r2 carrying positive charges Q1 and Q2 are separated by a very large distance. A thin wire connects the two spheres. Under what condition will positive charge flow from sphere 1 to sphere 2?', '["Q1 > Q2","r1 > r2","Q1 / r1 > Q2 / r2","Q1 r1 > Q2 r2","Q1 / r1^2 > Q2 / r2^2"]'::jsonb, 'Positive charge flows from higher to lower electric potential. The surface potential of an isolated sphere is V = k Q / r. Charge flows from sphere 1 to sphere 2 if and only if V1 > V2 ==> Q1 / r1 > Q2 / r2.'),
  ('ap-topic-physc-gauss_q13', 'ap-topic-physc-gauss', 13, false, 'C', 'Diagnostic Test – E&M', 'medium', 'A charged particle is launched into a region of uniform magnetic field. Given that the particle’s initial velocity has components parallel and perpendicular to the magnetic field, describe the particle’s path qualitatively.', '["a straight line","a circle","a helical (corkscrew) path","a parabolic path","none of the above"]'::jsonb, '(C) See the discussion of the motion of particles within magnetic fields in Chapter 14.'),
  ('ap-topic-physc-gauss_q14', 'ap-topic-physc-gauss', 14, false, 'B', 'Diagnostic Test – E&M', 'medium', 'A point charge +Q is located at a fixed distance from a sphere. Compare the magnitude of the attractive force on the sphere if the sphere is (1) metal with net charge −Q, (2) metal with no net charge, (3) an insulator with net charge −Q, or (4) an insulator with no net charge.', '["charged metal = charged insulator > uncharged metal = uncharged insulator","charged metal > charged insulator > uncharged metal > uncharged insulator","charged insulator > charged metal > uncharged insulator > uncharged metal","charged insulator > charged metal > uncharged metal = uncharged insulator","charged insulator = charged metal > uncharged metal > uncharged insulator"]'::jsonb, '(B) This is a question about electrostatic induction. When a positive point charge is placed near a metal sphere (charged or uncharged), it attracts mobile electrons in the metal, causing the metal to become polarized such that more negative charge is on the side closer to the positive point charge and more positive charge is on the side farther away from the positive point charge. Because this charge redistribution results in moving negative charge closer to the positive point charge and moving positive charge farther away from the positive point charge, it increases the attractive force between the metal sphere and the positive point charge. Therefore, compared to an insulating sphere with the same net charge, a metal sphere always experiences a greater attractive force (such that charged metal > charged insulator and uncharged metal > uncharged insulator). Because this inductive effect is small compared to the effect of actually putting net charge −Q on the sphere, charged insulator > uncharged metal.'),
  ('ap-topic-physc-gauss_q15', 'ap-topic-physc-gauss', 15, false, 'C', 'Diagnostic Test – E&M', 'medium', 'A bar moves to the right through a magnetic field as shown (the magnetic field points into the page). What is the potential difference between points A and B after equilibrium is established in the bar?', '["The difference is v2Bd, with A at higher potential.","The difference is v2Bd, with B at higher potential.","The difference is vBd, with A at higher potential.","The difference is vBd, with B at higher potential.","Because there is no loop, there is no flux, so there is no potential difference."]'::jsonb, '(C) The charges within the bar are moving in a magnetic field, so they feel a magnetic force. Using the conventional-current description, positive charges feel an upward force, causing positive charge to accumulate at the top end of the bar (leaving negative charge on the bottom end of the bar). This charge continues to accumulate until the electric force created by the charge imbalance cancels the magnetic force, mathematically qE = qvB. The magnitude of the potential difference between points A and B is then |V | = |−\int E \cdot  dr| = |vBd|. The electric field points down (producing a force that opposes the magnetic force), and recalling that electric fields point from high to low potential, we see that point A is at the higher potential. Further information about motional EMF can be found in Example 15.6.'),
  ('ap-topic-physc-gauss_q16', 'ap-topic-physc-gauss', 16, false, 'B', 'Diagnostic Test – E&M', 'medium', 'Suppose that the electric potential in a region of space is a constant. What can you conclude about the magnitude of the electric field in this region?', '["It is a nonzero constant.","It is zero.","It is proportional to the distance from the origin.","It is given by","Not enough information is given. Questions 6–8 refer to a circular region of radius a with a uniform magnetic field pointing into the page that is increasing at a constant rate as shown. A circular loop of wire of radius r is centered on the middle of the region."]'::jsonb, '(B) The electric field is the negative derivative (with respect to the spatial coordinate) of the potential. Thus, with a constant potential the electric field must be zero.'),
  ('ap-topic-physc-gauss_q17', 'ap-topic-physc-gauss', 17, false, 'C', 'Diagnostic Test – E&M', 'medium', 'Which of the graphs plots the induced EMF in the circular loop of wire shown as a function of its radius r?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(C) The induced EMF depends on the change in the enclosed flux. Because the magnetic field is uniform, and changing at a constant rate, Therefore, the induced EMF depends only on the area of the loop through which magnetic field lines pass. For r < a, the area within the loop exposed to the magnetic field is simply the entire area of the loop, which is a quadratic function, A(r) = \pir2. For r > a, increasing r does not increase the area exposed to the magnetic field (because the magnetic field through the additional area is zero). Therefore, for r > a the induced EMF is constant. The only graph that is quadratic for small r and then constant is choice (C). Calculating the induced EMF due to a magnetic field via Faraday’s law is discussed in Chapter 15.'),
  ('ap-topic-physc-gauss_q18', 'ap-topic-physc-gauss', 18, false, 'A', 'Diagnostic Test – E&M', 'medium', 'Given that the resistance of the loop is proportional to the loop’s circumference, which of the graphs seen in question 6 shows the induced current as a function of the radius of the loop?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(A) The current is given by I = V/R. The resistance is proportional to the circumference of the loop, 2\pir. Therefore, for r < a, V is proportional to r2 (as discussed in question 6), and 1/R is proportional to 1/r, so the product I = V/R is proportional to r (and thus its graph is a line passing through the origin). For r > a, V is constant and 1/R is proportional to 1/r, so the product I = V/R is inversely proportional to r. The only graph that satisfies these conditions is choice (A).'),
  ('ap-topic-physc-gauss_q19', 'ap-topic-physc-gauss', 19, false, 'A', 'Diagnostic Test – E&M', 'medium', 'A uniform electric field E is directed parallel to the axis of a right circular cylinder of radius R and length L. What is the net electric flux through the entire closed surface of the cylinder?', '["Zero","pi R^2 E","2 pi R^2 E","2 pi R L E","(pi R^2 + 2 pi R L) E"]'::jsonb, 'The field lines enter through one flat circular face (flux = -E * pi R^2), pass parallel to the curved sides (flux = 0 because E is parallel to the surface), and exit through the opposite flat circular face (flux = +E * pi R^2). The net electric flux is -pi R^2 E + 0 + pi R^2 E = 0. Alternatively, by Gauss''s Law, since no charge is enclosed, Phi_net = 0.'),
  ('ap-topic-physc-gauss_q20', 'ap-topic-physc-gauss', 20, false, 'E', 'Diagnostic Test – E&M', 'medium', 'The magnitude of the electric field inside a uniformly charged spherical shell', '["depends on the charge of the shell","depends on the radius of the shell","depends on the distance from the center of the sphere, r","depends on the permittivity of free space, \\epsilon0","is equal to the integral , where is a unit vector pointing from the differential charge dQ to the point in space (within the sphere) where the electric field is being measured"]'::jsonb, '(E) According to Gauss’s law (Chapter 11), the electric field inside a hollow sphere is zero because there is no enclosed charge. Therefore, the electric field is independent of the charge of the shell, the radius of the shell, the radial coordinate, and the permittivity of free space; it is zero inside the sphere independent of any of these factors. Note that the electric field is always given by the equation in choice (E).'),
  ('ap-topic-physc-capacitors_q1', 'ap-topic-physc-capacitors', 1, false, 'B', 'Ch12: Capacitors', 'medium', 'The dielectric slab filling the space between the plates of a charged, isolated capacitor is removed. The energy stored in the capacitor', '["remains constant","increases by a factor of κD","decreases by a factor of κD","increases by a factor of κD 2","decreases by a factor of κD 2"]'::jsonb, '(B) Recall that charge is induced on the surfaces of the dielectric so that the induced charge attracts the adjacent, oppositely charged plates of the capacitor. Thus, removing the dielectric requires work, increasing the potential energy of the capacitor, immediately eliminating choices (A), (C), and (E). The energy stored on a capacitor can be expressed in terms of any two of the three variables Q, C, and V. Now, when we add or remove a dielectric, Q remains the same (the capacitor is isolated), and we know that C decreases by a factor of kD. Therefore, the most convenient equation to use here expresses the potential energy in terms of Q and C: U = Q2/2C. Because Q remains constant and C decreases by a factor of kD, the energy increases by a factor of kD.'),
  ('ap-topic-physc-capacitors_q2', 'ap-topic-physc-capacitors', 2, false, 'B', 'Ch12: Capacitors', 'medium', 'A spherical capacitor consists of two concentric conducting spherical shells of radii a and b (with a < b). What is the capacitance C of this spherical capacitor?', '["4 pi epsilon_0 (b - a)","4 pi epsilon_0 (a b) / (b - a)","4 pi epsilon_0 (b + a)","2 pi epsilon_0 (a b) / (b - a)","4 pi epsilon_0 / (a b)"]'::jsonb, 'When inner shell carries +Q and outer carries -Q, the potential difference is Delta V = (Q / (4 pi epsilon_0)) * (1/a - 1/b) = (Q / (4 pi epsilon_0)) * (b - a) / (a b). Capacitance is C = Q / Delta V = 4 pi epsilon_0 (a b) / (b - a).'),
  ('ap-topic-physc-capacitors_q3', 'ap-topic-physc-capacitors', 3, false, 'E', 'Ch12: Capacitors', 'medium', 'Four identical capacitors, each of capacitance C, are available. Which of the following combinations produces the greatest equivalent capacitance?', '["All four in series","Two in parallel, connected in series with the other two in series","Three in series, connected in parallel with the fourth","Two parallel pairs connected in series","All four connected in parallel"]'::jsonb, 'Capacitances in parallel add directly: C_eq = C1 + C2 + C3 + C4 = 4C. Capacitors in series reduce equivalent capacitance: four in series gives C/4. Any combination involving series connections will have C_eq < 4C. Thus, connecting all four in parallel gives the maximum equivalent capacitance of 4C.'),
  ('ap-topic-physc-capacitors_q4', 'ap-topic-physc-capacitors', 4, false, 'C', 'Ch12: Capacitors', 'medium', 'A parallel-plate capacitor with plate separation d is charged by a battery to potential difference V0 and then isolated. If the plate separation is doubled to 2d while keeping the charge Q constant, what happens to the stored electrostatic energy U?', '["U is halved","U remains the same","U is doubled","U is quadrupled","U is reduced to one-fourth"]'::jsonb, 'Capacitance is C = epsilon_0 A / d. Doubling d halves the capacitance: C_new = C0 / 2. Because the capacitor is isolated, charge Q remains constant. The stored energy is U = Q^2 / (2C). With C halved, U_new = Q^2 / (2 (C0/2)) = 2 (Q^2 / (2C0)) = 2 U0 (the stored energy doubles because positive external work is done pulling the oppositely charged plates apart).'),
  ('ap-topic-physc-capacitors_q5', 'ap-topic-physc-capacitors', 5, false, 'B', 'Ch12: Capacitors', 'medium', 'A sphere is suspended by an insulating cable between the plates of a charged capacitor, resulting in the electric field lines as shown in Figure 12.8. Which of the following is true? Figure 12.8', '["The sphere is an uncharged insulator.","The sphere is a conductor with zero net charge.","The sphere is a positively charged insulator.","The sphere is a negatively charged insulator.","The sphere is a positively charged conductor."]'::jsonb, '(B) Recall that electric field lines begin on positive charge and end on negative charge. Because an equal number of lines begin and end at the sphere, its net charge must be zero. (Imagine drawing an imaginary sphere around the suspended sphere and applying Gauss’s law: The net electric flux would be zero.) However, there is definitely a nonzero charge density on the sphere: negative charge on the top of the sphere and positive charge on the bottom of the sphere. This is the situation we would expect because of electrostatic induction if the sphere were a conductor with zero net charge. (The net charge remains zero, but the external electric field causes the charge to redistribute itself.) Note that the induced charge is on the surface of the sphere, distributed in such a way that the electric field within the metal is zero (as displayed by the fact that no field lines penetrate the sphere).'),
  ('ap-topic-physc-capacitors_q6', 'ap-topic-physc-capacitors', 6, false, 'A', 'Ch12: Capacitors', 'medium', 'A cylindrical coaxial cable has an inner cylindrical conductor of radius a and an outer cylindrical conductor of radius b. What is the capacitance per unit length (C / L) of the cable?', '["2 pi epsilon_0 / ln(b / a)","pi epsilon_0 / ln(b / a)","2 pi epsilon_0 ln(b / a)","4 pi epsilon_0 (b - a)","epsilon_0 / (b - a)"]'::jsonb, 'Let the inner conductor carry charge per unit length lambda. The electric field between the cylinders is E(r) = lambda / (2 pi epsilon_0 r). The potential difference is Delta V = int_a^b E(r) dr = (lambda / (2 pi epsilon_0)) ln(b/a). The capacitance per unit length is C/L = lambda / Delta V = 2 pi epsilon_0 / ln(b/a).'),
  ('ap-topic-physc-capacitors_q7', 'ap-topic-physc-capacitors', 7, false, 'B', 'Ch12: Capacitors', 'medium', 'After the circuit shown in Figure 12.9 has reached equilibrium, what is the potential at point A, designating the potential at the negative terminal of the battery to be zero? Figure 12.9', '["3.33 V","4 V","5 V","6 V","6.66 V"]'::jsonb, '(B) Because the two capacitors are in series, they each have the same charge in equilibrium. Using the equation Q = CV, the voltage across the 4 F capacitor is V4 = Q/4 F, and the voltage across the 6 F capacitor is V6 = Q/6 F. A Kirchhoff’s loop rule equation then yields 10 V = Q/4 F + Q/6 F; solving for Q shows that Q = 24 C. (Note: What we just did is equivalent to simply applying the equation for the equivalent capacitance of two capacitors in series.) Finally, to calculate the potential at point A, we start at the negative terminal of the battery (where V = 0) and trace the circuit counterclockwise to point A, keeping track of potential jumps. The only jump is across the 6 F capacitor, which is a positive jump (because we are going from the negatively charged plate to the positively charged plate) whose value is V = 24 C/6 F = 4 V. Therefore, the potential at point A is 4 V.'),
  ('ap-topic-physc-capacitors_q8', 'ap-topic-physc-capacitors', 8, false, 'B', 'Ch12: Capacitors', 'medium', 'Two identical capacitors of capacitance C are connected in parallel across a voltage source V0. The combination is then disconnected from the source, and a dielectric with kappa = 2 is inserted into one of the capacitors. What is the new potential difference across the parallel combination?', '["V0 / 3","2/3 V0","V0","4/3 V0","2 V0"]'::jsonb, 'Initially, total charge is Q_total = C_eq V0 = (2C) V0. When dielectric with kappa = 2 is inserted into one capacitor, its capacitance becomes 2C, so the new equivalent capacitance of the parallel pair is C_eq,new = 2C + C = 3C. Because the system is isolated, total charge is conserved: V_new = Q_total / C_eq,new = (2C V0) / (3C) = 2/3 V0.'),
  ('ap-topic-physc-capacitors_q9', 'ap-topic-physc-capacitors', 9, false, 'B', 'Ch12: Capacitors', 'medium', 'A parallel plate capacitor is connected to a battery. If the plate separation is doubled, after the circuit is allowed to reach equilibrium, the relationship between the final electric field and the initial electric field within the capacitor is', '["EF = E0/4","EF = E0/2","EF = E0","EF = 2E0","EF = 4E0"]'::jsonb, '(B) Recall that for a parallel plate capacitor, the relationship among voltage, electric field, and plate separation is |V| = |E|d. Because the capacitor is equilibrated with a battery of the same voltage before and after doubling the plate separation, the voltage is the same in both cases. Therefore, doubling the plate separation causes the electric field to decrease by a factor of 2.'),
  ('ap-topic-physc-capacitors_q10', 'ap-topic-physc-capacitors', 10, false, 'B', 'Ch12: Capacitors', 'medium', 'In the situation described in question 5, which of the following is a valid comparison of the energy stored in the capacitor before and after the plate separation is doubled?', '["UF = U0/4","UF = U0/2","UF = U0","UF = 2U0","UF = 4U0"]'::jsonb, '(B) The energy of a capacitor can be expressed using any two of the three variables Q, C, and V; in this case, the most convenient formula to use is because it is easiest to figure out what happens to the voltage and capacitance before and after plate separation. As in question 5, because the capacitor is allowed to equilibrate with the same battery before and after increasing the plate separation, the voltage is the same in both cases. Since the capacitance of a parallel plate capacitor is given by the equation , doubling the plate separation decreases the capacitance by a factor of 2. Thus, using the equation , we see that the potential energy decreases by a factor of 2.'),
  ('ap-topic-physc-capacitors_q11', 'ap-topic-physc-capacitors', 11, false, 'C', 'Ch12: Capacitors', 'medium', 'If the capacitor described in question 5 were disconnected from the battery before the plates were separated, the relationship between the initial and final electric fields would be', '["EF = E0/4","EF = E0/2","EF = E0","EF = 2E0","EF = 4E0"]'::jsonb, '(C) Recall that the electric field due to an infinite sheet of charge does not depend on how close you are to the infinite sheet of charge. Because the capacitor is isolated, the charge has nowhere to go, so the charge density on the plates remains unchanged. Since the plates act approximately like infinite sheets of charge, the field between them does not depend on the distance between the sheets, so it remains unchanged. Perhaps a more straightforward, mathematical solution would involve the equations Q = CV and V = Ed. Because Q remains constant, CV must remain constant. As discussed in the last section, C decreases by a factor of 2 when the plate separation is doubled, so V must then increase by a factor of 2 for CV to remain constant. Now consider the equation V = Ed. Because both V and d increase by a factor of 2, E must remain constant.'),
  ('ap-topic-physc-capacitors_q12', 'ap-topic-physc-capacitors', 12, false, 'D', 'Ch12: Capacitors', 'medium', 'Again, supposing that the capacitor described in question 5 were disconnected from the battery before the plates were separated, the relationship between the initial and final energies would be', '["UF = U0/4","UF = U0/2","UF = U0","UF = 2U0","UF = 4U0"]'::jsonb, '(D) In this case, the most convenient formula to use for the energy stored on the capacitor is U = Q2/2C. Because the capacitor is disconnected before the plates are separated, the charge has nowhere to go, so it remains constant. As before, because the distance is doubled, the capacitance is halved. Combining these observations with the formula U = Q2/2C indicates that the amount of energy is doubled. This makes sense: Physically pulling apart the plates (which attract each other) requires energy, so we expect the potential energy of the capacitor to increase. (Pulling the plates apart in question 7 also required work, but this work was more than compensated for by charge that moved across the battery, increasing its potential energy.) From this reasoning, we could have immediately eliminated choices (A), (B), and (C).'),
  ('ap-topic-physc-capacitors_q13', 'ap-topic-physc-capacitors', 13, false, 'E', 'Ch12: Capacitors', 'medium', 'For a parallel plate vacuum capacitor, the electric field within the capacitor can be calculated from each of the following combinations of variables except', '["the magnitude of the charge density on the plates \\sigma","the voltage of the capacitor V and the plate separation distance d","the charge on the plates Q, the capacitance C, and the plate separation distance d","the magnitude of charge on the plates Q and the area of the plates A","the energy stored in the capacitor U, the voltage across the capacitor V, and capacitance C Free-Response Questions"]'::jsonb, '(E) Calculation of the electric field from the parameters given in choices (A)–(D) is shown below, demonstrating that they are not the correct answer. For choice (A), approximating the plates as infinite sheets of charge, the electric field due to an infinite sheet of charge is E = \sigma/2\epsilon0 (which does not depend on the distance from the sheet of charge). Within the capacitor, the electric fields due to the two plates add so that the net electric field is E = \sigma/\epsilon0. For choice (B), for a parallel plate capacitor, V = Ed, so E = V/d. For choice (C), from Q and C, the voltage can be calculated using the equation Q = CV. Then, given the voltage and the separation distance, the electric field can be calculated using the formula E = V/d as in choice (B). For choice (D), from the magnitude of charge per plate and the plate area, the charge density can be calculated as \sigma = Q/A. Then, the electric field can be calculated from the charge density as in choice (A). The variables in choice (E) do not allow calculation of the electric field. From U, V, and C, one could calculate the charge Q = CV. However, without knowing the area of the plates or the plate separation distance, it is impossible to calculate the electric field. Free-Response 1. (a) This section is a straightforward application of Gauss’s law (in the case of spherical symmetry and thus spherical gaussian surfaces). (i) Because there is zero net charge enclosed, the field is zero for r > r2. (ii) In this region, the enclosed charge is −Q, so the electric field points toward the center of the sphere. Because the directed area vector dA points away from the surface (by definition), (iii) In this region, the enclosed charge is again zero, so the field is zero. (b) This section involves applying the equation (i) In the region x > r2, the electric field is zero. Therefore, the potential integral above is zero, and the potential is zero within this region. (ii) Here’s where things get a little tricky: As just discussed in part (b)(i), the first of these integrals is equal to zero because the electric field is zero. In the second integral, we use the electric field calculated in part (a)(ii), noting that the direction of the field is in the negative x-direction: Therefore, the calculated potential at r1 is negative. This makes sense: A positive charge is attracted toward the center of the sphere and tends to move downhill from r2 to r1; thus, r2 is at a higher potential than r1. (c) The definition of capacitance is the charge stored per potential difference: 2. (a) See Figure 12.13. The electric field is uniform and perpendicular to the plates. The equipotential curves are perpendicular to the electric field lines and equally spaced (because potential is a linear function that depends only on the relative distance between the two plates). Figure 12.13 (b) The flux through all faces parallel to the field or immersed in the metal is zero (because the field is parallel to the surface or zero, respectively). Therefore, the net flux through box A is zero. The net flux through box B is zero because the inward flux through the bottom face cancels the outward flux through the top face (recall that the electric field within a parallel plate capacitor is constant, so these fluxes are equal in magnitude). Another way to realize that the flux through boxes A and B is zero is because they enclose zero net charge (box A contains equal amounts of positive and negative charge; box B contains no charge at all). Box C encloses net charge, so its flux is nonzero (there is nonzero flux through the top face and no flux through any other faces). Because box C is the only box with nonzero net flux, it is the only box where the application of Gauss’s law is nontrivial. (c) The flux through box C is Applying Gauss’s law, Note that the field does not depend on the arbitrary area of our imaginary gaussian surface (that would be a problem). Also note that comparison with the equation for the electric field due to a sheet of charge, E = \sigma/2\epsilon0, immediately reveals that this equation has correct units. (d) Consider the equations C = Q/V and V = Ed (the relationship between voltage and electric field for a parallel plate capacitor). We know that adding a dielectric increases the capacitance by a factor of κD. Because charge is constant (the capacitor is isolated), this means that the voltage decreases by a factor of κD. Now, considering the second equation, because d is constant, E also decreases by a factor of κD. Therefore, the new value of E is This answer makes intuitive sense: Induced charge on the dielectric partially cancels charge on the plates, reducing the effective charge on the plates and thus reducing the electric field. 3. (a) See Figure 12.14 (the only electric field is in the region a < r < b). The electric field points radially away from the positive charge on the inner cylinder. The circular equipotential curves are perpendicular to the field lines and thus more closely spaced near the inner cylinder (where the magnitude of the electric field is greater). Note that charge is arranged on the outer surface of the inner cylinder and the inner surface of the sheath (as required for the electric field within the metal to be zero). Figure 12.14 (b) Away from the edges of the cylinder, we can treat the cylinder as if it were infinitely long. Applying Gauss’s law, we have cylindrical symmetry and so we use a cylindrical Gaussian surface of length ℓ and radius a < r < b. The flux through the ends of the Gaussian cylinder is zero because the field is parallel to the surface of the caps. The flux through the sides is equal to Applying Gauss’s law, (c) To calculate this potential difference, we must find a path where the electric field is easily calculated (and, ideally, parallel to the path of integration). A suitable path is one perpendicular to the axis of the cylinder (so that it is parallel to the field) and at the center of the capacitor (so that edge effects can be ignored and the above expression for the electric field can be used). Integrating, Because V(b) − V(a) is negative, the potential is greater at a (as always, the positive plate of the capacitor is at a higher potential). (d) The charge on the capacitor is Q = \lambdal, and the magnitude of the potential difference across the capacitor is Therefore, the capacitance is 4. (a) The total charge on the capacitors remains 2Q0 because of charge conservation. However, the charge on each will no longer be Q0. We can determine the new charges Q1 and Q2 as follows: The capacitors are in parallel and thus have a common voltage difference V, which we will see in part (b) is not equal to the original V0. We know that , with Q1 + Q2 = 2Q0 (charge conservation). If we label the capacitor without the dielectric #1, then and C2 = κD C1. From the equality of the potential differences across the capacitors and charge conservation we can write Check that if there is no dielectric present, i.e., κD = 1, the answers reduce to Q1 = Q2 = Q0. (b) The common voltage V can be found from either capacitor: (c) Because κD > 1 the voltage has decreased as expected with the insertion of a dielectric. (d) The total energy stored is (e) The initial total energy is . Because κD > 1 we see that the energy has decreased due to the addition of the dielectric. The dielectric is attracted to the capacitor because of the charge induced on the dielectric, which is attracted to the charges on the plates; see Figure 12.6. 1Note that we’re using the conventional-current description here (in reality, the electrons are actually moving).'),
  ('ap-topic-physc-capacitors_q14', 'ap-topic-physc-capacitors', 14, false, 'C', 'Diagnostic Test – E&M', 'medium', 'Two metal spheres with radii r1 and r2 carrying positive charges Q1 and Q2 are separated by a very large distance. A thin wire connects the two spheres. Under what condition will positive charge flow from sphere 1 to sphere 2?', '["Q1 > Q2","r1 > r2","Q1 / r1 > Q2 / r2","Q1 r1 > Q2 r2","Q1 / r1^2 > Q2 / r2^2"]'::jsonb, 'Positive charge flows from higher to lower electric potential: V = k Q / r. Charge flows from 1 to 2 if V1 > V2 ==> Q1 / r1 > Q2 / r2.'),
  ('ap-topic-physc-capacitors_q15', 'ap-topic-physc-capacitors', 15, false, 'C', 'Diagnostic Test – E&M', 'medium', 'A charged particle is launched into a region of uniform magnetic field. Given that the particle’s initial velocity has components parallel and perpendicular to the magnetic field, describe the particle’s path qualitatively.', '["a straight line","a circle","a helical (corkscrew) path","a parabolic path","none of the above"]'::jsonb, '(C) See the discussion of the motion of particles within magnetic fields in Chapter 14.'),
  ('ap-topic-physc-capacitors_q16', 'ap-topic-physc-capacitors', 16, false, 'B', 'Diagnostic Test – E&M', 'medium', 'A point charge +Q is located at a fixed distance from a sphere. Compare the magnitude of the attractive force on the sphere if the sphere is (1) metal with net charge −Q, (2) metal with no net charge, (3) an insulator with net charge −Q, or (4) an insulator with no net charge.', '["charged metal = charged insulator > uncharged metal = uncharged insulator","charged metal > charged insulator > uncharged metal > uncharged insulator","charged insulator > charged metal > uncharged insulator > uncharged metal","charged insulator > charged metal > uncharged metal = uncharged insulator","charged insulator = charged metal > uncharged metal > uncharged insulator"]'::jsonb, '(B) This is a question about electrostatic induction. When a positive point charge is placed near a metal sphere (charged or uncharged), it attracts mobile electrons in the metal, causing the metal to become polarized such that more negative charge is on the side closer to the positive point charge and more positive charge is on the side farther away from the positive point charge. Because this charge redistribution results in moving negative charge closer to the positive point charge and moving positive charge farther away from the positive point charge, it increases the attractive force between the metal sphere and the positive point charge. Therefore, compared to an insulating sphere with the same net charge, a metal sphere always experiences a greater attractive force (such that charged metal > charged insulator and uncharged metal > uncharged insulator). Because this inductive effect is small compared to the effect of actually putting net charge −Q on the sphere, charged insulator > uncharged metal.'),
  ('ap-topic-physc-capacitors_q17', 'ap-topic-physc-capacitors', 17, false, 'C', 'Diagnostic Test – E&M', 'medium', 'A bar moves to the right through a magnetic field as shown (the magnetic field points into the page). What is the potential difference between points A and B after equilibrium is established in the bar?', '["The difference is v2Bd, with A at higher potential.","The difference is v2Bd, with B at higher potential.","The difference is vBd, with A at higher potential.","The difference is vBd, with B at higher potential.","Because there is no loop, there is no flux, so there is no potential difference."]'::jsonb, '(C) The charges within the bar are moving in a magnetic field, so they feel a magnetic force. Using the conventional-current description, positive charges feel an upward force, causing positive charge to accumulate at the top end of the bar (leaving negative charge on the bottom end of the bar). This charge continues to accumulate until the electric force created by the charge imbalance cancels the magnetic force, mathematically qE = qvB. The magnitude of the potential difference between points A and B is then |V | = |−\int E \cdot  dr| = |vBd|. The electric field points down (producing a force that opposes the magnetic force), and recalling that electric fields point from high to low potential, we see that point A is at the higher potential. Further information about motional EMF can be found in Example 15.6.'),
  ('ap-topic-physc-capacitors_q18', 'ap-topic-physc-capacitors', 18, false, 'B', 'Diagnostic Test – E&M', 'medium', 'Suppose that the electric potential in a region of space is a constant. What can you conclude about the magnitude of the electric field in this region?', '["It is a nonzero constant.","It is zero.","It is proportional to the distance from the origin.","It is given by","Not enough information is given. Questions 6–8 refer to a circular region of radius a with a uniform magnetic field pointing into the page that is increasing at a constant rate as shown. A circular loop of wire of radius r is centered on the middle of the region."]'::jsonb, '(B) The electric field is the negative derivative (with respect to the spatial coordinate) of the potential. Thus, with a constant potential the electric field must be zero.'),
  ('ap-topic-physc-capacitors_q19', 'ap-topic-physc-capacitors', 19, false, 'C', 'Diagnostic Test – E&M', 'medium', 'Which of the graphs plots the induced EMF in the circular loop of wire shown as a function of its radius r?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(C) The induced EMF depends on the change in the enclosed flux. Because the magnetic field is uniform, and changing at a constant rate, Therefore, the induced EMF depends only on the area of the loop through which magnetic field lines pass. For r < a, the area within the loop exposed to the magnetic field is simply the entire area of the loop, which is a quadratic function, A(r) = \pir2. For r > a, increasing r does not increase the area exposed to the magnetic field (because the magnetic field through the additional area is zero). Therefore, for r > a the induced EMF is constant. The only graph that is quadratic for small r and then constant is choice (C). Calculating the induced EMF due to a magnetic field via Faraday’s law is discussed in Chapter 15.'),
  ('ap-topic-physc-capacitors_q20', 'ap-topic-physc-capacitors', 20, false, 'A', 'Diagnostic Test – E&M', 'medium', 'Given that the resistance of the loop is proportional to the loop’s circumference, which of the graphs seen in question 6 shows the induced current as a function of the radius of the loop?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(A) The current is given by I = V/R. The resistance is proportional to the circumference of the loop, 2\pir. Therefore, for r < a, V is proportional to r2 (as discussed in question 6), and 1/R is proportional to 1/r, so the product I = V/R is proportional to r (and thus its graph is a line passing through the origin). For r > a, V is constant and 1/R is proportional to 1/r, so the product I = V/R is inversely proportional to r. The only graph that satisfies these conditions is choice (A).'),
  ('ap-topic-physc-induction_q1', 'ap-topic-physc-induction', 1, false, 'A', 'Ch15: Electromagnetism', 'medium', 'An external force pushes a square loop of wire through a region of constant magnetic field as shown in Figure 15.9. Which of the following is a plot of the magnetic flux as a function of the position of the loop? Figure 15.9', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(A) The magnetic flux is proportional to the portion of the loop’s area that is exposed to the magnetic field. This area increases linearly as the loop enters the field, remains constant while the loop is completely within the field, and decreases as the loop exits the field.'),
  ('ap-topic-physc-induction_q2', 'ap-topic-physc-induction', 2, false, 'A', 'Ch15: Electromagnetism', 'medium', 'A planar loop of wire with area A and resistance R is positioned perpendicular to a uniform magnetic field directed into the page. If the magnitude of the magnetic field decreases at a constant rate dB/dt = -alpha, what is the direction and magnitude of the induced current in the loop?', '["Clockwise with magnitude alpha A / R","Counterclockwise with magnitude alpha A / R","Counterclockwise with magnitude alpha A R","Clockwise with magnitude alpha A R","Zero because the field is uniform"]'::jsonb, 'By Faraday''s Law, the induced EMF is EMF = -dPhi_B/dt = -A (dB/dt) = A alpha. By Lenz''s Law, the induced current must oppose the change in flux. Because the inward magnetic flux is decreasing, the induced current must produce an inward magnetic field to support the flux. By the right-hand rule, a clockwise current produces an inward magnetic field. The current magnitude is I = EMF / R = alpha A / R.'),
  ('ap-topic-physc-induction_q3', 'ap-topic-physc-induction', 3, false, 'A', 'Ch15: Electromagnetism', 'medium', 'A square conducting loop of side length L, mass m, and resistance R moves at constant speed v into a region of uniform magnetic field B directed perpendicular to the loop plane. What is the magnitude of the magnetic braking force exerted on the loop while it is entering the field?', '["B^2 L^2 v / R","B L v / R","B^2 L v^2 / R","B^2 L^2 v^2 / R","Zero"]'::jsonb, 'While entering the field, the flux increases at rate dPhi_B/dt = B L v, inducing EMF = B L v. The induced current is I = EMF / R = B L v / R. The magnetic force on the leading edge is F = I L B = (B L v / R) L B = B^2 L^2 v / R. By Lenz''s Law, this force opposes the motion (acts as a braking force).'),
  ('ap-topic-physc-induction_q4', 'ap-topic-physc-induction', 4, false, 'E', 'Ch15: Electromagnetism', 'medium', 'Referring to the situation in question 1, which of the plots in Figure 15.9 shows the force due to the field on the wire, now carrying induced current (designating rightward force as positive)?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(E) As the loop both enters and leaves the magnetic field, the forces produced by the field on the top and bottom of the current-carrying loop cancel each other. The only vertical wire (on the right segment as the loop enters and on the left segment as it exits) exposed to the magnetic field carries current toward the bottom of the page, producing a net leftward force. Choice (E) is the only choice that is negative as the loop both enters and leaves the loop. Answer check: It makes sense that the force is constant, because the magnitude of the induced current is constant.'),
  ('ap-topic-physc-induction_q5', 'ap-topic-physc-induction', 5, false, 'A', 'Ch15: Electromagnetism', 'medium', 'A conducting rod of length L and mass m slides down frictionless parallel conducting rails tilted at an angle theta to the horizontal in a uniform vertical magnetic field B. A resistor R connects the rails. What is the terminal speed v_t of the rod?', '["m g R sin(theta) / (B^2 L^2 cos^2(theta))","m g R tan(theta) / (B^2 L^2)","m g R / (B^2 L^2)","m g R cos(theta) / (B^2 L^2 sin(theta))","m g R sin^2(theta) / (B^2 L^2)"]'::jsonb, 'The component of the magnetic field perpendicular to the rails is B cos(theta). The motional EMF is EMF = B cos(theta) L v, giving induced current I = B cos(theta) L v / R. The horizontal magnetic force is F_mag = I L B = B^2 L^2 v cos(theta) / R. The component of F_mag opposing motion along the incline is F_mag cos(theta) = B^2 L^2 v cos^2(theta) / R. At terminal speed, this balances the component of gravity down the incline: m g sin(theta) = B^2 L^2 v_t cos^2(theta) / R ==> v_t = m g R sin(theta) / (B^2 L^2 cos^2(theta)).'),
  ('ap-topic-physc-induction_q6', 'ap-topic-physc-induction', 6, false, 'A', 'Ch15: Electromagnetism', 'medium', 'Consider Figure 15.10. The current in the straight wire varies with time, inducing a current in the loop. Which of the following statements is true about the magnetic force exerted on the loop of wire due to the straight wire? Figure 15.10', '["The force is to the right if I is increasing and to the left if I is decreasing.","The force is to the left if I is increasing and to the right if I is decreasing.","The force is to the left regardless of whether I is increasing or decreasing.","The force is to the right regardless of whether I is increasing or decreasing.","The force is zero because the force on each side of the rectangular loop cancels the force on the opposite side of the loop."]'::jsonb, '(A) The force on the top of the loop cancels the force on the bottom of the loop, but the force on the left side of the loop dominates over the force on the right side of the loop because the left side is closer to the current-carrying wire and thus experiences a greater magnetic field. Therefore, whether I is increasing or decreasing, the net force on the loop is in the same direction as the force on the left side of the loop. The rest of the problem consists of applying Lenz’s law in each situation (to find the direction of the induced current on the loop) and then using the right-hand rule to determine the direction of the force on the left side of the loop (F = Il \times  B). You should convince yourself that the following are true:'),
  ('ap-topic-physc-induction_q7', 'ap-topic-physc-induction', 7, false, 'A', 'Ch15: Electromagnetism', 'medium', 'A long solenoid with n turns per unit length and radius R carries a time-varying current I(t) = I0 sin(omega t). What is the magnitude of the induced electric field E(r) at a radial distance r < R from the central axis inside the solenoid?', '["1/2 mu_0 n I0 omega r cos(omega t)","mu_0 n I0 omega r cos(omega t)","1/2 mu_0 n I0 r sin(omega t)","mu_0 n I0 omega R^2 / r cos(omega t)","Zero"]'::jsonb, 'Inside the solenoid, the magnetic field is B(t) = mu_0 n I(t) = mu_0 n I0 sin(omega t). Using Faraday''s Law in integral form: oint E * dl = -dPhi_B/dt. For a circular path of radius r < R: E (2 pi r) = -pi r^2 (dB/dt) = -pi r^2 (mu_0 n I0 omega cos(omega t)). The magnitude of the induced electric field is E(r) = 1/2 mu_0 n I0 omega r cos(omega t).'),
  ('ap-topic-physc-induction_q8', 'ap-topic-physc-induction', 8, false, 'A', 'Ch15: Electromagnetism', 'medium', 'A uniform magnetic field points out of the page through a circular area as shown in Figure 15.11. If the magnetic field strength is decreasing, the electric field at point P Figure 15.11', '["points upward","points downward","points to the left","points to the right","is zero because of symmetry"]'::jsonb, '(A) Imagine a loop of wire concentric with the circular region of magnetic field but passing through point P. From Lenz’s law, current will flow counterclockwise through the loop. Because the flow of current is parallel to the electric field along the loop and because of the symmetry considerations discussed in Example 15.4 that establish that the radial component of the field is zero, the field will point up, so choice (A) is correct.'),
  ('ap-topic-physc-induction_q9', 'ap-topic-physc-induction', 9, false, 'A', 'Ch15: Electromagnetism', 'medium', 'A metal rod of length L rotates with constant angular velocity omega about an axis through one end, perpendicular to a uniform magnetic field B. What is the induced potential difference (motional EMF) between the two ends of the rod?', '["1/2 B omega L^2","B omega L^2","1/2 B omega^2 L","2 B omega L^2","Zero"]'::jsonb, 'An element of the rod of length dr at distance r from the pivot moves with linear speed v = omega r. The motional EMF across dr is d(EMF) = v B dr = B omega r dr. Integrating from r = 0 to r = L: EMF = int_0^L B omega r dr = 1/2 B omega L^2.'),
  ('ap-topic-physc-induction_q10', 'ap-topic-physc-induction', 10, false, 'A', 'Ch15: Electromagnetism', 'medium', 'A circular loop of wire of diameter d moves with constant velocity across a region with a constant magnetic field as in Figure 15.12. Choosing counterclockwise current as positive, which of the graphs in Figure 15.13 is a plot of the induced current as a function of the x- coordinate of point P on the loop? Figure 15.12 Figure 15.13', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(A) From x = 0 to x = d, the flux into the page across the loop is increasing, so a counterclockwise current is produced to oppose this increase in flux. This eliminates choices (B), (D), and (E). The magnitude of the current depends on the change in flux per unit time, which depends on the additional amount of area that enters the magnetic field region per unit time. The rate at which area enters the magnetic field is proportional to the height of the portion of the loop in the field region. This height is a continuous nonlinear function of the location of P. Thus, of the two remaining choices, (A) is correct.'),
  ('ap-topic-physc-induction_q11', 'ap-topic-physc-induction', 11, false, 'A', 'Ch15: Electromagnetism', 'medium', 'Consider the circuit shown in Figure 15.19, which has a mass m and is free to move up and down. Figure 15.19 (a) Assuming that the loop starts from rest and initially accelerates upward, what is the magnitude of the induced EMF as a function of the loop’s speed? (b) What is the current as a function of the loop’s speed? (c) What is the net force on the loop as a function of its speed? (Designate upward as positive.) (d) What is the loop’s terminal speed? (e) Considering the fact that the bottom of the loop eventually passes into region 1, qualitatively describe the motion of the loop when it is entirely in region 1. 1It may seem that there are a lot of Faraday’s law problems. There are good reasons for this: (1) Faraday’s law problems are very common on AP exams, rivaling Gauss’s law problems for popularity with about one per exam, and (2) although these problems are centered around Faraday’s law, they review other topics as well.', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(A) From x = 0 to x = d, the flux into the page across the loop is increasing, so a counterclockwise current is produced to oppose this increase in flux. This eliminates choices (B), (D), and (E). The magnitude of the current depends on the change in flux per unit time, which depends on the additional amount of area that enters the magnetic field region per unit time. The rate at which area enters the magnetic field is proportional to the height of the portion of the loop in the field region. This height is a continuous nonlinear function of the location of P. Thus, of the two remaining choices, (A) is correct.'),
  ('ap-topic-physc-induction_q12', 'ap-topic-physc-induction', 12, false, 'D', 'Ch15: Electromagnetism', 'medium', 'A loop of wire is moved toward a pole of a bar magnet as shown in Figure 15.14. The force on the loop is Figure 15.14', '["toward the magnet if the loop is closer to the north pole of the magnet and away from the magnet if the loop is closer to the south pole of the magnet","toward the magnet if the loop is closer to the south pole of the magnet and away from the magnet if the loop is closer to the north pole of the magnet","toward the magnet regardless of which pole of the magnet is closer to the loop","away from the magnet regardless of which pole of the magnet is closer to the loop","zero because of vector cancellation and symmetry considerations Free-Response Questions 1.1 A rectangular loop of wire (resistance R, mass m) levitates below an infinitely long current-carrying wire as shown in Figure 15.15. Figure 15.15 (a) If a current Iwire flows through the current-carrying wire, what is the magnitude of the magnetic flux in the loop? (b) If the current in the wire is decreasing at a rate of dIwire/dt, what is the magnitude and direction of the induced EMF in the loop? (c) What is the induced current in the loop? (d) What is the magnetic force on the loop? (Give magnitude and direction.)"]'::jsonb, '(D) First, let’s consider the situation where the north pole is closer to the loop, as shown in Figure 15.20. Recall that, outside the magnet, the field lines point away from the north pole and the magnitude of the field increases as we approach the poles. Therefore, as you move the loop closer to the north pole, the upward flux through the loop increases, inducing a current in the indicated direction (clockwise as viewed from above). Using the right-hand rule, the force on any differential length of wire points upward and toward the center of the loop. Because of symmetry, the horizontal components of these differential forces cancel, leaving a net force away from the magnet. Therefore, if the loop is closer to the north pole, the force is away from the magnet, eliminating choices (E), (A), and (C). Figure 15.20 Another way to realize that the loop repels the magnet is to sketch the magnetic field lines produced by the current induced in the loop, as shown in Figure 15.21. The current through the loop creates a magnetic dipole much like that created by a bar magnet, with the north end of the dipole on the bottom, closer to the north pole of the magnet. Because like magnetic poles repel, the loop is expected to repel the magnet. Figure 15.21 What if the loop is closer to the south pole of the magnet? The field lines, and therefore the direction of the current, will be reversed. However, because both the magnetic field and the current have reversed their directions, these opposite signs will cancel in the equation dF = Idl \times  B and the same force will be produced. Therefore, the correct answer is (D). The most powerful and simple way to solve this problem, however, is to realize that currents are induced such that the force on the current- carrying wire caused by the external magnetic field always tries to oppose the change in magnetic flux. For example, when a loop is being pushed into a region of nonzero magnetic field, the magnetic force on the loop (now carrying induced current) always tries to oppose the motion of the loop into the region of nonzero magnetic field. This is a restatement of Lenz’s law at the force level. The justification of this statement is similar to the justification of Lenz’s law: If the opposite were true, one could imagine a situation where conservation of energy was violated (the loop would move with ever-increasing speed into the region of the magnetic field with kinetic energy produced from no identifiable source). Free-Response 1. (a) Because the magnetic field within the loop is not constant, we must integrate. To mirror the cylindrical symmetry of the magnetic field, we divide the loop into differential rectangles running parallel to the infinite wire, with dimensions dr by l and area dA = ldr. The differential flux through a given differential area is then (given that the magnetic field due to an infinite wire is . Integrating, (b) According to Faraday’s law, Decreasing current causes a decrease of flux into the page, and the current flows clockwise to counter this decrease in inward flux. (c) (d) Given the direction of the current, the direction of the magnetic field, and the equation F = lI \times  B, the following are the directions of the force on all the wire segments: top segment, upward force; bottom segment, downward force; left segment, leftward force; right segment, rightward force. As a result of symmetry, the rightward and leftward forces have the same magnitude and cancel. However, since the top segment is closer to the wire than the bottom segment, it experiences a larger force, producing a net upward force on the loop. Quantitatively, this force (designating positive as upward) is 2. (a) As the loop enters the field, during a time interval dt, the area of the loop exposed to the field changes by a differential strip with height l and thickness dx (and thus, area dA = ldx). The change in flux during dt is thus (choosing flux out of the page as positive and the direction of dA as out of the page) Applying Faraday’s law, Alternative solution: Letting x be the horizontal length of the loop exposed to the magnetic field, As the loop exits the field, the rate at which the flux changes is the same, and thus the EMF has the same magnitude (the only difference is that the outward flux is decreasing rather than increasing). (b) (c) As the loop enters the field, the current is clockwise; as the loop exits the field, the current is counterclockwise (Lenz’s law). (d) The magnetic field exerts a force on current-carrying wires equal to F = Il \times  B. The forces on the top and bottom segments of the loop always cancel, and the net force is due to the vertical segment within the magnetic field, with magnitude As the loop enters the region of the field, the induced current flows clockwise, and thus current flows downward through the segment exposed to the magnetic field (the right side of the square). As the loop exits the field, current flows counterclockwise, yet it also flows downward through the segment exposed to the magnetic field (the left side of the square). Thus, current is always flowing downward through the vertical segment exposed to the magnetic field, and the direction is thus always to the left (opposite the velocity). 3. (a) During a time increment dt, the area of the circuit increases by a differential strip of area, dA = A dx. The increase in flux during this time dt is equal to the flux through the new strip, which equals d\Phi = B dA = Bl dx (setting dA pointing out of the page). Therefore, applying Faraday’s law: (b) According to Ohm’s law, (c) The bar experiences two forces: a gravitational force equal to mg, and the force exerted by a magnetic field on a current-carrying wire. Designating the downward direction as positive, What about the force exerted by the magnetic field? Lenz’s law requires the current to flow in a clockwise direction, making this force point upward. The acceleration is then simply the net force divided by the mass: (d) At the terminal velocity the acceleration is zero. Therefore, we can solve for the terminal velocity by setting the acceleration equal to zero: Answer check: Larger B and larger l or smaller R produce a greater magnetic force and thus a smaller terminal velocity. Greater mass and greater g produce a larger gravitational force and thus a larger terminal velocity. 4. (a) (i) Making a straightforward application of Faraday’s law, (ii) (iii) Because the magnetic field outside an infinite solenoid is zero, the flux and EMF are the same as in part (a)(ii). (b) (i) (For further explanation, see Example 15.4.) (ii) Similarly, (iii) Again, (c) If f(t) is increasing, flux into the page is increasing. To oppose this increase in flux, the induced current flows counterclockwise and the electric field (parallel to the current) points tangentially to the path in the counterclockwise direction (since the current flows in the direction of the electric field). (d) No. The induced electric field lines are circles, so the electric field has no radial component. Since there is no force capable of providing centripetal force, the charge cannot move in a circular path. 5. (a) As the bar begins to rotate, the positive current-carrying charges feel a magnetic force, F = qv \times  B, pointing along the rod toward the pivot. The positive charges are driven toward the pivot, leaving negative charge at the opposite end. This uneven charge distribution creates an electric force that will eventually cancel out the magnetic force and cause the current to stop. (b) In Example 15.6 we saw that the induced EMF in a bar moving to the right at speed v is given by | | = Bℓv. In the present case, we must use this equation in a differential form, |d | = B(dr)v for a small segment dr of the rod (see Figure 15.22). The total EMF will be the integral over the differential EMFs. The velocity of the small segment is given by v = \omegar. Thus, (c) The electric force induced by the uneven charge distribution points away from the pivot where the positive charge accumulates. Thus, the pivot is at higher potential compared to the other end of the rod. Figure 15.22 6. (a) During a time dt, the area exposed to the magnetic field increases by a differential strip of area dA = lvdt, where v is the speed of the loop and the magnetic flux increases by an amount d\PhiB = B ⋅ dA = Blv dt. Therefore, the induced EMF is (b) From Lenz’s law, the EMF opposes the battery (and pushes current counterclockwise). Therefore, the voltage across the resistor is The current is then (c) The magnitude of the upward magnetic force is The gravitational force is −mg, so the net force is (d) At the terminal speed, the net force is zero. Therefore, (e) When the loop is entirely within region 1, there is no net magnetic force on the loop (because the force on each segment is canceled by the opposite segment). With no magnetic force, the net force is due to gravity alone, so the loop behaves as if in free fall (with an initial upward velocity given by its velocity as the bottom of the loop enters region 1) and the y(t) function is parabolic.'),
  ('ap-topic-physc-induction_q13', 'ap-topic-physc-induction', 13, false, 'C', 'Diagnostic Test – E&M', 'medium', 'Two metal spheres with radii r1 and r2 carrying positive charges Q1 and Q2 are separated by a very large distance. A thin wire connects the two spheres. Under what condition will positive charge flow from sphere 1 to sphere 2?', '["Q1 > Q2","r1 > r2","Q1 / r1 > Q2 / r2","Q1 r1 > Q2 r2","Q1 / r1^2 > Q2 / r2^2"]'::jsonb, 'Charge flows from higher to lower electric potential: V = k Q / r. Positive charge flows from 1 to 2 if V1 > V2 ==> Q1 / r1 > Q2 / r2.'),
  ('ap-topic-physc-induction_q14', 'ap-topic-physc-induction', 14, false, 'C', 'Diagnostic Test – E&M', 'medium', 'A charged particle is launched into a region of uniform magnetic field. Given that the particle’s initial velocity has components parallel and perpendicular to the magnetic field, describe the particle’s path qualitatively.', '["a straight line","a circle","a helical (corkscrew) path","a parabolic path","none of the above"]'::jsonb, '(C) See the discussion of the motion of particles within magnetic fields in Chapter 14.'),
  ('ap-topic-physc-induction_q15', 'ap-topic-physc-induction', 15, false, 'B', 'Diagnostic Test – E&M', 'medium', 'A point charge +Q is located at a fixed distance from a sphere. Compare the magnitude of the attractive force on the sphere if the sphere is (1) metal with net charge −Q, (2) metal with no net charge, (3) an insulator with net charge −Q, or (4) an insulator with no net charge.', '["charged metal = charged insulator > uncharged metal = uncharged insulator","charged metal > charged insulator > uncharged metal > uncharged insulator","charged insulator > charged metal > uncharged insulator > uncharged metal","charged insulator > charged metal > uncharged metal = uncharged insulator","charged insulator = charged metal > uncharged metal > uncharged insulator"]'::jsonb, '(B) This is a question about electrostatic induction. When a positive point charge is placed near a metal sphere (charged or uncharged), it attracts mobile electrons in the metal, causing the metal to become polarized such that more negative charge is on the side closer to the positive point charge and more positive charge is on the side farther away from the positive point charge. Because this charge redistribution results in moving negative charge closer to the positive point charge and moving positive charge farther away from the positive point charge, it increases the attractive force between the metal sphere and the positive point charge. Therefore, compared to an insulating sphere with the same net charge, a metal sphere always experiences a greater attractive force (such that charged metal > charged insulator and uncharged metal > uncharged insulator). Because this inductive effect is small compared to the effect of actually putting net charge −Q on the sphere, charged insulator > uncharged metal.'),
  ('ap-topic-physc-induction_q16', 'ap-topic-physc-induction', 16, false, 'C', 'Diagnostic Test – E&M', 'medium', 'A bar moves to the right through a magnetic field as shown (the magnetic field points into the page). What is the potential difference between points A and B after equilibrium is established in the bar?', '["The difference is v2Bd, with A at higher potential.","The difference is v2Bd, with B at higher potential.","The difference is vBd, with A at higher potential.","The difference is vBd, with B at higher potential.","Because there is no loop, there is no flux, so there is no potential difference."]'::jsonb, '(C) The charges within the bar are moving in a magnetic field, so they feel a magnetic force. Using the conventional-current description, positive charges feel an upward force, causing positive charge to accumulate at the top end of the bar (leaving negative charge on the bottom end of the bar). This charge continues to accumulate until the electric force created by the charge imbalance cancels the magnetic force, mathematically qE = qvB. The magnitude of the potential difference between points A and B is then |V | = |−\int E \cdot  dr| = |vBd|. The electric field points down (producing a force that opposes the magnetic force), and recalling that electric fields point from high to low potential, we see that point A is at the higher potential. Further information about motional EMF can be found in Example 15.6.'),
  ('ap-topic-physc-induction_q17', 'ap-topic-physc-induction', 17, false, 'B', 'Diagnostic Test – E&M', 'medium', 'Suppose that the electric potential in a region of space is a constant. What can you conclude about the magnitude of the electric field in this region?', '["It is a nonzero constant.","It is zero.","It is proportional to the distance from the origin.","It is given by","Not enough information is given. Questions 6–8 refer to a circular region of radius a with a uniform magnetic field pointing into the page that is increasing at a constant rate as shown. A circular loop of wire of radius r is centered on the middle of the region."]'::jsonb, '(B) The electric field is the negative derivative (with respect to the spatial coordinate) of the potential. Thus, with a constant potential the electric field must be zero.'),
  ('ap-topic-physc-induction_q18', 'ap-topic-physc-induction', 18, false, 'C', 'Diagnostic Test – E&M', 'medium', 'Which of the graphs plots the induced EMF in the circular loop of wire shown as a function of its radius r?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(C) The induced EMF depends on the change in the enclosed flux. Because the magnetic field is uniform, and changing at a constant rate, Therefore, the induced EMF depends only on the area of the loop through which magnetic field lines pass. For r < a, the area within the loop exposed to the magnetic field is simply the entire area of the loop, which is a quadratic function, A(r) = \pir2. For r > a, increasing r does not increase the area exposed to the magnetic field (because the magnetic field through the additional area is zero). Therefore, for r > a the induced EMF is constant. The only graph that is quadratic for small r and then constant is choice (C). Calculating the induced EMF due to a magnetic field via Faraday’s law is discussed in Chapter 15.'),
  ('ap-topic-physc-induction_q19', 'ap-topic-physc-induction', 19, false, 'A', 'Diagnostic Test – E&M', 'medium', 'Given that the resistance of the loop is proportional to the loop’s circumference, which of the graphs seen in question 6 shows the induced current as a function of the radius of the loop?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(A) The current is given by I = V/R. The resistance is proportional to the circumference of the loop, 2\pir. Therefore, for r < a, V is proportional to r2 (as discussed in question 6), and 1/R is proportional to 1/r, so the product I = V/R is proportional to r (and thus its graph is a line passing through the origin). For r > a, V is constant and 1/R is proportional to 1/r, so the product I = V/R is inversely proportional to r. The only graph that satisfies these conditions is choice (A).')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-physc-induction_q20', 'ap-topic-physc-induction', 20, false, 'A', 'Diagnostic Test – E&M', 'medium', 'A circular conducting loop of radius R and resistance r lies in the xy-plane in a uniform magnetic field B(t) = B0 (1 - alpha t) k. What is the induced current in the loop?', '["pi R^2 B0 alpha / r","2 pi R B0 alpha / r","pi R^2 B0 / (r alpha)","Zero","pi R^2 B0 (1 - alpha t) / r"]'::jsonb, 'The magnetic flux through the loop is Phi_B(t) = B(t) A = B0 (1 - alpha t) (pi R^2). The induced EMF is EMF = |-dPhi_B/dt| = pi R^2 B0 alpha. The induced current is I = EMF / r = pi R^2 B0 alpha / r.'),
  ('ap-topic-physc-inductors_q1', 'ap-topic-physc-inductors', 1, false, 'E', 'Ch16: Inductors', 'medium', 'Consider the two concentric solenoids shown in Figure 16.5, one of which is attached to a battery, a resistor, and a switch and the other of which is attached to a lightbulb. (No current passes directly between the two circuits.) When the switch is turned on, what is expected to happen? Figure 16.5', '["No current passes through the lightbulb.","The intensity of the lightbulb increases and quickly reaches its maximum, final intensity.","The lightbulb flickers on and off with a regular frequency and constant intensity.","The lightbulb flickers on and off with a regular frequency and decreasing intensity.","The lightbulb flashes on once, and then no current passes through it."]'::jsonb, '(E) The instant after the switch is turned on, the flux through the inner solenoid increases sharply. This changing flux induces a current in the outer solenoid, which briefly causes the lightbulb to flash on. Very soon, the current in the left circuit reaches its final value, the flux through the inner solenoid ceases changing, and the induced current through the lightbulb drops to zero and remains zero.'),
  ('ap-topic-physc-inductors_q2', 'ap-topic-physc-inductors', 2, false, 'A', 'Ch16: Inductors', 'medium', 'In an RL circuit with a battery of EMF V, resistor R, and inductor L, what is the current I(t) as a function of time after the switch is closed at t = 0?', '["I(t) = (V / R) * (1 - e^{-R t / L})","I(t) = (V / R) * e^{-R t / L}","I(t) = (V / R) * (1 - e^{-L t / R})","I(t) = (V / L) * t","I(t) is constant and equal to V / R"]'::jsonb, 'Applying Kirchhoff''s loop rule: V - I R - L (dI/dt) = 0. Solving this first-order linear differential equation with initial condition I(0) = 0 gives I(t) = (V / R) (1 - e^{-R t / L}).'),
  ('ap-topic-physc-inductors_q3', 'ap-topic-physc-inductors', 3, false, 'B', 'Ch16: Inductors', 'medium', 'An inductor with inductance L = 0.5 H carries a current that decreases uniformly from 4.0 A to 1.0 A in a time interval of 0.10 s. What is the magnitude of the self-induced EMF in the inductor?', '["7.5 V","15 V","25 V","0.15 V","1.5 V"]'::jsonb, 'The self-induced EMF is given by Faraday''s law for an inductor: EMF = -L (Delta I / Delta t). The magnitude is |EMF| = L * |Delta I| / Delta t = 0.5 H * (4.0 A - 1.0 A) / (0.10 s) = 0.5 * 3.0 / 0.10 = 15 V.'),
  ('ap-topic-physc-inductors_q4', 'ap-topic-physc-inductors', 4, false, 'B', 'Ch16: Inductors', 'medium', 'Consider the coaxial cable shown in Figure 16.12. At one end of the cable, the inner wire has been connected to the outer sheath so that current coming out of the page through the inner wire equals the current going into the page through the outer sheath. If this current I has a uniform current density, Figure 16.12 (a) Calculate the magnitude of the magnetic field in the region a < r < b. Figure 16.13 shows a lengthwise cross section of the coaxial cable. Figure 16.13 (b) If the current is increasing at a rate of dI/dt, what is the induced EMF through the area shown in the figure? (c) How does this EMF affect the change in current? (d) What is the inductance of a coaxial cable of length l?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(B) As the current exponentially approaches its final value, the change in current (which is proportional to the voltage) decreases exponentially, as discussed in the beginning of this chapter.'),
  ('ap-topic-physc-inductors_q5', 'ap-topic-physc-inductors', 5, false, 'E', 'Ch16: Inductors', 'medium', 'What is the period of the circuit shown in Figure 16.7? Figure 16.7', '["f / 2","f / \\sqrt{2}","f","\\sqrt{2}f","2f"]'::jsonb, '(E) In general, the angular frequency of an LC circuit is , so the period is . (For a review of period and angular frequency, see Chapter 8.) In this case, the equivalent capacitance is C/2 and the equivalent inductance is 2L (because the voltage jumps across the inductors add), so the product , and the period is .'),
  ('ap-topic-physc-inductors_q6', 'ap-topic-physc-inductors', 6, false, 'E', 'Ch16: Inductors', 'medium', '(a) What is the equivalent inductance of two inductors, L1 and L2, in series? (b) What is the equivalent inductance of two inductors, L1 and L2, in parallel? (Assume that the mutual inductance of the two inductors involved is negligible.)', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(E) In general, the angular frequency of an LC circuit is , so the period is . (For a review of period and angular frequency, see Chapter 8.) In this case, the equivalent capacitance is C/2 and the equivalent inductance is 2L (because the voltage jumps across the inductors add), so the product , and the period is .'),
  ('ap-topic-physc-inductors_q7', 'ap-topic-physc-inductors', 7, false, 'C', 'Ch16: Inductors', 'medium', 'An LC circuit oscillates with maximum charge Q0 on the capacitor. When the energy is shared equally between the electric field of the capacitor and the magnetic field of the inductor, what is the charge on the capacitor?', '["Q0 / 4","Q0 / 2","Q0 / sqrt(2)","Q0 / 3","Zero"]'::jsonb, 'Total energy is U_total = Q0^2 / (2C). When energy is shared equally, U_E = 1/2 U_total ==> q^2 / (2C) = 1/2 (Q0^2 / (2C)) ==> q^2 = Q0^2 / 2 ==> q = Q0 / sqrt(2).'),
  ('ap-topic-physc-inductors_q8', 'ap-topic-physc-inductors', 8, false, 'A', 'Ch16: Inductors', 'medium', 'Two concentric coplanar circular loops of wire have radii r1 and r2 with r1 << r2. What is the mutual inductance M between the two loops?', '["mu_0 pi r1^2 / (2 r2)","mu_0 pi r1 / (2 r2^2)","mu_0 r1 r2 / 2","2 pi mu_0 r1^2 / r2","mu_0 pi (r2^2 - r1^2) / 2"]'::jsonb, 'When current I flows through the outer loop of radius r2, it produces a nearly uniform magnetic field at the center: B = mu_0 I / (2 r2). The magnetic flux through the small inner loop of radius r1 is Phi_12 = B A1 = (mu_0 I / (2 r2)) * (pi r1^2). Mutual inductance is M = Phi_12 / I = mu_0 pi r1^2 / (2 r2).'),
  ('ap-topic-physc-inductors_q9', 'ap-topic-physc-inductors', 9, false, 'C', 'Ch16: Inductors', 'medium', 'Consider the circuit in Figure 16.9. The switch is closed at t = 0, when the capacitor is uncharged and no current is flowing through the inductor. What is the initial current that passes through the battery the instant after the switch is closed? Figure 16.9', '["I = 0","I = V/R1","I = V/R2","I = V/(R1 + R2)","I = V(R1 + R2)/R1R2"]'::jsonb, '(C) At t = 0, the capacitor acts like a short circuit and the inductor acts like an open circuit (opposing any sudden jump in the current). Therefore, zero current flows through the inductor, and a current equal to V/R2 flows through the capacitor and around the outer loop.'),
  ('ap-topic-physc-inductors_q10', 'ap-topic-physc-inductors', 10, false, 'A', 'Ch16: Inductors', 'medium', 'In an RL circuit with inductance L and resistance R, what is the magnetic energy stored in the inductor when the current reaches its steady-state value I_max = V / R?', '["1/2 L (V / R)^2","L (V / R)^2","1/2 L^2 V / R","1/2 R (V / L)^2","Zero"]'::jsonb, 'The magnetic energy stored in an inductor carrying current I is U_B = 1/2 L I^2. At steady state, I = V / R, so U_B = 1/2 L (V / R)^2.'),
  ('ap-topic-physc-inductors_q11', 'ap-topic-physc-inductors', 11, false, 'B', 'Ch16: Inductors', 'medium', 'What is the final current in the circuit shown in question 5?', '["I = 0","I = V/R1","I = V/R2","I = V/(R1 + R2)","I = V(R1 + R2)/R1R2"]'::jsonb, '(B) At equilibrium, the capacitor acts like an open circuit and the inductor acts like a closed circuit so that zero current flows through the capacitor and a current of I = V/R1 flows around the inner loop. One caveat is in order here, however: The rule that a capacitor acts like an open circuit at equilibrium was based on RC circuits, so we must consider whether it still applies here. Because the potential across the capacitor and the resistor R2 is always V, the inductor branch of the circuit actually has absolutely no impact on the current flowing through the capacitor, so any generalizations we made for RC circuits apply here. Similarly, the voltage across the inductor and the resistor R1 is always V, so the inductor acts independently of the capacitor. The only place where we actually see the loops in the circuit interacting is where the current is flowing through the battery, which is a sum of the currents flowing through each loop.'),
  ('ap-topic-physc-inductors_q12', 'ap-topic-physc-inductors', 12, false, 'B', 'Ch16: Inductors', 'medium', 'Consider the circuit shown in Figure 16.16. At time t = 0, the switch is closed. (Before the switch is closed, the capacitor is uncharged and there is no current flowing through the inductor.) Figure 16.16 (a) What is the current through the battery the instant after the switch is closed, at t = 0? (b) What is the current through the battery after the circuit has reached equilibrium, at t = \infty? After the circuit has reached equilibrium, the switch is opened (for simplicity we will designate a new frame of reference so that this occurs at t′ = 0). (c) What is the period of oscillation of the LC circuit formed? (d) What is the maximum current?', '["f / 2","f / \\sqrt{2}","f","\\sqrt{2}f","2f"]'::jsonb, '(B) At equilibrium, the capacitor acts like an open circuit and the inductor acts like a closed circuit so that zero current flows through the capacitor and a current of I = V/R1 flows around the inner loop. One caveat is in order here, however: The rule that a capacitor acts like an open circuit at equilibrium was based on RC circuits, so we must consider whether it still applies here. Because the potential across the capacitor and the resistor R2 is always V, the inductor branch of the circuit actually has absolutely no impact on the current flowing through the capacitor, so any generalizations we made for RC circuits apply here. Similarly, the voltage across the inductor and the resistor R1 is always V, so the inductor acts independently of the capacitor. The only place where we actually see the loops in the circuit interacting is where the current is flowing through the battery, which is a sum of the currents flowing through each loop.'),
  ('ap-topic-physc-inductors_q13', 'ap-topic-physc-inductors', 13, false, 'A', 'Ch16: Inductors', 'medium', 'All the capacitors in each of the networks shown in Figure 16.10 have a capacitance of C. Which statement is correct? Figure 16.10', '["When attached to a given battery, array A stores more energy.","Equal amounts of charge are required to charge each array to the same final voltage.","When attached to a fixed battery and resistor, array A has a lower time constant.","When attached to a fixed inductor, array A has a greater angular frequency.","When attached to a battery, all the capacitors in array A store the same amount of charge. Free-Response Questions"]'::jsonb, '(A) By applying the formulas for parallel and series capacitance, it is not hard to determine that networks A and B have equivalent capacitance of 2C and 0.5C, respectively. Choice (A): , so network A, which has a greater equivalent capacitance, indeed stores more energy. Choice (B): The amount of charge required to charge a network to a given voltage is Q = CV. Because the two networks have different equivalent capacitances, they require different amounts of charge, making this choice false. Choice (C): The formula for the time constant is \tau = RC. Therefore, network A, which has a larger equivalent capacitance, produces a circuit with a greater time constant. Choice (D): The angular frequency of an LC circuit is given by the formula . Because network A has a greater equivalent capacitance, it has a smaller angular frequency. Choice (E): The voltage across the central capacitor in network A is twice the voltage across the other capacitors, so the capacitors do not store the same amount of charge. Free-Response 1. This problem drills you on determining initial and final conditions of circuits containing inductors and capacitors. The challenge here is figuring out which rule or equation to apply; once you have figured out how to correctly approach each section, the math is very simple. Some of the most useful equations and generalizations are listed here. Capacitors: 1. Initially, capacitors act as short circuits. 2. At equilibrium, capacitors act as open circuits. Inductors: 1. The initial condition of an inductor can generally be figured out using the rule that the current through an inductor is a continuous function of time. 2. At equilibrium, inductors act like short circuits. Kirchhoff’s loop rule: Once you have the voltage across one component of the circuit, you can use a loop rule to figure out the voltage across other parts of the circuit. (a) Initially, the capacitor acts like a short circuit so that the current is I = V/R. At equilibrium when the capacitor is fully charged, it acts like an open circuit so that the current is zero. (b) Initially, the capacitor is uncharged so that its voltage is V = Q/C = 0. At equilibrium, the voltage across the resistor is zero (the current is zero, so V = IR = 0), so according to Kirchhoff’s loop rule, the voltage across the capacitor must be V (in the opposite polarity as the battery). (c) Initially, the inductor acts like an open circuit so that the current is zero (as required by the fact that the current through an inductor must be continuous). At equilibrium, the inductor acts like a closed circuit so that the current is I = V/R. (d) Initially, the voltage across the resistor is zero because the current is zero (according to Ohm’s law, V = IR = 0). Therefore, Kirchhoff’s loop rule requires the voltage across the inductor to equal V (in the polarity opposite that of the battery). At equilibrium, the change in current, dI/dt, is zero, so the voltage across the inductor is zero. (e) The presence of an inductor requires the current to be continuous in time. (If the current were discontinuous, dI/dt would be infinite, generating an infinite voltage across the inductor and an infinite current and violating conservation of energy.) Therefore, the initial current through the inductor is the same as the current through the inductor before the switch is flipped, I = V/R. Because this current is to the right, it generates a counterclockwise current in the circuit containing the inductor and capacitor. This initial state of the circuit is shown in Figure 16.17. Figure 16.17 (f) The initial voltage across the capacitor is V. [The capacitor was left fully charged from its previous state, as calculated in part (b).] Kirchhoff’s loop rule then requires the voltage across the inductor to have magnitude V with opposite polarity. 2. (a) This is a classic Ampere’s law problem with cylindrical symmetry. The enclosed current is simply I, so the magnetic field is equal to the field due to a wire (recall that the field doesn’t depend on the distribution of the current as long as it is cylindrically symmetric): (b) We can use a standard Faraday’s law application. Because the magnetic field varies, we must integrate to calculate the magnetic flux. To mirror the cylindrical symmetry of the magnetic field, we divide the area into differential areas that are thin rectangular strips running parallel to the axis of the cable with differential area: The differential flux through each differential area is Integrating, Applying Faraday’s law, (c) We can apply Lenz’s law directly: Increasing current causes an increase in inward flux through the loop, which induces a counterclockwise EMF, which decreases the current. Or we can apply Lenz’s law indirectly: Because the change in current causes the change in flux, in order to oppose the change in flux, the induced EMF must oppose the change in current. (d) The inductance is defined as 3. Our general approach is the same as when we calculated equivalent resistance or equivalent capacitance. The goal is to find values of voltage and dI/dt to plug into the definition of inductance, Leq = V/(dI/dt). We do this by assigning either a voltage (V) or a change in current (dI/dt), then calculating the other value, and finally finding the ratio. Whether we begin by assigning V or dI/dt is simply a matter of convenience. (Parallel elements share a common voltage, so it’s easier to start with the voltage V and calculate dI/dt; series elements share a common current, so it’s easier to start with dI/dt and calculate the voltage.) (a) Elements in series share a common current, so let’s begin by considering what will happen if the current through both inductors is changing at a rate dI/dt. Each inductor produces a voltage of L(dI/dt) such that the net voltage is Then, according to the definition of inductance, the net inductance is Therefore, the equivalent inductance of inductors in series is the sum of their individual inductances. This makes sense: Adding two coils in series is quite similar to increasing the length of a single coil, and both cause increases in the net inductance. (b) Elements in parallel share a common voltage, so let’s begin by considering the situation where two inductors in parallel have a voltage V across them. The change in current through each inductor is then The change in the total current throughout the inductor array, Inet = I1 + I2, is then Therefore, applying the definition of inductance, Therefore, the net inductance of inductors in parallel is smaller than the inductance of either of the inductors alone. This makes sense if we consider an inductor as an element that resists changes in current. When more inductors are added in parallel, each allows a certain change in current for a given voltage; thus, the net effect of adding more inductors is to produce a greater change in current for the same voltage. (This is similar to the way adding more resistors in parallel produces a greater current for the same voltage, such that the equivalent resistance is smaller than the resistance of any of the individual resistors.) 4. (a) First apply Biot-Savart’s law (note that the magnitude of r is constant and that it is always perpendicular to dl). (b) Because r << R, we can assume that the field is approximately uniform within the smaller loop and equal to the value at the center, calculated above in part (a). Therefore, the flux (choosing A to point into the page) is (c) Using Faraday’s law, 5. (a) Just after the switch is closed, all of the current will pass through resistor R1 because the inductor prevents the current in its branch from jumping immediately to a nonzero value. Thus, the potential difference across R1 will be V, the EMF of the battery. Point a is connected to the positive terminal of the battery, so it will be at a higher potential than b. (b) Because there is no current through the branch with the inductor, the potential difference across resistor R2 will be zero. The potential difference across the inductor must then be V. The inductor is in parallel with resistor R1, and the potential at c will be higher than at d. (c) When the switch is closed for a long time and the currents reach steady-state values, the potential difference across the inductor will go to zero. When the switch is opened, the current through resistor R2 cannot immediately change; it will briefly maintain its value of flowing to the right. This current then flows through resistor R1 to the left. The potential difference across resistor R1 will be with b now at higher potential because the current flows to the left through resistor R1. (d) The potential difference between points c and d is given by with point d at higher potential because the current flows counterclockwise in the loop containing the two resistors and is decreasing in time. So the inductor acts like a battery that is trying to keep current flowing counterclockwise, meaning that d is at higher potential compared to c. 6. (a) The instant after the circuit is closed, the inductor acts like an open circuit and the capacitor acts like a short circuit (so that the capacitor begins to charge and the capacitor and the inductor together have zero net resistance). The current is then I = V/R = 10 V/50 Ω = 0.2 A. (b) At equilibrium, the inductor acts like a short circuit and the capacitor acts like an open circuit, so the capacitor and inductor together have zero net resistance and the current through the circuit is I = V/R = 10 V/50 Ω = 0.2 A. (c) The period is given by the equation (d) Since the current through an inductor must remain continuous, the initial current through the inductor is 0.2 A. The instant the switch is opened, the capacitor is still uncharged. Therefore, the instant the LC circuit begins to oscillate, energy is stored within the inductor alone. We calculate the maximum current using conservation of energy: Thus the maximum current equals the initial current, 0.2 A.'),
  ('ap-topic-physc-inductors_q14', 'ap-topic-physc-inductors', 14, false, 'C', 'Diagnostic Test – E&M', 'medium', 'Two metal spheres with radii r1 and r2 carrying positive charges Q1 and Q2 are separated by a very large distance. A thin wire connects the two spheres. Under what condition will positive charge flow from sphere 1 to sphere 2?', '["Q1 > Q2","r1 > r2","Q1 / r1 > Q2 / r2","Q1 r1 > Q2 r2","Q1 / r1^2 > Q2 / r2^2"]'::jsonb, 'Positive charge flows from higher to lower electric potential: V = k Q / r. Charge flows from 1 to 2 if V1 > V2 ==> Q1 / r1 > Q2 / r2.'),
  ('ap-topic-physc-inductors_q15', 'ap-topic-physc-inductors', 15, false, 'C', 'Diagnostic Test – E&M', 'medium', 'A charged particle is launched into a region of uniform magnetic field. Given that the particle’s initial velocity has components parallel and perpendicular to the magnetic field, describe the particle’s path qualitatively.', '["a straight line","a circle","a helical (corkscrew) path","a parabolic path","none of the above"]'::jsonb, '(C) See the discussion of the motion of particles within magnetic fields in Chapter 14.'),
  ('ap-topic-physc-inductors_q16', 'ap-topic-physc-inductors', 16, false, 'B', 'Diagnostic Test – E&M', 'medium', 'A point charge +Q is located at a fixed distance from a sphere. Compare the magnitude of the attractive force on the sphere if the sphere is (1) metal with net charge −Q, (2) metal with no net charge, (3) an insulator with net charge −Q, or (4) an insulator with no net charge.', '["charged metal = charged insulator > uncharged metal = uncharged insulator","charged metal > charged insulator > uncharged metal > uncharged insulator","charged insulator > charged metal > uncharged insulator > uncharged metal","charged insulator > charged metal > uncharged metal = uncharged insulator","charged insulator = charged metal > uncharged metal > uncharged insulator"]'::jsonb, '(B) This is a question about electrostatic induction. When a positive point charge is placed near a metal sphere (charged or uncharged), it attracts mobile electrons in the metal, causing the metal to become polarized such that more negative charge is on the side closer to the positive point charge and more positive charge is on the side farther away from the positive point charge. Because this charge redistribution results in moving negative charge closer to the positive point charge and moving positive charge farther away from the positive point charge, it increases the attractive force between the metal sphere and the positive point charge. Therefore, compared to an insulating sphere with the same net charge, a metal sphere always experiences a greater attractive force (such that charged metal > charged insulator and uncharged metal > uncharged insulator). Because this inductive effect is small compared to the effect of actually putting net charge −Q on the sphere, charged insulator > uncharged metal.'),
  ('ap-topic-physc-inductors_q17', 'ap-topic-physc-inductors', 17, false, 'C', 'Diagnostic Test – E&M', 'medium', 'A bar moves to the right through a magnetic field as shown (the magnetic field points into the page). What is the potential difference between points A and B after equilibrium is established in the bar?', '["The difference is v2Bd, with A at higher potential.","The difference is v2Bd, with B at higher potential.","The difference is vBd, with A at higher potential.","The difference is vBd, with B at higher potential.","Because there is no loop, there is no flux, so there is no potential difference."]'::jsonb, '(C) The charges within the bar are moving in a magnetic field, so they feel a magnetic force. Using the conventional-current description, positive charges feel an upward force, causing positive charge to accumulate at the top end of the bar (leaving negative charge on the bottom end of the bar). This charge continues to accumulate until the electric force created by the charge imbalance cancels the magnetic force, mathematically qE = qvB. The magnitude of the potential difference between points A and B is then |V | = |−\int E \cdot  dr| = |vBd|. The electric field points down (producing a force that opposes the magnetic force), and recalling that electric fields point from high to low potential, we see that point A is at the higher potential. Further information about motional EMF can be found in Example 15.6.'),
  ('ap-topic-physc-inductors_q18', 'ap-topic-physc-inductors', 18, false, 'B', 'Diagnostic Test – E&M', 'medium', 'Suppose that the electric potential in a region of space is a constant. What can you conclude about the magnitude of the electric field in this region?', '["It is a nonzero constant.","It is zero.","It is proportional to the distance from the origin.","It is given by","Not enough information is given. Questions 6–8 refer to a circular region of radius a with a uniform magnetic field pointing into the page that is increasing at a constant rate as shown. A circular loop of wire of radius r is centered on the middle of the region."]'::jsonb, '(B) The electric field is the negative derivative (with respect to the spatial coordinate) of the potential. Thus, with a constant potential the electric field must be zero.'),
  ('ap-topic-physc-inductors_q19', 'ap-topic-physc-inductors', 19, false, 'C', 'Diagnostic Test – E&M', 'medium', 'Which of the graphs plots the induced EMF in the circular loop of wire shown as a function of its radius r?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(C) The induced EMF depends on the change in the enclosed flux. Because the magnetic field is uniform, and changing at a constant rate, Therefore, the induced EMF depends only on the area of the loop through which magnetic field lines pass. For r < a, the area within the loop exposed to the magnetic field is simply the entire area of the loop, which is a quadratic function, A(r) = \pir2. For r > a, increasing r does not increase the area exposed to the magnetic field (because the magnetic field through the additional area is zero). Therefore, for r > a the induced EMF is constant. The only graph that is quadratic for small r and then constant is choice (C). Calculating the induced EMF due to a magnetic field via Faraday’s law is discussed in Chapter 15.'),
  ('ap-topic-physc-inductors_q20', 'ap-topic-physc-inductors', 20, false, 'A', 'Diagnostic Test – E&M', 'medium', 'Given that the resistance of the loop is proportional to the loop’s circumference, which of the graphs seen in question 6 shows the induced current as a function of the radius of the loop?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(A) The current is given by I = V/R. The resistance is proportional to the circumference of the loop, 2\pir. Therefore, for r < a, V is proportional to r2 (as discussed in question 6), and 1/R is proportional to 1/r, so the product I = V/R is proportional to r (and thus its graph is a line passing through the origin). For r > a, V is constant and 1/R is proportional to 1/r, so the product I = V/R is inversely proportional to r. The only graph that satisfies these conditions is choice (A).'),
  ('ap-mock-physc-em-full-1_q1', 'ap-mock-physc-em-full-1', 1, false, 'E', 'Practice Test 1 – E&M', 'medium', 'Consider the circuit shown, which contains two identical lightbulbs connected to a battery. The top bulb’s intensity will', '["decrease slightly if either of the two switches is closed.","decrease slightly if S1 is closed but not if S2 is closed.","decrease slightly if S2 is closed but not if S1 is closed.","remain unchanged if S2 is closed but go out completely if S1 is closed.","remain unchanged if S1 is closed but go out completely if S2 is closed."]'::jsonb, '(E) If S1 is closed, a parallel circuit with an equivalent resistance of R/2 will be created. Thus the current drawn from the battery will double and half that current will go through the top bulb, yielding the same current that flowed before the switch S1 was closed. If S2 is closed, creating a path of zero resistance, no current will pass through either bulb.'),
  ('ap-mock-physc-em-full-1_q2', 'ap-mock-physc-em-full-1', 2, false, 'D', 'Practice Test 1 – E&M', 'medium', 'What is the voltage V in the circuit shown in the figure?', '["1 V","2 V","4 V","6 V","8 V"]'::jsonb, '(D) A Kirchhoff’s loop equation for the right loop [clockwise: 8 V − (1 A)(4 Ω) − (I)(2 Ω) = 0] reveals that the current i moving from point A to point B must be 2.0 A (upward). A node equation at point A then shows the current through the left 2 Ω resistor must be 1.0 A flowing to the right. Finally, a Kirchhoff’s loop equation for the left loop [clockwise: V − (1 A)(2 Ω) − (2 A)(2 Ω) = 0] allows us to calculate the voltage of the battery as 6 V.'),
  ('ap-mock-physc-em-full-1_q3', 'ap-mock-physc-em-full-1', 3, false, 'D', 'Practice Test 1 – E&M', 'medium', 'A battery of EMF V0 is connected in series with a resistor R and an uncharged capacitor C at t = 0. What is the current in the circuit at the instant t = R C?', '["(V0 / R) * (1 - 1/e)","Zero","(V0 / R) * (1 - 1/e^2)","(V0 / R) * (1/e)","V0 / R"]'::jsonb, 'The current in an RC series charging circuit is I(t) = (V0 / R) e^{-t / (RC)}. At t = RC, the current is I(RC) = (V0 / R) e^{-1} = (V0 / R) * (1/e).'),
  ('ap-mock-physc-em-full-1_q4', 'ap-mock-physc-em-full-1', 4, false, 'A', 'Practice Test 1 – E&M', 'medium', 'A sphere of radius R contains a negative charge with a charge density given by the function \rho = −cr4, where r equals the distance from the center of the sphere. Where does the electric field have the smallest magnitude?', '["at the center of the sphere","at some point between the center of the sphere and the surface of the sphere","at the surface of the sphere","outside the sphere","The electric field is constant in space."]'::jsonb, '(A) At the center of the sphere, as a result of symmetry, the electric field is zero. At every other point in space, the electric field is nonzero.'),
  ('ap-mock-physc-em-full-1_q5', 'ap-mock-physc-em-full-1', 5, false, 'E', 'Practice Test 1 – E&M', 'medium', 'Referring to the charge distribution described in question 4, where is the potential smallest in magnitude?', '["at the center of the sphere","at some point between the center of the sphere and the surface of the sphere","at the surface of the sphere","outside the sphere","at infinity"]'::jsonb, '(E) The electric field at all points in space is directed toward the center of the sphere because the sphere is negatively charged. Electric fields always point in the direction of decreasing potential. With the conventional choice of zero potential at infinity, the potential will be negative everywhere else and thus smallest in magnitude at infinity.'),
  ('ap-mock-physc-em-full-1_q6', 'ap-mock-physc-em-full-1', 6, false, 'A', 'Practice Test 1 – E&M', 'medium', 'A loop is moved out of a magnetic field at constant velocity as shown. Which of the following statements about the induced current in the loop and the applied force on the loop is correct? (The magnetic field points into the page.)', '["The current is clockwise, and the applied force is to the right.","The current is clockwise, and the applied force is to the left.","The current is counterclockwise, and the applied force is to the right.","The current is counterclockwise, and the applied force is to the left.","The current is counterclockwise, and the applied force is into the page."]'::jsonb, '(A) To oppose the decrease in flux going into the page, the current flows clockwise. What magnetic force does this produce on the loop? The magnetic forces on the top and bottom of the loop, which point up and down, respectively, cancel each other out. The force on the left side of the loop points to the left, and there is zero force on the right side of the loop (because the magnetic field is zero in this region), so the net magnetic force points to the left. Because the applied force must cancel out this magnetic force in order for the loop to move at constant velocity, it then points to the right.'),
  ('ap-mock-physc-em-full-1_q7', 'ap-mock-physc-em-full-1', 7, false, 'C', 'Practice Test 1 – E&M', 'medium', 'Which of the following statements about electric field lines and equipotential curves is false?', '["Equipotential lines are always perpendicular to electric field lines.","The electric field magnitude is greater in regions where the density of electric field lines is greater.","Electric field lines begin and end only at the locations of negative and positive charges, respectively.","The work required to move a charge along an equipotential line is zero.","Electric field lines never penetrate metals."]'::jsonb, '(C) Electric field lines begin and end at locations of positive and negative charges, respectively (not the other way around).'),
  ('ap-mock-physc-em-full-1_q8', 'ap-mock-physc-em-full-1', 8, false, 'A', 'Practice Test 1 – E&M', 'medium', 'In an LC circuit composed of an inductor with inductance L and a capacitor of capacitance C, if the current through the capacitor is changing at a rate of dI/dt, what is the magnitude of the charge on the capacitor?', '["CL(dI/dt)","(C/L)(dI/dt)","(CL2/2)(dI/dt)","(L/C)(dI/dt)","Information is not given."]'::jsonb, '(A) Because the capacitor and the inductor are in series, they share a common current. Therefore, if the current through the capacitor is changing with a rate of dI/dt, the current through the inductor is changing at exactly the same rate. The voltage across the inductor is then V = L(dI/dt), which is equal to the magnitude of the voltage across the capacitor (by Kirchhoff’s loop rule). The charge on the capacitor is then given by the equation'),
  ('ap-mock-physc-em-full-1_q9', 'ap-mock-physc-em-full-1', 9, false, 'B', 'Practice Test 1 – E&M', 'medium', 'A uniform cylindrical resistor has resistance R. Assume that the current density in this resistor is uniform. What is the resistance of a similar cylindrical resistor composed of the same material with half the radius and half the length?', '["4R","2R","R","R/2","R/4"]'::jsonb, '(B) Recall the formula for the resistance of a uniform cylindrical resistor: R = \rhol/A, where l is the length of the resistor and A is its cross- sectional area. The second resistor has half the length of the first resistor, which alone would cause its resistance to decrease by a factor of 2 compared to R. The second resistor also has one-fourth the area of the first resistor (because A = \pir2, increasing r by a factor of 2 causes A to increase by a factor of 4), which alone would cause its resistance to increase by a factor of 4 compared to R. The combined results of these changes are an increase by a factor of 2.'),
  ('ap-mock-physc-em-full-1_q10', 'ap-mock-physc-em-full-1', 10, false, 'B', 'Practice Test 1 – E&M', 'medium', 'A parallel plate capacitor of capacitance C has charge +Q on one plate and −Q on the other. It is discharged through a resistor of resistance R. The maximum value of the current flowing through the resistor is given by', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(B) The potential difference across the fully charged capacitor is V = Q/C. The capacitor acts like a discharging battery whose maximum voltage is Q/C. Hence, the maximum current through the resistor is choice (B), using Ohm’s law. Note that using dimensional analysis also yields the correct answer.'),
  ('ap-mock-physc-em-full-1_q11', 'ap-mock-physc-em-full-1', 11, false, 'E', 'Practice Test 1 – E&M', 'medium', 'The electric field lines due to a point charge suspended within a spherical conducting shell are shown. These field lines are consistent with which of the following charge distributions? (Qp is the charge of the point charge, and Qs is the net charge on the conducting shell.)', '["Qp < 0, Qs < 0, |Qp| > |Qs|","Qp < 0, Qs > 0, |Qp| > |Qs|","Qp < 0, Qs > 0, |Qp| < |Qs|","Qp > 0, Qs < 0, |Qp| > |Qs|","Qp > 0, Qs < 0, |Qp| < |Qs|"]'::jsonb, '(E) Inside the shell, the field lines point away from the point charge. Because field lines begin only at positive charges, this reveals that the point charge is positive, eliminating choices (A), (B), and (C). Outside the spherical shell, the field lines point toward the shell. Applying Gauss’s law to any spherical surface outside the shell reveals that the net charge of the point charge and the shell must be negative. This can occur only if the net charge on the cylindrical shell is negative and greater in magnitude than the positive charge of the point charge, indicating that the correct answer is (E). Another way to rule out choice (D) is as follows. For the electric field within the metal to be zero, a net charge of −Qp must be distributed on the inside of the spherical shell. Conservation of charge then requires the charge on the outside of the spherical shell to be Qs + Qp. Because electric field lines terminate only at negative charges, the charge on the outside of the spherical shell must be negative. Because Qp > 0 and (Qs + Qp) < 0, this requires Qs to be negative and greater in magnitude than Qp.'),
  ('ap-mock-physc-em-full-1_q12', 'ap-mock-physc-em-full-1', 12, false, 'B', 'Practice Test 1 – E&M', 'medium', 'Two long parallel wires carry equal currents I in the same direction (+z direction out of the page). Wire 1 is at x = -d and Wire 2 is at x = +d. What is the net magnetic field at the origin (x = 0)?', '["mu_0 I / (pi d) in the +y direction","Zero","mu_0 I / (pi d) in the -y direction","2 mu_0 I / (pi d) in the +x direction","mu_0 I / (2 pi d) in the +z direction"]'::jsonb, 'By the right-hand rule, Wire 1 at x = -d produces a magnetic field at the origin pointing in the +y direction with magnitude B1 = mu_0 I / (2 pi d). Wire 2 at x = +d produces a magnetic field at the origin pointing in the -y direction with magnitude B2 = mu_0 I / (2 pi d). The two fields have equal magnitude and opposite directions, so they cancel out completely: B_net = 0.'),
  ('ap-mock-physc-em-full-1_q13', 'ap-mock-physc-em-full-1', 13, false, 'D', 'Practice Test 1 – E&M', 'medium', 'Referring to the situation introduced in question 12, if the value of I is increased by a factor of 2 (doubling the current carried by each wire), how will the magnitude of the force on the top wire change?', '["It will stay the same.","It will increase by a factor of 2.","It will increase by a factor of 3.","It will increase by a factor of 4.","It will increase by a factor of 6."]'::jsonb, '(D) Recall that the force exerted by one wire on another parallel wire has a magnitude given by the formula force/length = \mu0I1I2/2\pir. Doubling I will double all the currents, so it will increase each of the forces by a factor of 4. Because each of the pairwise forces increases by a factor of 4, the net force (which is the sum of these forces) will also increase by a factor of 4.'),
  ('ap-mock-physc-em-full-1_q14', 'ap-mock-physc-em-full-1', 14, false, 'B', 'Practice Test 1 – E&M', 'medium', 'A positive charge +Q is fixed at the origin. As a charge of +q moves along the x-axis from (d, 0) to (2d, 0), how much work does the electric force do on the +q charge?', '["Work = qQ/4\\pi\\epsilon0d","Work = qQ/8\\pi\\epsilon0d","Work = −qQ/4\\pi\\epsilon0d","Work = −qQ/8\\pi\\epsilon0d","Work = −Q/4\\pi\\epsilon0d"]'::jsonb, '(B) Choice (E) is incorrect as revealed by dimensional analysis. Work has the same units as energy, which has units of qV. However, comparison with the formula V = Q/4\pi\epsilon0r indicates that choice (E) has the units of voltage, not of qV. Because both the electrostatic force and the displacement point in the +x-direction, the dot product and the integral of work must be positive, ruling out choices (C) and (D). To actually solve the problem, note that the change in electric potential energy is Because of conservation of energy, it is equal to the net external work (because the kinetic energy is constant) so that work = qQ/8\pi\epsilon0d.'),
  ('ap-mock-physc-em-full-1_q15', 'ap-mock-physc-em-full-1', 15, false, 'B', 'Practice Test 1 – E&M', 'medium', 'Which of the following statements is true about a discharging capacitor?', '["The energy stored and the charge on the capacitor both increase with time.","The energy stored and the charge on the capacitor both decrease with time.","The energy stored decreases while the charge increases with time.","The energy stored remains the same while the charge decreases with time.","The energy stored increases while the charge decreases with time."]'::jsonb, '(B) A discharging capacitor certainly loses charge as it discharges. The decrease in charge leads to a decrease in the electric field between the plates; thus, the energy stored decreases as well.'),
  ('ap-mock-physc-em-full-1_q16', 'ap-mock-physc-em-full-1', 16, false, 'D', 'Practice Test 1 – E&M', 'medium', 'To calculate the resistance of an 80 W speaker, you measure the voltage across the speaker to be 20 V. Which of the following is the speaker’s resistance?', '["0.2 Ω","0.25 Ω","4 Ω","5 Ω","1,600 Ω"]'::jsonb, '(D) The most useful form of the formula for power here is P = V2/R. Rearranging this yields R = V2/P = (20 V)2/80 W = 5 Ω.'),
  ('ap-mock-physc-em-full-1_q17', 'ap-mock-physc-em-full-1', 17, false, 'E', 'Practice Test 1 – E&M', 'medium', 'A battery of voltage V is connected across two capacitors C1 and C2 connected in series. What is the total electrostatic energy stored in the series combination?', '["1/2 (C1 + C2) V^2","1/2 (C1 C2) V^2","1/2 (C1 C2 / (C1 + C2)^2) V^2","1/4 (C1 + C2) V^2","1/2 (C1 C2 / (C1 + C2)) V^2"]'::jsonb, 'For two capacitors in series, the equivalent capacitance is C_eq = C1 C2 / (C1 + C2). The total stored energy across voltage V is U = 1/2 C_eq V^2 = 1/2 [C1 C2 / (C1 + C2)] V^2.'),
  ('ap-mock-physc-em-full-1_q18', 'ap-mock-physc-em-full-1', 18, false, 'C', 'Practice Test 1 – E&M', 'medium', 'Consider a spherical shell with a uniform surface charge density \sigma. If the radius of the shell is doubled while holding the charge density constant, what effect does this have on the magnitude of the electric field just outside the shell?', '["The electric field decreases by a factor of 4.","The electric field decreases by a factor of 2.","The electric field remains the same.","The electric field increases by a factor of 2.","The electric field increases by a factor of 4."]'::jsonb, '(C) Gauss’s law applied to a gaussian surface just outside the sphere indicates that \PhiE = EA = Qenc/\epsilon0. Doubling the radius increases the area of the shell, A = 4\piR2 (and thus the charge of the shell), by a factor of 4, but it also increases the area of the gaussian sphere by a factor of 4. These effects cancel, and the electric field remains the same. Note: Very close to the surface of the sphere, the field is mainly due to the nearby charge on the surface of the sphere. Also, when very close to the sphere, the curvature can be ignored (just as we can ignore the curvature of Earth) so that the sphere can be approximated as a plane and the electric field approximated as E = \sigma/2\epsilon0. Therefore, it is not surprising that changing the radius doesn’t affect the field near the sphere if the charge density is held constant.'),
  ('ap-mock-physc-em-full-1_q19', 'ap-mock-physc-em-full-1', 19, false, 'B', 'Practice Test 1 – E&M', 'medium', 'A very long rod containing a charge density of −\lambda coulombs/meter is moving along the +x-axis in the +x-direction with velocity v. The length of the rod is along the x-axis. What is the magnitude of the current, and in what direction is the conventional current flowing?', '["I = v\\lambda along the +x-direction.","I = v\\lambda along the −x-direction.","I = v\\lambda2 along the +x-direction.","I = v\\lambda2 along the −x-direction.","I = v/\\lambda along the +x-direction."]'::jsonb, '(B) Carrying negative charge in the +x-direction causes the same net charge transport as carrying positive charge in the −x-direction. Therefore, the direction of the conventional current produced is in the −x-direction, which immediately eliminates choices (A), (C), and (E). What is the magnitude of the current? The magnitude of current is defined as the amount of charge that passes a certain point per time. In a time increment dt, a length of rod dx = vdt passes a certain point that carries a charge dQ = \lambdadx = \lambdav dt. The current is then I = dQ/dt = \lambdav dt/dt = \lambdav.'),
  ('ap-mock-physc-em-full-1_q20', 'ap-mock-physc-em-full-1', 20, false, 'D', 'Practice Test 1 – E&M', 'medium', 'An infinite line of uniform negative linear charge density -lambda lies along the z-axis. Which of the following correctly describes the electric field produced by this line charge at any point in the xy-plane at distance r from the z-axis?', '["Radially outward with magnitude lambda / (2 pi epsilon_0 r)","Parallel to the z-axis with magnitude lambda / (2 pi epsilon_0 r)","Circumferential around the z-axis","Radially inward toward the z-axis with magnitude lambda / (2 pi epsilon_0 r)","Zero"]'::jsonb, 'By Gauss''s law for a cylindrical Gaussian surface of radius r and length L, the electric field is purely radial: oint E * dA = E (2 pi r L) = |lambda| L / epsilon_0 ==> E(r) = lambda / (2 pi epsilon_0 r). Because the charge is negative, the field vectors point radially inward toward the line of charge.'),
  ('ap-mock-physc-em-full-1_q21', 'ap-mock-physc-em-full-1', 21, false, 'B', 'Practice Test 1 – E&M', 'medium', 'Consider the charge distribution shown. The potential is zero at points in which of the following regions (not including \pm \infty)?', '["region I only","region II only","region III only","regions I and II","regions I and III"]'::jsonb, '(B) Recall that the potential due to point charges is V = ∑(Qi/4\pi\epsilon0r). For the net potential at a point to be zero, the magnitude of the positive potential due to +Q must equal the magnitude of the negative potential due to −Q. This requires that the point be equidistant from the two point charges, which occurs only at one place: exactly between the two charges in region II. Note: In two-dimensional or three-dimensional space, the region where the potential is zero is a line or a plane, respectively.'),
  ('ap-mock-physc-em-full-1_q22', 'ap-mock-physc-em-full-1', 22, false, 'D', 'Practice Test 1 – E&M', 'medium', 'The current through an inductor L is given as a function of time by I(t) = I0 (1 - t / T) for 0 <= t <= T. What is the magnitude of the induced EMF across the inductor during this time?', '["Zero","L I0 / T^2","1/2 L I0 / T","L I0 / T","L I0 T"]'::jsonb, 'The induced EMF across an inductor is EMF = -L (dI/dt). Differentiating I(t): dI/dt = d/dt [I0 (1 - t/T)] = -I0 / T. Therefore, the magnitude of the EMF is |EMF| = L * |-I0 / T| = L I0 / T.'),
  ('ap-mock-physc-em-full-1_q23', 'ap-mock-physc-em-full-1', 23, false, 'C', 'Practice Test 1 – E&M', 'medium', 'Which of the following is most closely related to the brightness of a lightbulb? (Assume that all the energy dissipated in a lightbulb is emitted as light energy rather than thermal energy.)', '["the current running through the lightbulb","the voltage across the lightbulb","the power dissipated by the lightbulb","the resistance of the lightbulb","the current density of the lightbulb"]'::jsonb, '(C) If all the energy dissipated in the lightbulb were emitted as light energy, the brightness of the lightbulb would directly reflect the amount of energy dissipated in the lightbulb per time, which is the power of the lightbulb.'),
  ('ap-mock-physc-em-full-1_q24', 'ap-mock-physc-em-full-1', 24, false, 'E', 'Practice Test 1 – E&M', 'medium', 'In a parallel-plate capacitor with electric field E directed from plate A (at x = 0) to plate B (at x = d), the electric potential is set to zero at plate B (V(d) = 0). What is the potential V(x) at position x between the plates (0 <= x <= d)?', '["V(x) = E x","V(x) = -E x","V(x) = E d","V(x) = E (d + x)","V(x) = E (d - x)"]'::jsonb, 'The electric field is related to potential by E_x = -dV/dx. Since E is uniform in the +x direction, dV/dx = -E ==> V(x) = -E x + C. With boundary condition V(d) = 0: -E d + C = 0 ==> C = E d. Thus, V(x) = E (d - x). At plate A (x = 0), V(0) = E d, and at plate B (x = d), V(d) = 0.'),
  ('ap-mock-physc-em-full-1_q25', 'ap-mock-physc-em-full-1', 25, false, 'D', 'Practice Test 1 – E&M', 'medium', 'The electric field inside a sphere with uniform positive charge density has the following property:', '["It is zero.","It is a nonzero constant.","It decreases as a function of radial distance from the center of the sphere.","It increases as a function of radial distance from the center of the sphere.","It is infinite."]'::jsonb, '(D) Gauss’s law tells us that the electric field is proportional to the enclosed charge. Drawing a gaussian sphere inside the sphere of charge shows us that the field will increase with increasing radial distance.'),
  ('ap-mock-physc-em-full-1_q26', 'ap-mock-physc-em-full-1', 26, false, 'E', 'Practice Test 1 – E&M', 'medium', 'A charged particle moving in the presence of both an electric and a magnetic field moves in a closed path (i.e., a path that begins and ends at the same point). If the energy of the particle at the end of the closed path is 2.0 J greater than its energy when it began the path, which of the following statements is correct?', '["The magnetic field performed 2.0 J of work on the particle.","The magnetic field performed −2.0 J of work on the particle.","The electric field is conservative.","The electric field is due to static charges.","none of the above"]'::jsonb, '(E) The magnetic force is always perpendicular to the particle’s displacement, so the magnetic force never can do any work on any particle. Therefore, choices (A) and (B) are incorrect. Because the magnetic field performs no work on the particle, the electric field must perform work on the particle. However, the fact that the electric field performs net work on the particle as it moves in a closed path indicates that the field is not conservative, ruling out choice (C). Because the electric fields due to static charges are always conservative, this eliminates choice (D). The solution therefore is (E).'),
  ('ap-mock-physc-em-full-1_q27', 'ap-mock-physc-em-full-1', 27, false, 'A', 'Practice Test 1 – E&M', 'medium', 'Consider an electric dipole within a constant electric field as shown. (The dipole consists of two charges of equal magnitude and opposite sign rigidly connected to each other.) Describe the net force and net torque on the dipole.', '["The net force is zero, and the net torque is clockwise.","The net force is zero, and the net torque is counterclockwise.","The net force is to the right, and the net torque is clockwise.","The net force is to the right, and the net torque is counterclockwise.","The net force is to the left, and the net torque is counterclockwise."]'::jsonb, '(A) The force on +Q is equal in magnitude and opposite in direction to the force on −Q, so the net force is zero. However, both forces produce a clockwise torque about the center of the dipole, so the net torque is clockwise.'),
  ('ap-mock-physc-em-full-1_q28', 'ap-mock-physc-em-full-1', 28, false, 'D', 'Practice Test 1 – E&M', 'medium', 'A circular loop of wire of radius r lies in a plane perpendicular to a uniform magnetic field that is changing at a rate of a teslas/second. Which of the following statements correctly describes the power dissipated in the loop as a function of the loop’s radius? (Recall that a wire’s resistance is proportional to its length.)', '["The power is independent of r.","The power is proportional to r.","The power is proportional to r2.","The power is proportional to r3.","The power is inversely proportional to r."]'::jsonb, '(D) The EMF is proportional to the area of the loop, so it is proportional to r2 (mathematically, V = c1r2). The resistance is proportional to the length of the loop, so it is proportional to r (mathematically, R = c2r). Because we know the resistance and the voltage, the most useful formula for power to use here is'),
  ('ap-mock-physc-em-full-1_q29', 'ap-mock-physc-em-full-1', 29, false, 'D', 'Practice Test 1 – E&M', 'medium', 'If a potential difference of 3 V across a wire that is 2 m long and 0.5 mm in radius yields a current of 10 A, what is the resistivity of the wire?', '["3.8 Ω ⋅ m","1.2 Ω ⋅ m","2.4 \\times  10−4 Ω ⋅ m","1.2 \\times  10−7 Ω ⋅ m","1.2 \\times  10−18 Ω ⋅ m"]'::jsonb, '(D) Resistivity is given by for a wire of radius r. We have also used Ohm’s law to write the resistance R in terms of the voltage and current.')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-mock-physc-em-full-1_q30', 'ap-mock-physc-em-full-1', 30, false, 'B', 'Practice Test 1 – E&M', 'medium', 'Consider the inductor shown in the figure below. If the current I is decreasing in time, what can be said about the potential difference between points A and B?', '["Point A is at higher potential.","Point B is at higher potential.","The potential difference is zero.","Potential difference cannot be defined for an inductor.","Not enough information is given."]'::jsonb, '(B) The potential difference across an inductor is V_B - V_A = -L(dI/dt). Because the current I is decreasing in time, dI/dt < 0, which means V_B - V_A > 0. Therefore, Point B is at higher potential.'),
  ('ap-mock-physc-em-full-1_q31', 'ap-mock-physc-em-full-1', 31, false, 'E', 'Practice Test 1 – E&M', 'medium', 'A dielectric material is inserted between the plates of an isolated charged capacitor. Which of the following is true?', '["The potential energy of the capacitor increases.","The charge of the capacitor decreases.","The capacitance of the capacitor decreases.","The voltage of the capacitor increases.","none of the above"]'::jsonb, '(E) Choice (C): When a dielectric is added to a capacitor, the capacitance increases by a factor of kD. Choice (B): Because the capacitor is isolated, there is nowhere for the charge to go and so it remains constant. Choice (D): Based on the equation Q = CV, the charge remains constant and the capacitance increases, so the voltage decreases. Choice (A): The potential energy can be expressed as Q2/2C. Because the charge remains constant while the capacitance increases, the potential energy decreases. (Note: As the dielectric is added, charges of opposite polarity are induced on the two surfaces of the dielectric adjacent to the capacitor plates. These induced charges attract the charge on the capacitor, drawing the dielectric toward it. As the dielectric is pulled into the capacitor, it can perform positive work on another object as it decreases the capacitor’s potential energy.) Therefore, by elimination the answer is (E).'),
  ('ap-mock-physc-em-full-1_q32', 'ap-mock-physc-em-full-1', 32, false, 'A', 'Practice Test 1 – E&M', 'medium', 'Consider charging a battery with an internal resistance of R and an EMF of V0. (Charging a battery involves moving charge from the negative terminal to the positive terminal.) Which of the following is capable of charging a battery? I. a potential difference greater than V0 II. a potential difference equal to V0 III. a potential difference smaller than V0', '["I only","II only","III only","I and II only","I, II, and III"]'::jsonb, '(A) Consider the schematic in the figure, which shows a battery being charged. In order for the battery to be charged, the current must flow in the direction indicated. This requires the potential difference from A to B to be V0 + IR (with B at higher potential). Thus, to make current flow in the correct direction, a potential greater than V0 is required.'),
  ('ap-mock-physc-em-full-1_q33', 'ap-mock-physc-em-full-1', 33, false, 'C', 'Practice Test 1 – E&M', 'medium', 'An electron is traveling through a region of space with electric and magnetic fields as shown (the velocity is in the plane of the E and B vectors). The force exerted on the electron has components in what directions?', '["the +y-direction and the +z-direction","the −y-direction and the −z-direction","the −y-direction and the +z-direction","the +y-direction and the −z-direction","none of the above"]'::jsonb, '(C) Because an electron has a negative charge, the electric force points antiparallel to the electric field, in the −y-direction. Similarly, because the particle is negative, the magnetic force points antiparallel to the direction indicated by the right-hand rule, in the +z-direction.'),
  ('ap-mock-physc-em-full-1_q34', 'ap-mock-physc-em-full-1', 34, false, 'B', 'Practice Test 1 – E&M', 'medium', 'Consider an infinite line of positive charge that has a varying charge density. Very close to the line of charge, in which direction does the electric field approximately point?', '["directly toward the line of charge","directly away from the line of charge","parallel to the line of charge, pointing in the direction of increasing charge density","parallel to the line of charge, pointing in the direction of decreasing charge density","The field is zero."]'::jsonb, '(B) Very close to the line of charge, the variation in the charge density with position is not apparent because the field is dominated by the charge located very close to the field point. The distance from the line of charge to the field point is small compared to the rate at which the charge density is changing. This effectively constant charge density produces a field pointing away from the line of charge (as does any uniform line of positive charge). This is analogous to the way the electric field is perpendicular to a surface charge distribution very close to an infinite surface even if the surface charge density is not constant.'),
  ('ap-mock-physc-em-full-1_q35', 'ap-mock-physc-em-full-1', 35, false, 'D', 'Practice Test 1 – E&M', 'medium', 'Consider a wire loop moving through a region of magnetic field pointing into the page as shown. Which is a graph of the magnetic flux through the loop as a function of position (designating inward flux as negative)?', '["Linear positive flux increase, plateau, linear return to zero","Abrupt step function jumping to negative flux and returning to zero","Positive-valued upward trapezoidal flux profile","Trapezoidal pulse with negative flux (steady decrease, plateau, steady return to zero)","Sinusoidal alternating flux oscillation"]'::jsonb, '(D) As the loop enters the field, the flux into the page (negative flux) steadily increases in magnitude, remains constant while the loop is completely within the magnetic field, and then steadily approaches zero as the loop exits the field. The discontinuities and plateaus featured in choices (A), (B), and (E) are similar to what the current or the EMF would look like as a function of position. Choice (C) is the same as choice (D) except that the sign is incorrect. (Flux out of the page is designated as positive, so the loop experiences negative flux.) Free-Response Electricity and Magnetism I (a) Using the relationship between voltage and electric field for a parallel plate capacitor, V = Ed, the minimum distance is (b) By the same equation, VBD = EBDd. (c) See the figure. The capacitor-charging stage is exactly the same as in an RC circuit, except that when the breakdown voltage is reached, the capacitor rapidly discharges (as if it were shorted through a small resistance) and then repeats the charging step. (d) Recall the equation for the charge on a charging capacitor: where Qf is the charge on the capacitor when it is fully charged. Using the relationship Q = CV, we can convert this to an equation expressing voltage as a function of time: The time T between discharges is given by the duration of a single charging step (if we assume the discharge is essentially instantaneous), which is the amount of time it takes for the charging capacitor to reach the breakdown voltage: Solving for T yields (e) The energy stored in the capacitor just before dielectric breakdown is given by the equation . (f) Because the battery is disconnected, the charge density on the plates is fixed (and thus, the charge density remains fixed). Since the electric field inside the capacitor depends only on the charge density of the plates, it is not affected and no dielectric breakdown occurs. Electricity and Magnetism II (a) Because the charge density is not uniform, we must integrate. Mirroring the spherical symmetry of the charge distribution, we use as our differential volume spherical shells: (b) (i) We apply Gauss’s law, noting that the enclosed charge is negative, which causes the electric field to point inward (antiparallel to the directed area vector) and yields a negative flux (note that E signifies the magnitude of the electric field) Units check: The constant c has units of C/m, so the units of the numerator in the field expression are coulombs. We then recognize the usual dimensions of electric field: charge/\epsilon0(distance2). (b) (ii) At r < a, we have to integrate to obtain the enclosed charge: Again applying Gauss’s law, Units check: If we multiply the numerator and denominator by length, we recover the usual form of the electric field, charge/\epsilon0(distance2), as in (b)(i). (b) (iii) Both expressions for r > a and r < a agree that the magnitude of the field at r = a is Recall that because there are no infinite charge densities (no point charges or surface charge densities), the electric field must be continuous, so the expressions for field in different regions must match up at the region’s border. (c) Taking the line integral of V = − \int  E ⋅ dr along the x-axis from x = \infty to x = a yields (because the electric field points to the left, Ex = −ca/\epsilon0x2). Evaluating the integral, Sign check: Based on the equation V = \int  dQ⁄4\pi \epsilon0 r, because the charge is negative, the potential should be negative. (d) Because the electric field outside the sphere is identical to that produced by a point charge located at the center of the sphere, the potential is also equal to that produced by a point charge: Using the expression for Q calculated in part (a), Electricity and Magnetism III (a) Electric potential energy in the capacitor is converted to kinetic energy: (b) B1 and B3 point into the page; B2 points out of the page (remember that the charge is negative!). (c) The magnetic force provides the centripetal force. (Here the sin \theta term in the cross product is 1.) (d) Given that the particle manages to make it through the first region, its mass must satisfy the equation above. As a particle traverses the semicircles, its speed does not change. (The magnetic field does no work because it is perpendicular to the displacement.) Therefore, equations with the same form can be written for the other two semicircles, with the results Because the speed of the particle is constant throughout its trajectory, we can combine these equations: Therefore, r2 = r1(B1/B2) and r3 = r1(B1/B3). (e) From part (c), you find that . Thus, to obtain a linear relationship, you should plot V versus r2 or vice versa. (f) Plot V versus r2 (see the figure below). Fitting to a straight line gives the following slope: You expect the slope of the line to be given by . With B1 = 0.01 T, you find . The accepted value is .'),
  ('ap-mock-physc-em-full-1_q36', 'ap-mock-physc-em-full-1', 36, false, 'C', 'Ch10: Electrostatics', 'medium', 'Two experiments are performed using a pair of solid metal spheres connected by a switch, as shown in Figure 10.9. Both spheres are grounded before each experiment so that they initially have no charge. Figure 10.9 Experiment I: A positively charged rod is brought near sphere A while the switch is closed, the switch is opened, and the rod is then removed. Experiment II: A positively charged rod is touched to sphere A while the switch is closed, the switch is opened, and the rod is then removed. Which of the following describes the charge on the spheres after the two experiments?', '["After experiment I both spheres have no charge; after experiment II both spheres are positively charged.","After experiment I sphere A is negatively charged and sphere B is positively charged; after experiment II sphere A is positively charged and sphere B is negatively charged.","After experiment I sphere A is negatively charged and sphere B is positively charged; after experiment II both spheres are positively charged.","After both experiments, both spheres are positively charged.","After both experiments, sphere A is positively charged and sphere B is negatively charged."]'::jsonb, '(C) Experiment I involves electrostatic induction. When the positively charged rod is brought near sphere A, it attracts electrons from both spheres, causing sphere A to have a slight negative charge and sphere B to have a slight positive charge. Because the switch is opened before the rod is removed, the charge never has a chance to redistribute itself, so after the experiment is over, sphere A is left negatively charged and sphere B is left positively charged. Experiment II involves conduction. The rod removes a large negative charge from the two-sphere system, leaving both spheres with a large net positive charge. Although induction effects cause the positive charge on sphere B to be slightly larger than the charge on sphere A, in general conduction imparts a much greater charge than induction, so the net charge of both spheres after the switch is opened is positive. Note that choice (D) can be immediately eliminated by conservation of charge. Because the rod never touches the sphere system in experiment I, the amount of charge on the two spheres together must remain constant; it is impossible for both to have a positive or a negative charge at any point during or after experiment I.'),
  ('ap-mock-physc-em-full-1_q37', 'ap-mock-physc-em-full-1', 37, false, 'C', 'Ch10: Electrostatics', 'medium', 'Two identical conducting spheres A and B are mounted on insulating stands. Initially, sphere A carries positive charge +Q and sphere B is uncharged. The two spheres are brought into contact, allowed to reach equilibrium, and then separated. What is the final charge on sphere A?', '["Zero","+Q / 4","+Q / 2","+Q","+2Q"]'::jsonb, 'When two identical conducting spheres touch, charge redistributes equally between them to equalize their electric potentials. The total initial charge is Q_total = +Q + 0 = +Q. By symmetry, the charge divides equally: Q_A = Q_B = Q_total / 2 = +Q/2.'),
  ('ap-mock-physc-em-full-1_q38', 'ap-mock-physc-em-full-1', 38, false, 'B', 'Ch10: Electrostatics', 'medium', 'Which of the three distributions in Figure 10.10 has a point or points where the potential is zero (excluding \pm \infty but assuming that the potential equals zero at these latter points)? Figure 10.10', '["distribution I only","distribution II only","distribution III only","distributions I and II, only","distributions I, II, and III"]'::jsonb, '(B) For any distribution of two point charges, the charges must have opposite signs for there to be a location(s) where the potential is zero. (Otherwise, both charges will never be able to cancel out each other’s contribution.) In distribution II, the potential is zero in between the two charges, much closer to the −q charge because this charge has a smaller magnitude (which can be compensated for by having a greater 1/r term in its potential contribution), and also to the left of the −q charge. This behavior is illustrated in Figure 10.17, which shows the potential due to point charges. Figure 10.17'),
  ('ap-mock-physc-em-full-1_q39', 'ap-mock-physc-em-full-1', 39, false, 'B', 'Ch10: Electrostatics', 'medium', 'Two point charges +4q and -q are fixed on the x-axis at x = 0 and x = d, respectively. At what finite position on the x-axis is the net electric field equal to zero?', '["x = d / 2","x = 2d","x = -d","x = 3d","There is no point on the x-axis where the field is zero"]'::jsonb, 'For the net field to be zero, the electric fields of the two opposite charges must point in opposite directions and have equal magnitudes. Between x = 0 and x = d, both fields point in the +x direction (no cancellation). To the left of x = 0 (x < 0), the larger charge +4q is always closer than -q, so its field always dominates. To the right of -q (x > d), the fields point in opposite directions. Setting magnitudes equal: k(4q)/x^2 = k(q)/(x - d)^2 ==> 2/x = 1/(x - d) ==> 2x - 2d = x ==> x = 2d.'),
  ('ap-mock-physc-em-full-1_q40', 'ap-mock-physc-em-full-1', 40, false, 'B', 'Ch10: Electrostatics', 'medium', 'Consider the potential vs position function shown in Figure 10.11 (the potential asymptotically approaches zero as x goes to + infinity or − infinity). At which of the points—A, B, C, D, or E—does a positive charge feel the greatest force in the +x-direction? Figure 10.11', '["point A","point B","point C","point D","point E"]'::jsonb, '(B) The electric field is the negative slope of the potential curve, Ex = −dV/dx, so the place where the force to the right (the positive force) is maximized is the place where the slope of the potential curve has a negative value with the greatest magnitude, at point B.'),
  ('ap-mock-physc-em-full-1_q41', 'ap-mock-physc-em-full-1', 41, false, 'B', 'Ch10: Electrostatics', 'medium', 'The electric potential V in a region of space depends only on the x-coordinate and is given by V(x) = 4x^2 - 3x + 2, where V is in volts and x is in meters. What is the x-component of the electric field at x = 2.0 m?', '["+13 N/C","-13 N/C","+16 N/C","-8 N/C","+8 N/C"]'::jsonb, 'The relationship between electric field and electric potential in one dimension is E_x = -dV/dx. Differentiating V(x): dV/dx = d/dx (4x^2 - 3x + 2) = 8x - 3. At x = 2.0 m: dV/dx = 8(2.0) - 3 = 13 V/m. Therefore, E_x = -13 V/m (or -13 N/C).'),
  ('ap-mock-physc-em-full-1_q42', 'ap-mock-physc-em-full-1', 42, false, 'C', 'Ch10: Electrostatics', 'medium', 'In the five charge distributions shown in Figure 10.12, all have identical square geometry and all charges have identical magnitudes q. In how many of the charge distributions is the electric field zero at the center of the square? Figure 10.12', '["one","two","three","four","five"]'::jsonb, '(C) Because of symmetry, distributions (b), (d), and (e) all have an electric field of zero at the center of the square. Said another way: If we pair charges along the diagonals of the square, we will see that in distributions (b), (d), and (e), each pair consists of two charges of the same sign and hence produce a net field of zero at the center of the square.'),
  ('ap-mock-physc-em-full-1_q43', 'ap-mock-physc-em-full-1', 43, false, 'C', 'Ch10: Electrostatics', 'medium', 'Four point charges of equal magnitude Q are placed at the four corners of a square of side length a. Two opposite corners have positive charges +Q, and the other two opposite corners have negative charges -Q. What is the net electric potential V at the center of the square (taking V = 0 at infinity)?', '["4 k Q / a","2 sqrt(2) k Q / a","Zero","-2 sqrt(2) k Q / a","sqrt(2) k Q / a"]'::jsonb, 'Electric potential is a scalar quantity given by V = sum (k q_i / r_i). The center of the square is equidistant from all four corners, at distance r = (a sqrt(2)) / 2 = a / sqrt(2). The total potential at the center is V = k/r * (+Q + Q - Q - Q) = k/r * (0) = 0.'),
  ('ap-mock-physc-em-full-1_q44', 'ap-mock-physc-em-full-1', 44, false, 'B', 'Ch10: Electrostatics', 'medium', 'The axis of the cone in Figure 10.13 lies on the y-axis. The cone has a uniform charge density. Based on symmetry considerations alone, in what direction(s) can the electric field at the origin point? (The origin lies within the cone along its axis of symmetry.) Figure 10.13', '["the x-axis","the y-axis","the z-axis","anywhere along the xy-plane","anywhere along the yz-plane"]'::jsonb, '(B) Imagine describing to a friend what direction the electric field points; the only description you could give would be “toward the tip of the cone” or “away from the tip of the cone” (i.e., along the y-axis).'),
  ('ap-mock-physc-em-full-1_q45', 'ap-mock-physc-em-full-1', 45, false, 'B', 'Ch10: Electrostatics', 'medium', 'A thin non-conducting rod of length L carries a uniformly distributed positive charge Q. Which of the following correctly expresses the electric potential V at a point P located on the perpendicular bisector of the rod at a distance y from its center (taking V = 0 at infinity)?', '["V is proportional to 1 / y^2","V = (k Q / L) * ln( (sqrt((L/2)^2 + y^2) + L/2) / (sqrt((L/2)^2 + y^2) - L/2) )","V = k Q / y","V is zero due to symmetry","V = k Q / (y^2 + (L/2)^2)"]'::jsonb, 'Let the rod lie along the x-axis from x = -L/2 to x = +L/2 with linear charge density lambda = Q/L. An infinitesimal element dx at position x carries charge dq = lambda dx and is at distance r = sqrt(x^2 + y^2) from point (0, y). The potential is V = int k dq / r = (k Q / L) int_{-L/2}^{L/2} dx / sqrt(x^2 + y^2) = (k Q / L) * [ln(x + sqrt(x^2 + y^2))]_{-L/2}^{L/2} = (k Q / L) * ln( (sqrt((L/2)^2 + y^2) + L/2) / (sqrt((L/2)^2 + y^2) - L/2) ).'),
  ('ap-mock-physc-em-full-2_q1', 'ap-mock-physc-em-full-2', 1, false, 'D', 'Practice Test 2 – E&M', 'medium', 'In an RC discharging circuit, a capacitor C with initial voltage V0 discharges through a resistor R when a switch is closed at t = 0. Which of the following functions represents the voltage V(t) across the capacitor as a function of time?', '["V(t) = V0 (1 - e^{-t / (RC)})","V(t) = V0 t / (RC)","V(t) = V0 (1 - t / (RC))","V(t) = V0 e^{-t / (RC)}","V(t) = V0 e^{-t / (2RC)}"]'::jsonb, 'During capacitor discharge through resistance R, Kirchhoff''s loop rule gives -R (dq/dt) - q/C = 0 ==> dq/dt = -q / (RC). The solution is q(t) = Q0 e^{-t / (RC)}. Dividing by capacitance C yields the capacitor voltage V(t) = q(t)/C = V0 e^{-t / (RC)}, which decays exponentially to zero.'),
  ('ap-mock-physc-em-full-2_q2', 'ap-mock-physc-em-full-2', 2, false, 'D', 'Practice Test 2 – E&M', 'medium', 'A loop of wire of radius r and resistance R is exposed to a magnetic field pointing into the page that steadily increases from zero to magnitude B in time t, as shown. Describe the induced current.', '["\\pirB/t, clockwise","\\pirB/t, counterclockwise","\\pir2B/Rt, clockwise","\\pir2B/Rt, counterclockwise","\\pir2B/t, counterclockwise"]'::jsonb, '(D) First, to oppose the increase in inward flux, the induced current must flow counterclockwise, producing an outward flux. What is the magnitude of the current? The induced EMF is Because the magnetic field increases linearly, its slope dB/dt is simply The resistance is R, so according to Ohm’s law the current is I = V/R = AB/Rt. Finally, to express the result in terms of the variables in the problem, A = \pir2, so I = \pir2 B/Rt.'),
  ('ap-mock-physc-em-full-2_q3', 'ap-mock-physc-em-full-2', 3, false, 'B', 'Practice Test 2 – E&M', 'medium', 'The potential in a region of space is given by the formula V = ar, where r is a radial coordinate and a is a positive constant. Which of the following statements is true of this region?', '["The electric field has magnitude a and points away from the origin of the coordinates .","The electric field has a magnitude a and points toward the origin .","The electric field has a magnitude r2/2a and points away from the origin .","The electric field has a magnitude r2/2a and points toward the origin .","The electric force is nonconservative."]'::jsonb, '(B) The electric field equals the negative derivative of the potential along any line, and this holds for a line passing through the radius. Mathematically, Er = −dV/dr = −a. Even without recalling this equation in its entirety, one could arrive at the correct answer by combining the information that (1) the magnitude of the electric field is related to the derivative of the potential, and (2) the electric field always points in the direction of decreasing potential. Choice (E) is false. Any field that has an associated potential function is conservative. (That is, any field for which a potential energy function can be defined is a conservative field.)'),
  ('ap-mock-physc-em-full-2_q4', 'ap-mock-physc-em-full-2', 4, false, 'D', 'Practice Test 2 – E&M', 'medium', 'A capacitor of capacitance 25 \muF is charged to 300 V and then connected in series with an inductor of inductance 10 mH. The maximum current flowing through the circuit will be', '["7,500 A","500 A","300 A","15 A","2.5 A"]'::jsonb, '(D) The loop rule for an LC circuit is . This looks just like a harmonic oscillator with . The current is given by and the maximum current obeys Imax = \omegaQmax. The maximum charge is the initial charge of the capacitor, .'),
  ('ap-mock-physc-em-full-2_q5', 'ap-mock-physc-em-full-2', 5, false, 'A', 'Practice Test 2 – E&M', 'medium', 'If it requires an input of E joules to move a charge Q from point A to point B at constant velocity, which of the following is true?', '["VB − VA = E/Q","VB − VA = −E/Q","VB − VA = QE","VB − VA = −QE","VB − VA = Q/E"]'::jsonb, '(A) Potential is equal to the potential energy per unit charge, so only choices (A) and (B) have the correct units. To figure out the signs, consider the case where Q and E are positive. If positive energy is required to move the charge from point A to point B, point B must be at higher potential energy (uphill), so Q(VB − VA) must be positive. Because E is positive, only the equation VB − VA = E/Q has signs that are consistent with this situation.'),
  ('ap-mock-physc-em-full-2_q6', 'ap-mock-physc-em-full-2', 6, false, 'D', 'Practice Test 2 – E&M', 'medium', 'A parallel-plate vacuum capacitor with capacitance C0 is connected to a battery of voltage V. While still connected to the battery, a dielectric slab with dielectric constant kappa = 3 is inserted to fill the space between the plates. What is the ratio of the new stored energy to the initial stored energy (U_new / U_initial)?', '["1/9","1/3","1","3","9"]'::jsonb, 'Because the capacitor remains connected to the battery, the voltage V across the plates stays constant. The capacitance increases to C_new = kappa C0 = 3 C0. The energy stored in a capacitor at fixed voltage is U = 1/2 C V^2. Therefore, U_new / U_initial = (1/2 (3 C0) V^2) / (1/2 C0 V^2) = 3.'),
  ('ap-mock-physc-em-full-2_q7', 'ap-mock-physc-em-full-2', 7, false, 'E', 'Practice Test 2 – E&M', 'medium', 'A battery with EMF of V and an internal resistance of rint is connected to a heating loop with resistance R. What is the correct expression for the rate at which energy is converted to heat by the heating loop?', '["V2/R","V2rint/(rint + R)2","V/(rint + R)","V2R2/(rint + R)2","none of the above"]'::jsonb, '(E) The current through the circuit is The power dissipated through the heating element is then Because this is not equivalent to any of the given choices, the answer is choice (E).'),
  ('ap-mock-physc-em-full-2_q8', 'ap-mock-physc-em-full-2', 8, false, 'D', 'Practice Test 2 – E&M', 'medium', 'A parallel plate capacitor connected to a battery contains a plastic dielectric material between the plates of the capacitor. Removing the dielectric has what effect on the electric field between the plates and the charge on the plates?', '["Electric field and charge both decrease.","Electric field and charge both increase.","Electric field increases and the charge remains the same.","Electric field remains the same and the charge decreases.","none of the above"]'::jsonb, '(D) The equation always holds, so V = Ed is valid even in the case of a dielectric. Therefore, because the capacitor is always connected to the battery and the plate separation distance is unchanged, V and d are fixed and so E must remain the same. What effect does this have on the plate charge? The key equation here is Q = CV. The capacitance decreases in the absence of the dielectric. The voltage is held fixed (because the capacitor is attached to the battery), so the charge on the plates must decrease. How is it that the electric field can remain constant while the charge on the plates decreases? In the presence of the dielectric, the charge on the plates is partially screened by the induced charge on the surface of the dielectric. Once the dielectric is removed, the charge on the plates no longer needs to cancel this induced charge, so it decreases.'),
  ('ap-mock-physc-em-full-2_q9', 'ap-mock-physc-em-full-2', 9, false, 'D', 'Practice Test 2 – E&M', 'medium', 'An electron (charge -e, mass m) is released from rest at distance r1 from a fixed proton (charge +e). What is the kinetic energy of the electron when it has accelerated to a distance r2 from the proton (where r2 < r1)?', '["k e^2 * (1/r1 - 1/r2)","Zero","k e^2 / (2 r2)","k e^2 * (1/r2 - 1/r1)","1/2 m (k e^2 / r2)^2"]'::jsonb, 'Mechanical energy is conserved: K_initial + U_initial = K_final + U_final. The electron starts from rest, so K_initial = 0. The electrostatic potential energy is U(r) = -k e^2 / r. Therefore, 0 - k e^2 / r1 = K_final - k e^2 / r2 ==> K_final = k e^2 (1/r2 - 1/r1). Because r2 < r1, 1/r2 > 1/r1, so the kinetic energy is positive.'),
  ('ap-mock-physc-em-full-2_q10', 'ap-mock-physc-em-full-2', 10, false, 'C', 'Practice Test 2 – E&M', 'medium', 'The magnetic field created by the two wires shown at point A in the figure is B0 (pointing out of the page), and the two wires carry identical currents in the same direction. Which of the following is true?', '["Both wires carry a current of 4\\pid/3\\mu0 toward the top of the page.","Both wires carry a current of 4\\pid/3\\mu0 toward the bottom of the page.","Both wires carry a current of 4\\pidB0/\\mu0 toward the top of the page.","Both wires carry a current of 4\\pidB0/\\mu0 toward the bottom of the page.","It is impossible for the wires to produce a magnetic field pointing perpendicular to the page."]'::jsonb, '(C) A little experimentation with the right-hand rule shows that for points in between two wires carrying current in the same direction, the two wires produce magnetic fields in opposite directions. The wire closer to the point produces a larger magnetic field, so the net magnetic field points in the direction determined by this wire. In this case, because the magnetic field points out of the page, the current through the wire closest to point A (the right wire) must move toward the top of the page. The magnitude of the magnetic field due to a current-carrying wire is B = \mu0I/2\pir. Because the two wires produce fields in opposite directions, in this case the net magnetic field has magnitude Solving this equation for the current yields I = 4\pidB0/\mu0, so the correct answer is choice (C).'),
  ('ap-mock-physc-em-full-2_q11', 'ap-mock-physc-em-full-2', 11, false, 'D', 'Practice Test 2 – E&M', 'medium', 'Two insulating spheres of equal radii are oppositely charged with uniform charge densities of equal magnitude, as shown in the top half of the figure. The spheres are placed far apart from each other and can be considered completely isolated from each other. What is the effect of exchanging the top halves of these distributions with one another, as shown in the bottom half of the figure?', '["The potential increases at point A and decreases at point B.","The electric field magnitude increases at point A and decreases at point B.","The potential increases at both points A and B.","The electric field magnitude increases at both points A and B.","After the exchange, positive work is required to move a positive charge from point A to point B."]'::jsonb, '(D) Recall that potential is given by the integral . Therefore, moving negative charge closer to point A and positive charge farther away from point A decreases the potential at point A. The opposite occurs at point B, causing the potential to increase at point B. Therefore, choices (A) and (C) are false. Because of symmetry, a sphere of uniform charge density produces a zero net field at its center. Therefore, the electric field at points A and B is initially zero. Exchanging the tops of the spheres leads to nonzero electric fields at points A and B (pointing up at point A and down at point B). Therefore, (B) is false, while (D) is true. As a result of the symmetry of the situation, points A and B have the same potential. Therefore, zero work is required to move any charge from point A to point B, making choice (E) false.'),
  ('ap-mock-physc-em-full-2_q12', 'ap-mock-physc-em-full-2', 12, false, 'B', 'Practice Test 2 – E&M', 'medium', 'A loop of wire is pushed with constant velocity through a region of uniform magnetic field as shown. (The field points out of the page.) As the loop enters and exits the magnetic field, only one of the vertical segments of wire is within the magnetic field. What is the direction of the induced current within this vertical segment?', '["upward when both entering and exiting the magnetic field","downward when both entering and exiting the magnetic field","upward when entering the magnetic field and downward when exiting the magnetic field","downward when entering the magnetic field and upward when exiting the magnetic field","zero, because the segment of wire is perpendicular to the magnetic field"]'::jsonb, '(B) While entering the magnetic field, the induced current flows clockwise, moving downward through the right segment of the loop that is exposed to the magnetic field. While leaving the magnetic field, the induced current flows counterclockwise, moving downward through the left segment of the loop that is exposed to the magnetic field.'),
  ('ap-mock-physc-em-full-2_q13', 'ap-mock-physc-em-full-2', 13, false, 'D', 'Practice Test 2 – E&M', 'medium', 'What is the force on a positive charge +Q located on a 10 V equipotential line?', '["10 Q in magnitude, pointing parallel to the line","10 Q in magnitude, pointing perpendicular to the line in the direction of decreasing potential","10 Q in magnitude, pointing perpendicular to the line in the direction of increasing potential","of unknown magnitude, pointing perpendicular to the line in the direction of decreasing potential","of unknown magnitude, pointing perpendicular to the line in the direction of increasing potential"]'::jsonb, '(D) The force on the charge is proportional to the electric field according to the equation F = qE. The electric field is the negative derivative of the potential, but a single value of potential alone does not indicate anything about the electric field or the electric force. However, we can still determine the direction of the force. Electric fields are always perpendicular to equipotential curves, pointing in the direction of decreasing potential. Because the charge is positive, the force is parallel to the electric field.'),
  ('ap-mock-physc-em-full-2_q14', 'ap-mock-physc-em-full-2', 14, false, 'D', 'Practice Test 2 – E&M', 'medium', 'The capacitor shown consists of two concentric metallic cylindrical shells. Assuming that the radius of the inner cylinder, r, is much greater than the plate separation distance, d, what is the approximate capacitance of the capacitor?', '["C = \\epsilon0\\pir2/d","C = \\epsilon0\\pirl/d","C = \\epsilon0\\pidl/r","C = 2\\epsilon0\\pirl/d","C = \\epsilon0d/2\\pirl"]'::jsonb, '(D) Because the plate separation d is very small compared to the radius of the cylinder, it is reasonable to approximate the capacitor as a parallel plate capacitor with plate separation d and plate area 2\pirl. (This makes sense: Because d << r, the electric field is relatively constant between the plates and is perpendicular to the plates.) Therefore, the approximate capacitance is Even without making this observation, a few choices can be eliminated. Compared to the formula C = \epsilon0A/d, choice (E) has incorrect units, so it can be eliminated. Choice (A) does not include the length of the capacitor. However, we know from the simpler case of a parallel plate capacitor that the dimension of the plates is relevant to the value of the capacitance, so we can safely eliminate choice (A).'),
  ('ap-mock-physc-em-full-2_q15', 'ap-mock-physc-em-full-2', 15, false, 'D', 'Practice Test 2 – E&M', 'medium', 'A sphere has a uniform charge density distributed throughout its interior. What effect does doubling the radius of the sphere (while maintaining the same charge density) have on the electric field at a point outside the enlarged sphere?', '["The field remains the same.","The field increases by a factor of 2.","The field increases by a factor of 4.","The field increases by a factor of 8.","The field increases by a factor of 16."]'::jsonb, '(D) Imagine a spherical gaussian surface passing through any point outside the enlarged sphere. Doubling the radius of the sphere increases the enclosed charge by a factor of 8 (because the volume of a sphere is proportional to r3 and the charge is proportional to the volume). Thus, by Gauss’s law, the flux through the gaussian surface (whose surface area is fixed) increases by a factor of 8, and thus so does the electric field.'),
  ('ap-mock-physc-em-full-2_q16', 'ap-mock-physc-em-full-2', 16, false, 'A', 'Practice Test 2 – E&M', 'medium', 'A charged particle moves in a planar, circular orbit as a result of the presence of a uniform magnetic field perpendicular to the plane of its motion. Holding all other variables (such as the magnetic field, the particle’s velocity, and the particle’s charge) constant, which graph shows the relationship between the particle’s mass and the radius of its path?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(A) The magnetic force provides the centripetal force: mv2/r = qvB. Rearranging this equation to solve for r in terms of m yields r = (v/qB)m. Therefore, the graph is linear, passing through the origin.'),
  ('ap-mock-physc-em-full-2_q17', 'ap-mock-physc-em-full-2', 17, false, 'A', 'Practice Test 2 – E&M', 'medium', 'A thin uniformly charged rod with negative linear charge density -lambda lies along the y-axis from y = -a to y = +a. What is the direction of the electric field produced by the rod at a point P on the positive x-axis at (x, 0)?', '["Directly toward the origin (in the -x direction)","Directly away from the origin (in the +x direction)","In the +y direction","In the -y direction","The electric field is zero"]'::jsonb, 'Consider symmetric elements of charge dq = -lambda dy at +y and -y on the rod. Because the charge is negative, the electric field vectors dE point toward the charge elements. By symmetry, their y-components cancel out, while their x-components add constructively pointing along the -x direction (toward the origin). Thus the net electric field points directly toward the origin in the -x direction.'),
  ('ap-mock-physc-em-full-2_q18', 'ap-mock-physc-em-full-2', 18, false, 'D', 'Practice Test 2 – E&M', 'medium', 'Consider a circuit consisting of the following elements in a single loop: a battery, a resistor, a switch, and a fourth unknown element E. A spark is most likely to occur at the switch if', '["E is a capacitor and the switch is being closed for the first time.","E is a capacitor and the switch is being opened after the circuit has reached equilibrium.","E is an inductor and the switch is being closed for the first time.","E is an inductor and the switch is being opened after the circuit has reached equilibrium.","E is a battery arranged in series with the other battery in the circuit."]'::jsonb, '(D) Recall that the current flowing through inductors is generally continuous because a discontinuous current would cause the time derivative of the current to be infinite and thus produce an infinite voltage. How is this theory applicable to the current problem? In choice (D), when the switch is opened, an abrupt change in the current occurs that produces a very large induced EMF, causing a spark to instantaneously connect the recently opened terminals of the switch. [In choice (C), the current is zero before and immediately after closing the switch, so there is no discontinuity and no spark.]'),
  ('ap-mock-physc-em-full-2_q19', 'ap-mock-physc-em-full-2', 19, false, 'D', 'Practice Test 2 – E&M', 'medium', 'The two charge distributions shown each contain a net charge +Q uniformly distributed along an arc of a circle with radius r. In distribution A this charge is spread along an arc twice the length of the arc in distribution B. Which of the following comparisons of the potential V and the magnitude E of the electric field at point A and point B are true?', '["VA > VB and EA > EB","VA > VB and EA < EB","VA = VB and EA > EB","VA = VB and EA < EB","VA < VB and EA > EB"]'::jsonb, '(D) All the charge in both distributions is at a fixed distance r from the points of interest. Therefore, the potential at both point A and point B is V = Q/4\pi\epsilon0r and these potientials are equal. The electric field sums as vectors rather than scalars, so it is more complicated. In both cases, the net electric field points in the +x- direction because of symmetry about the x-axis. However, in distribution B, because the charge is concentrated closer to the horizontal axis, there is less cancellation of the differential electric field vectors compared to case A. (For further explanation, see Chapter 10.)'),
  ('ap-mock-physc-em-full-2_q20', 'ap-mock-physc-em-full-2', 20, false, 'D', 'Practice Test 2 – E&M', 'medium', 'Two cylindrical resistors are arranged in series and connected to a complicated circuit, as shown. Both resistors have the same resistivity, and the second resistor has twice the radius and twice the length of the first resistor. Which of the following statements is correct?', '["The resistors have the same resistance.","The resistors experience the same potential drop.","The resistors dissipate the same amount of power.","The resistors have the same current.","The equivalent resistance of the two resistors is equal to 1.5R2."]'::jsonb, '(D) Recalling that the same current flows through elements in series, you could recognize that choice (D) is correct without paying attention to the details of the problem. The other choices are incorrect for the following reasons. The resistance of a cylindrical resistor is given by the equation R = \rhol/A. Because the second resistor has twice the length and four times the area compared to the first resistor, it has half the resistance of the first resistor, eliminating choice (A). The voltage across the resistors, given by V = IR, is different because the two resistors share the same current but have different resistances, eliminating choice (B). Similarly, power can be expressed as P = I2R, and because the resistors have the same current and different resistances, they dissipate different amounts of power, eliminating choice (D). Finally, R2 is half of R1 (as discussed above), and because resistors in series add, the equivalent resistance is equal to Req = 1.5R1 = 3R2, so choice (E) is incorrect.'),
  ('ap-mock-physc-em-full-2_q21', 'ap-mock-physc-em-full-2', 21, false, 'A', 'Practice Test 2 – E&M', 'medium', 'In a Wheatstone bridge circuit with four resistors R1, R2, R3, and R4 arranged in two parallel branches (branch 1 has R1 and R2 in series; branch 2 has R3 and R4 in series), the potential at the junction between R1 and R2 equals the potential at the junction between R3 and R4. Which condition must be satisfied?', '["R1 / R2 = R3 / R4","R1 R2 = R3 R4","R1 + R2 = R3 + R4","R1 - R2 = R3 - R4","R1 / R4 = R2 / R3"]'::jsonb, 'For the bridge to be balanced (equal potentials at the two internal nodes), the voltage drop across R1 must equal the voltage drop across R3: I1 R1 = I2 R3, and the voltage drop across R2 must equal that across R4: I1 R2 = I2 R4. Dividing the two equations yields R1 / R2 = R3 / R4 (the classic Wheatstone bridge balance condition).'),
  ('ap-mock-physc-em-full-2_q22', 'ap-mock-physc-em-full-2', 22, false, 'C', 'Practice Test 2 – E&M', 'medium', 'If each of the capacitors in the network shown has a capacitance of C, what is the equivalent capacitance of the network?', '["C/9","C/3","C","3C","9C"]'::jsonb, '(C) Each set of three capacitors in series has an equivalent capacitance of C/3. Because capacitors in parallel add, the combination of these three equivalent capacitors (each with a capacitance of C/3) in parallel produces a network with an equivalent capacitance of C.'),
  ('ap-mock-physc-em-full-2_q23', 'ap-mock-physc-em-full-2', 23, false, 'D', 'Practice Test 2 – E&M', 'medium', 'What voltage would have to be imposed across the entire network shown in question 26 for the voltage across any of the capacitors to be V?', '["V/9","V/3","V","3V","9V"]'::jsonb, '(D) Imagine charging the capacitor network. Equal amounts of charge would flow through the three branches of the network, causing equal amounts of charge to build up on every one of the nine capacitors. Therefore, for the voltage of one capacitor to be V, the voltage of every capacitor in the network must be V. When the voltage across each capacitor is V, what is the voltage across the entire network? To calculate the voltage across the network, we can imagine traversing one branch and summing the voltage jumps, as in a Kirchhoff’s loop equation. Because the capacitors have the same polarity, their voltages sum, causing the voltage across the branch (and thus the network) to be 3V.'),
  ('ap-mock-physc-em-full-2_q24', 'ap-mock-physc-em-full-2', 24, false, 'B', 'Practice Test 2 – E&M', 'medium', 'The gaussian “unit cube” shown lies in a region where the electric field is constant and parallel to the z-axis: . Which of the following choices lists the outward flux through sides 1 through 6, respectively?', '["0, 0, −E, 0, +E, 0","0, 0, +E, 0, −E, 0","0, 0, +E, 0, +E, 0","0, 0, −E, 0, −E, 0","none of the above"]'::jsonb, '(B) Sides 1, 2, 4, and 6 are parallel to the electric field, so the electric flux through them is zero. Sides 3 and 5 are perpendicular to the field, so the magnitude of the flux passing through each of these faces is equal to the area (which is 1) multiplied by the field, E. Because the field points in the positive z-direction, it enters the cube at side 5 (yielding negative outward flux) and leaves the cube at side 3 (yielding positive outward flux).'),
  ('ap-mock-physc-em-full-2_q25', 'ap-mock-physc-em-full-2', 25, false, 'C', 'Practice Test 2 – E&M', 'medium', 'You have three identical capacitors you are using to design an equivalent capacitor that will be used to store energy for a camera flash, as shown. Charging time is defined as the amount of time required to reach 90% of the maximum energy. Rank the networks in order from least to greatest charging time.', '["I, II, III, IV","IV, III, II, I","I, III, II, IV","IV, II, III, I","I, (II = III), IV I) II) III) IV)"]'::jsonb, '(C) The energy stored in a capacitor can be expressed in the form U = Q2/2C. Therefore, the amount of time required for a capacitor to reach 90% of its maximum energy is equal to the amount of time required to reach 90% of its maximum Q2 value (because C is fixed for any given capacitor). The circuit with the smaller time constant (smaller \tau = RC), and thus the smaller equivalent capacitance, reaches the 90% value more quickly. Therefore, ordering the networks from least to greatest charging time is simply a matter of ordering them from least to greatest equivalence capacitance. The equivalent capacitances of networks I through IV are and 3C, respectively.'),
  ('ap-mock-physc-em-full-2_q26', 'ap-mock-physc-em-full-2', 26, false, 'C', 'Practice Test 2 – E&M', 'medium', 'Considering the situation introduced in the last problem, rank order the capacitor networks in terms of the energy stored when fully charged. (Assume that the capacitor networks are connected to the same circuit, with a fixed voltage.)', '["I, II, III, IV","IV, III, II, I","I, III, II, IV","IV, II, III, I","I, (II = III), IV"]'::jsonb, '(C) From the equation , networks with higher equivalent capacitance store more energy when connected to the same voltage. Therefore, ordering the capacitors from least to greatest energy is equivalent to ordering them from least to greatest capacitance. This ordering is the same as in question 29, choice (C).'),
  ('ap-mock-physc-em-full-2_q27', 'ap-mock-physc-em-full-2', 27, false, 'E', 'Practice Test 2 – E&M', 'medium', 'What is the rate at which thermal energy is produced in the resistors shown?', '["(B) IV","Directly downward toward the bottom of the page","2IV","4IV","none of the above"]'::jsonb, '(E) What is the current through the circuit? A Kirchhoff’s loop equation for the circuit (moving in the clockwise direction and choosing positive current clockwise) is V − IR − V − IR = 0, which simplifies to 2IR = 0. Therefore, the current around the circuit is zero, which is not surprising because the two identical batteries are connected so as to oppose each other. Thus, the power dissipated in each of the resistors is zero, and absolutely no thermal energy is produced in the circuit.'),
  ('ap-mock-physc-em-full-2_q28', 'ap-mock-physc-em-full-2', 28, false, 'B', 'Practice Test 2 – E&M', 'medium', 'In the circuit shown, there is initially no current flowing through the inductor. The instant after the switch is closed, what is the current through the battery?', '["V/R1","V/(R1 + R2)","V/(R1 + R3)","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(B) The instant after the switch is closed in an RL circuit, the inductor acts like an open circuit (because the current through the inductor must be continuous and thus initially zero). Therefore, the equivalent resistance is R1 + R2, and the current is calculated using Ohm’s law with the result given by choice (B). Elimination approach: Even if you have forgotten about RL circuits, you could eliminate enough choices to make a good guess. First, because no circuit elements block the flow of current through resistors R1 and R2, these resistors determine the current and are expected to show up in the final answer, eliminating choices (A) and (C). The denominator of choice (E) has mixed units (Ω + Ω−1), so it must be incorrect. This leaves us to guess between choices (B) and (D).'),
  ('ap-mock-physc-em-full-2_q29', 'ap-mock-physc-em-full-2', 29, false, 'D', 'Practice Test 2 – E&M', 'medium', 'Referring to the circuit shown in question 32, after the circuit has reached equilibrium, what is the current through the battery?', '["V/R1","V/(R1 + R2)","V/(R1 + R3)","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(D) At equilibrium the inductor acts like a short circuit, so to calculate the current we simply ignore the inductor, calculate the equivalent resistance, and apply Ohm’s law. To calculate the equivalent resistance, note that R2 and R3 are in parallel with each other, so their equivalent resistance together is Because these resistors are in series with R1, the equivalent resistance of the entire circuit is Applying Ohm’s law yields the current given in choice (D).'),
  ('ap-mock-physc-em-full-2_q30', 'ap-mock-physc-em-full-2', 30, false, 'B', 'Practice Test 2 – E&M', 'medium', 'A solid conducting sphere of radius R carries a net positive charge +Q in electrostatic equilibrium. Taking electric potential to be zero at infinity (V = 0 at r = infinity), which of the following correctly describes the electric potential V(r) as a function of radial distance r from the center?', '["V(r) is zero inside the sphere and proportional to 1/r outside","V(r) is constant and equal to k Q / R for all r <= R, and proportional to k Q / r for r >= R","V(r) increases linearly from 0 at the center to k Q / R at the surface","V(r) is proportional to 1/r^2 both inside and outside the sphere","V(r) is constant throughout all space"]'::jsonb, 'Because the sphere is a conductor in electrostatic equilibrium, the electric field inside is zero (E = 0 for r <= R). Since E = -dV/dr, the potential must be constant throughout the volume of the conductor and equal to its surface value: V(r) = k Q / R for r <= R. Outside the sphere (r >= R), Gauss''s law gives E(r) = k Q / r^2, so integrating from infinity yields V(r) = k Q / r.'),
  ('ap-mock-physc-em-full-2_q31', 'ap-mock-physc-em-full-2', 31, false, 'A', 'Practice Test 2 – E&M', 'medium', 'For the solid conducting sphere in the previous question, which of the following correctly describes the electric field magnitude E(r) as a function of radial distance r from the center?', '["E(r) = 0 for r < R, and E(r) = k Q / r^2 for r > R","E(r) is constant and non-zero for r < R","E(r) increases linearly with r for r < R","E(r) is proportional to 1/r for all r","E(r) is non-zero at the center and decreases to 0 at the surface"]'::jsonb, 'In electrostatic equilibrium, charges reside entirely on the outer surface of a conductor, so the electric field inside the conducting material is identically zero: E(r) = 0 for r < R. Outside the sphere (r > R), Gauss''s law with a spherical Gaussian surface enclosing charge Q yields E(4 pi r^2) = Q / epsilon_0 ==> E(r) = k Q / r^2.'),
  ('ap-mock-physc-em-full-2_q32', 'ap-mock-physc-em-full-2', 32, false, 'C', 'Ch14: Magnetic Fields', 'medium', 'Two circular loops of wire of equal radius R carry equal currents I. One loop lies in the xy-plane carrying current counterclockwise as seen from the positive z-axis, producing a magnetic field B_z k at the origin. The second loop lies in the xz-plane carrying current that produces a magnetic field -B_y j at the origin. What is the direction of the net magnetic field at the origin?', '["Along the positive x-axis","In the xy-plane at 45 degrees to the axes","In the yz-plane along the direction -j + k","Along the negative z-axis","Zero net magnetic field"]'::jsonb, 'By the principle of superposition, the net magnetic field at the origin is B_net = B1 + B2 = -B_y j + B_z k. Because the loops have equal radii and carry equal currents, |B_y| = |B_z| = mu_0 I / (2R). The net field lies in the yz-plane and is parallel to the vector -j + k.'),
  ('ap-mock-physc-em-full-2_q33', 'ap-mock-physc-em-full-2', 33, false, 'C', 'Ch14: Magnetic Fields', 'medium', 'A long coaxial cable consists of an inner solid cylindrical conductor of radius a and an outer thin cylindrical shell of radius b (with a < b). Equal currents I flow in opposite directions through the inner and outer conductors. What is the magnetic field magnitude B(r) in the space between the conductors (a < r < b)?', '["Zero","mu_0 I r / (2 pi a^2)","mu_0 I / (2 pi r)","mu_0 I / (2 pi b)","mu_0 I / (4 pi r^2)"]'::jsonb, 'Apply Ampere''s law oint B * dl = mu_0 I_enc around a circular path of radius r (with a < r < b). The path encloses only the inner conductor carrying total current I. Thus, B(2 pi r) = mu_0 I ==> B(r) = mu_0 I / (2 pi r).'),
  ('ap-mock-physc-em-full-2_q34', 'ap-mock-physc-em-full-2', 34, false, 'D', 'Ch14: Magnetic Fields', 'medium', 'A uniform magnetic field of magnitude B points out of the page in the region x > 0, and a uniform magnetic field of equal magnitude points into the page in the region x < 0, as shown in Figure 14.15. A particle with charge +q and mass m initially at the origin moves to the right with speed v. At which of the following points does the particle cross the y- axis? Figure 14.15', '["6 mv/qB","3 mv/qB","−3 mv/qB","−6 mv/qB","The particle will never cross the y-axis."]'::jsonb, '(D) The particle’s velocity is perpendicular to the magnetic field, so it moves in a circular path. The radius of the path can be calculated by equating the magnetic force to the centripetal force, qvB = mv2/r, to obtain r = mv/qB. Careful examination of the particle’s path reveals that it moves in the path shown in Figure 14.25. Therefore, it passes through the y-axis at multiples of −2r = −2 mv/qB. Figure 14.25')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-mock-physc-em-full-2_q35', 'ap-mock-physc-em-full-2', 35, false, 'D', 'Ch14: Magnetic Fields', 'medium', 'Two infinitely long wires carry equal currents of I into the page, as shown in Figure 14.24.', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(D) The particle’s velocity is perpendicular to the magnetic field, so it moves in a circular path. The radius of the path can be calculated by equating the magnetic force to the centripetal force, qvB = mv2/r, to obtain r = mv/qB. Careful examination of the particle’s path reveals that it moves in the path shown in Figure 14.25. Therefore, it passes through the y-axis at multiples of −2r = −2 mv/qB. Figure 14.25'),
  ('ap-mock-physc-em-full-2_q36', 'ap-mock-physc-em-full-2', 36, false, 'E', 'Ch14: Magnetic Fields', 'medium', 'An electron moves in a magnetic field along a certain path at a constant speed. The magnetic field does no work on the electron if', '["the path is parallel to the magnetic field so that the magnetic force is zero","the path is perpendicular to the field so that the electron moves in uniform circular motion","the magnetic field is constant in space so that there is no induced electric field","the electron must move along a magnetic field line","None of the above conditions are necessary."]'::jsonb, '(E) The magnetic force is always perpendicular to velocity, so it can never do work (recall that dW = F \cdot  d r).'),
  ('ap-mock-physc-em-full-2_q37', 'ap-mock-physc-em-full-2', 37, false, 'C', 'Ch14: Magnetic Fields', 'medium', 'Figure 14.16 shows a cross section of a coaxial cable. A current of 1.0 A passes through the center of the cable, while a uniform current density of 1.0 A/m2 comes out of the page through the outer sheath of the cable. At what distance from the center of the cable is the magnetic field equal to zero? Figure 14.16', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","(D) The magnetic field is zero but not at the radii listed above.","Independent of the mass and charge distribution","The magnetic field is never zero except at infinity."]'::jsonb, '(C) According to Ampere’s law, the magnetic field is zero when the enclosed current is zero. For the inward current to balance the outward current, the outward current enclosed must equal 1.0 A. The enclosed outward current is 1.0 A when the Amperian path encloses an area of 1.0 m2 of the sheath (because the current density is 1.0 A/m2). Geometrically, 1 = \pir2 − \pi(1.0)2. Solving this equation for r yields choice (C).'),
  ('ap-mock-physc-em-full-2_q38', 'ap-mock-physc-em-full-2', 38, false, 'A', 'Ch14: Magnetic Fields', 'medium', 'A charged particle moves in uniform circular motion due to a magnetic field perpendicular to the plane of its motion. Which of the graphs in Figure 14.17 illustrates the relationship between the charge’s velocity and the radius of its motion? (Assume that other variables, such as the magnetic field strength and the mass of the particle, are held constant.) Figure 14.17', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(A) The magnetic force provides the centripetal force: Thus, v is a linear function of r that passes through the origin.'),
  ('ap-mock-physc-em-full-2_q39', 'ap-mock-physc-em-full-2', 39, false, 'B', 'Ch14: Magnetic Fields', 'medium', 'A particle with a charge −q and mass m is moving with speed v through a mass spectrometer that contains a uniform outward magnetic field as shown in Figure 14.18. What is the magnitude and direction of the electric field required so that the net force on this particle is zero? Figure 14.18', '["E = vB, with a direction upward","E = vB, with a direction downward","E = B/v, with a direction upward","E = B/v, with a direction downward","E = B/v, with a direction into the page"]'::jsonb, '(B) For the magnetic force to cancel the electric force, |qv \times  B| = qvB = qE, which simplifies to E = vB. The direction of the magnetic force on the charge is downward (opposite the direction indicated by the right- hand rule because the charge is negative). The electric force must point in the opposite direction, upward. However, since the charge is negative, in order to produce an upward electric force the field must point downward.'),
  ('ap-mock-physc-em-full-2_q40', 'ap-mock-physc-em-full-2', 40, false, 'A', 'Ch14: Magnetic Fields', 'medium', 'Consider current passing through a short segment of a circular loop of wire as shown in Figure 14.19. The current passing through the rest of the circular wire produces a magnetic field at the location of the short segment, resulting in a magnetic force on the current-carrying segment of wire. Which of the following statements about this force is true? Figure 14.19', '["The force is to the right.","The force is to the left.","The magnetic field is zero because of symmetry, so there is no force.","The force is pointing out of the page.","The force is pointing into the page."]'::jsonb, '(A) First, imagine dividing the loop into little segments and considering the magnetic field due to each segment (using the right- hand rule for the direction of a magnetic field produced by a current- carrying wire or using the right-hand rule embedded in Biot-Savart’s law). Because each segment produces a magnetic field pointing out of the page at the segment of wire, the net magnetic field points out of the page. Using the right-hand rule again, the force this field exerts on the segment of wire is to the right. In general, each segment of the loop feels a force directed radially outward due to the rest of the loop.'),
  ('ap-mock-physc-em-full-2_q41', 'ap-mock-physc-em-full-2', 41, false, 'D', 'Ch14: Magnetic Fields', 'medium', 'Two wires located along the x-axis carry equal currents into the page as shown in Figure 14.20. Which of the graphs shows the y-component of the magnetic field along the x-axis? Figure 14.20', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(D) At the origin, the fields due to the two wires cancel and the net field is zero, eliminating choices (A) and (B). As each wire is approached from the right, the field decreases to negative infinity, and as each wire is approached from the left, the field increases to positive infinity. This is consistent only with choice (D).'),
  ('ap-mock-physc-em-full-2_q42', 'ap-mock-physc-em-full-2', 42, false, 'C', 'Ch14: Magnetic Fields', 'medium', 'A particle moves through an electric field as shown in Figure 14.21. What is the direction of the magnetic field needed to ensure that the particle experiences zero net force? Figure 14.21', '["into the page if the particle is positively charged, out of the page if the particle is negatively charged","into the page if the particle is negatively charged, out of the page if the particle is positively charged","into the page, irrespective of the particle’s charge","out of the page, irrespective of the particle’s charge","to the left, irrespective of the particle’s charge"]'::jsonb, '(C) Changing the sign of the charge of the particle changes the direction of both the electric and the magnetic forces, two changes that cancel each other out, so that in either case the magnetic field must point into the page in order to cancel out the electric field. (If the magnetic field is into the page, a positive charge will feel an electric force to the right and a magnetic force to the left. Alternatively, a negative charge will feel forces in the opposite directions.)'),
  ('ap-mock-physc-em-full-2_q43', 'ap-mock-physc-em-full-2', 43, false, 'B', 'Ch14: Magnetic Fields', 'medium', 'Three loops of equal radii carrying equal currents lie on planes parallel to the yz-plane as shown in Figure 14.22. Two of the loops are located equal distances d from the yz-plane as shown, while the third loop lies on the yz-plane. In what direction is the net magnetic field at the origin? Figure 14.22', '["The magnetic field is zero because of symmetry.","The magnetic field is in the +x-direction.","The magnetic field is in the −x-direction.","The magnetic field lies in the xz-plane.","The magnetic field lies in the xy-plane. Free-Response Questions"]'::jsonb, '(B) The two loops lying off the yz-plane produce equal and opposite fields which cancel each other. (The loop at x = −d produces a magnetic field in the −x-direction, while the loop at x = d produces a magnetic field in the +x-direction.) The net field is therefore equal to the field produced by the middle loop, which produces a field in the +x- direction. Free-Response 1. Given the cylindrical symmetry of this problem, Ampere’s Law is the way to go. As in Examples 14.4 and 14.5, the field lines will be concentric circles centered on the center of the inner conductor. The Amperian path will be a circle of radius r. The left-hand side of Ampere’s law for this path will be ∮B \cdot  dl = B(2\pir). All we need to do is to figure out the direction and magnitude of the enclosed current to solve each part of the problem. (a) The current density in the inner conductor is , positive because the current is flowing out of the page. Thus, the enclosed current is , and Ampere’s law says: The field is counterclockwise because the current is positive, pointing out of the page. (b) Now the enclosed current is the full value I, pointing out of the page, i.e., positive. Ampere’s law yields , just like a thin current- carrying wire. The field is counterclockwise. (c) This is the trickiest part of this problem as we are enclosing the entire inner conductor but only a portion of the outer conductor. First, we need to find the current density in the outer conductor. The cross- sectional area of the outer conductor is and the current density is , negative because the current flows into the page. The enclosed current is then given by I enclosed . Applying Ampere’s law we find: The field is positive, i.e., counterclockwise because the enclosed current is positive. (d) The enclosed current is now zero so the field is zero. 2. (a) The magnetic field due to an infinitely long wire is equal in magnitude to B = \mu0I/2\pir and has a direction indicated by the right-hand rule. The magnetic field along the x-axis is a superposition of the magnetic fields due to both of the wires, as shown in Figure 14.26. Figure 14.26 Adding the two vectors yields (b) This expression is given in Figure 14.27. In sketching the curve, first we note that the function has odd symmetry; mathematically, B(−x) = −B(x). Because x is raised to a greater power in the denominator than in the numerator, the function asymptotically approaches zero as x approaches positive or negative infinity. Finally, we note that the function is zero at the origin and that it passes through the origin with a negative slope. Figure 14.27 Note: A graphing calculator can also be used to sketch this curve: Simply graphing the function f(x) = −x/(1 + x2) is sufficient to get an idea of how this curve looks. (c) The magnetic force is always perpendicular to the velocity, so it never does any work. (Thus, the magnetic force can change only an object’s direction, not its speed.) Therefore, no work need be done by an external force to move the charge from infinity to the origin.'),
  ('ap-mock-physc-em-full-2_q44', 'ap-mock-physc-em-full-2', 44, false, 'A', 'Ch15: Electromagnetism', 'medium', 'An external force pushes a square loop of wire through a region of constant magnetic field as shown in Figure 15.9. Which of the following is a plot of the magnetic flux as a function of the position of the loop? Figure 15.9', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(A) The magnetic flux is proportional to the portion of the loop’s area that is exposed to the magnetic field. This area increases linearly as the loop enters the field, remains constant while the loop is completely within the field, and decreases as the loop exits the field.'),
  ('ap-mock-physc-em-full-2_q45', 'ap-mock-physc-em-full-2', 45, false, 'C', 'Ch15: Electromagnetism', 'medium', 'A planar loop of wire with area A and resistance R is positioned perpendicular to a uniform magnetic field directed into the page. If the magnitude of the magnetic field decreases at a constant rate dB/dt = -alpha, what is the direction and magnitude of the induced current in the loop?', '["Clockwise with magnitude alpha A / (2 R)","Counterclockwise with magnitude alpha A / R","Clockwise with magnitude alpha A / R","Counterclockwise with magnitude alpha A R","Zero"]'::jsonb, 'By Faraday''s law, EMF = A alpha. By Lenz''s law, because inward flux is decreasing, the induced current must create an inward magnetic field, requiring a clockwise current. Magnitude is I = EMF / R = alpha A / R.'),
  ('ap-topic-physc-em-mastery_q1', 'ap-topic-physc-em-mastery', 1, false, 'A', 'Coulomb''s Law Scaling Factor', 'easy', 'What will happen to the magnitude of electric force between two particles if the distance between them is doubled and each charge is tripled?', '["Multiplied by a factor of $9/4$","Multiplied by a factor of $3/2$","Multiplied by a factor of $3/4$","Multiplied by a factor of $9/2$","Multiplied by a factor of $6/4$"]'::jsonb, '(A) From Coulomb''s Law, $F = \frac{1}{4\pi\varepsilon_0}\frac{q_1 q_2}{r^2}$. Tripling both charges scales the numerator by $3 \times 3 = 9$. Doubling the separation distance scales the denominator by $2^2 = 4$. The resulting electrostatic force is multiplied by a factor of $9/4$.'),
  ('ap-topic-physc-em-mastery_q2', 'ap-topic-physc-em-mastery', 2, false, 'C', 'Negative Charge Kinematics in Electric Field', 'medium', 'A particle ($m = 10^{-10}\text{ kg}, q = -5 \times 10^{-13}\text{ C}$) starts at rest inside a uniform electric field $E = 50\text{ N/C}$ directed toward the left in a $1\text{-m}$ square region, positioned $70\text{ cm}$ from the left edge and $30\text{ cm}$ from the right edge. How long will it take to escape the field?', '["$1.10\\text{ s}$","$1.23\\text{ s}$","$1.55\\text{ s}$","$2.31\\text{ s}$","$2.59\\text{ s}$"]'::jsonb, '(C) Because the charge is negative, the electric force acts to the right, opposite to $\vec{E}$. The distance to escape out the right side is $d = 30\text{ cm} = 0.30\text{ m}$.
